def normalize_issuer_name(
    company_name
):

    if pd.isna(
        company_name
    ):

        return ""


    name = str(
        company_name
    ).lower()


    # --------------------------------------------------------
    # Remove parenthetical share-class descriptions
    # --------------------------------------------------------

    name = re.sub(

        r"\(\s*class\s+[a-z0-9]+\s*\)",

        " ",

        name,

        flags=re.IGNORECASE,

    )


    # --------------------------------------------------------
    # Remove non-parenthetical share-class descriptions
    # --------------------------------------------------------

    name = re.sub(

        r"\bclass\s+[a-z0-9]+\b",

        " ",

        name,

        flags=re.IGNORECASE,

    )


    # --------------------------------------------------------
    # Remove common legal suffixes
    # --------------------------------------------------------

    legal_suffixes = [

        r"\bincorporated\b",
        r"\bcorporation\b",
        r"\bcompany\b",
        r"\binc\b",
        r"\bcorp\b",
        r"\bltd\b",
        r"\blimited\b",
        r"\bplc\b",

    ]


    for suffix in legal_suffixes:

        name = re.sub(

            suffix,

            " ",

            name,

            flags=re.IGNORECASE,

        )


    # --------------------------------------------------------
    # Remove punctuation
    # --------------------------------------------------------

    name = re.sub(

        r"[^a-z0-9]+",

        " ",

        name,

    )


    # --------------------------------------------------------
    # Normalize whitespace
    # --------------------------------------------------------

    name = re.sub(

        r"\s+",

        " ",

        name,

    ).strip()


    return name


