# ============================================================
# 21. TTM HELPERS
# ============================================================

def f2_ttm_sum(
    dataframe,
    column,
):

    if (

        dataframe.empty

        or

        column not in dataframe.columns

    ):

        return np.nan


    values = (

        pd.to_numeric(

            dataframe[
                column
            ],

            errors="coerce",

        )

        .dropna()

    )


    if len(values) < 4:

        return np.nan


    return float(

        values.iloc[:4]
        .sum()

    )


def f2_latest_value(
    dataframe,
    column,
):

    if (

        dataframe.empty

        or

        column not in dataframe.columns

    ):

        return np.nan


    values = (

        pd.to_numeric(

            dataframe[
                column
            ],

            errors="coerce",

        )

        .dropna()

    )


    if values.empty:

        return np.nan


    return float(
        values.iloc[0]
    )


def f2_ttm_or_annual(
    quarterly_company,
    annual_company,
    column,
):

    value = f2_ttm_sum(

        quarterly_company,
        column,

    )


    if pd.notna(value):

        return value


    return f2_latest_value(

        annual_company,
        column,

    )


def f2_capex_source(
    quarterly_company,
    annual_company,
):

    if (

        not quarterly_company.empty

        and

        "capital_expenditure_source"
        in quarterly_company.columns

    ):

        sources = (

            quarterly_company[
                "capital_expenditure_source"
            ]

            .iloc[:4]

            .dropna()

        )


        if len(sources) >= 4:

            unique_sources = set(
                sources
            )


            if unique_sources == {
                "DIRECT_STATEMENT"
            }:

                return "DIRECT_STATEMENT"


            if unique_sources == {
                "INFERRED_FROM_REPORTED_FCF_MINUS_CFO"
            }:

                return (
                    "INFERRED_FROM_REPORTED_FCF_MINUS_CFO"
                )


            return "MIXED_QUARTERLY_SOURCES"


    if (

        not annual_company.empty

        and

        "capital_expenditure_source"
        in annual_company.columns

    ):

        values = (

            annual_company[
                "capital_expenditure_source"
            ]

            .dropna()

        )


        if not values.empty:

            return (
                "ANNUAL_FALLBACK_"
                +
                str(
                    values.iloc[0]
                )
            )


    return "MISSING"


