def f2_route_sanity(
    row
):

    original = str(

        row.get(

            "valuation_model_family_original",

            row.get(
                "valuation_model_family",
                ""
            )

        )

    )


    sector = str(

        row.get(
            "sector_ticker",
            ""
        )

    )


    industry = str(

        row.get(
            "yahoo_industry",
            ""
        )

    ).lower()


    operating_financial_keywords = [

        "credit services",
        "financial data",

        "stock exchange",
        "financial exchanges",

        "software",
        "information services",

        "payment",

    ]


    if (

        sector == "XLF"

        and

        any(

            keyword in industry

            for keyword
            in operating_financial_keywords

        )

    ):

        target = "FCFF_BLEND"


        if original != target:

            return pd.Series({

                "valuation_model_family_effective":
                    target,

                "valuation_route_override":
                    True,

                "valuation_route_override_reason":
                    (
                        "Non-balance-sheet operating business "
                        "inside Financials taxonomy"
                    ),

            })


    return pd.Series({

        "valuation_model_family_effective":
            original,

        "valuation_route_override":
            False,

        "valuation_route_override_reason":
            "",

    })


