# ============================================================
# 32. ECONOMIC SHARE COUNT
# ============================================================

def f2_valid_positive_number(
    value
):

    try:

        return (

            pd.notna(value)

            and

            _f_isfinite(
                float(value)
            )

            and

            float(value) > 0

        )

    except Exception:

        return False


def f2_choose_economic_share_count(
    row
):

    summary = row.get(
        "shares_outstanding",
        np.nan
    )


    diluted = row.get(
        "statement_diluted_average_shares",
        np.nan
    )


    ordinary = row.get(
        "statement_ordinary_shares",
        np.nan
    )


    listed_sum = row.get(
        "listed_share_class_sum",
        np.nan
    )


    implied = row.get(
        "market_cap_implied_shares",
        np.nan
    )


    multi_class = bool(

        row.get(
            "multiple_share_class_entity",
            False
        )

    )


    if multi_class:

        candidates = [

            float(value)

            for value in [

                diluted,
                ordinary,
                listed_sum,
                implied,

            ]

            if f2_valid_positive_number(
                value
            )

        ]


        if len(candidates) >= 2:

            return pd.Series({

                "economic_diluted_shares":
                    float(
                        np.median(
                            candidates
                        )
                    ),

                "economic_share_count_source":
                    "MULTICLASS_RECONCILED_MEDIAN",

            })


        if len(candidates) == 1:

            return pd.Series({

                "economic_diluted_shares":
                    candidates[0],

                "economic_share_count_source":
                    "MULTICLASS_SINGLE_ALTERNATIVE",

            })


        if f2_valid_positive_number(
            summary
        ):

            return pd.Series({

                "economic_diluted_shares":
                    float(summary),

                "economic_share_count_source":
                    "MULTICLASS_SUMMARY_LAST_RESORT",

            })


        return pd.Series({

            "economic_diluted_shares":
                np.nan,

            "economic_share_count_source":
                "MISSING",

        })


    if (

        f2_valid_positive_number(summary)

        and

        f2_valid_positive_number(diluted)

    ):

        ratio = (

            float(diluted)
            /
            float(summary)

        )


        if 0.75 <= ratio <= 1.25:

            return pd.Series({

                "economic_diluted_shares":
                    max(
                        float(summary),
                        float(diluted),
                    ),

                "economic_share_count_source":
                    "MAX_CURRENT_AND_DILUTED",

            })


    for value, source in [

        (
            summary,
            "SUMMARY_CURRENT_SHARES",
        ),

        (
            diluted,
            "STATEMENT_DILUTED_SHARES",
        ),

        (
            ordinary,
            "STATEMENT_ORDINARY_SHARES",
        ),

        (
            implied,
            "MARKET_CAP_IMPLIED",
        ),

    ]:

        if f2_valid_positive_number(
            value
        ):

            return pd.Series({

                "economic_diluted_shares":
                    float(value),

                "economic_share_count_source":
                    source,

            })


    return pd.Series({

        "economic_diluted_shares":
            np.nan,

        "economic_share_count_source":
            "MISSING",

    })


