def f2_share_count_spread(
    row
):

    values = []


    for column in [

        "shares_outstanding",
        "statement_diluted_average_shares",
        "statement_ordinary_shares",
        "listed_share_class_sum",
        "market_cap_implied_shares",

    ]:

        value = row.get(
            column,
            np.nan
        )


        if f2_valid_positive_number(
            value
        ):

            values.append(
                float(value)
            )


    if len(values) < 2:

        return np.nan


    return float(

        max(values)
        /
        min(values)

    )


VALUATION_CURRENT_INPUTS[
    "share_count_source_spread_ratio"
] = (

    VALUATION_CURRENT_INPUTS

    .apply(

        f2_share_count_spread,

        axis=1,

    )

)


