# ============================================================
# 33A. SECURITY-CURRENCY / LISTED-UNIT RECONCILIATION
# ============================================================
#
# Financial statements can be reported in a different currency from the
# listed security (e.g. a USD-traded ADR backed by TWD financials).  The
# valuation engine must therefore: 
#   1) value the enterprise/equity in the financial-statement currency;
#   2) translate that equity value into the listed security's price currency;
#   3) divide by LISTED security units (ADR/receipt/share units), not blindly
#      by the issuer's underlying ordinary-share count.
#
# market_cap/current_price is the preferred listed-unit reconciliation when
# currencies differ because both inputs are quoted for the listed security.
# Explicit ADR metadata remains an audit/fallback control.
# ============================================================

F2_SECURITY_OVERRIDES = (
    CONFIG.get("valuation", {})
    .get("security_overrides", {})
    if isinstance(globals().get("CONFIG", {}), dict)
    else {}
)

# Defensive canonical currency labels.
for _currency_col in ["currency", "financial_currency"]:
    if _currency_col not in VALUATION_CURRENT_INPUTS.columns:
        VALUATION_CURRENT_INPUTS[_currency_col] = np.nan
    VALUATION_CURRENT_INPUTS[_currency_col] = (
        VALUATION_CURRENT_INPUTS[_currency_col]
        .astype("string")
        .str.upper()
        .str.strip()
        .replace({"<NA>": pd.NA, "NAN": pd.NA, "NONE": pd.NA, "": pd.NA})
    )


def f2_security_override(ticker):
    raw = F2_SECURITY_OVERRIDES.get(str(ticker).upper(), {})
    return raw if isinstance(raw, dict) else {}


def f2_fetch_fx_to_price(financial_currency, price_currency):
    """Return price-currency units per 1 financial-currency unit.

    Example: TWD financials / USD-listed ADR -> about 0.03 USD per TWD.
    Yahoo FX symbols are tried in both directions and aligned to the current
    MARKET_AS_OF_DATE.  The result is cached for the current run.
    """
    fin = str(financial_currency or "").upper().strip()
    px = str(price_currency or "").upper().strip()
    if not fin or fin in {"NAN", "NONE", "<NA>"}:
        return np.nan, "MISSING_FINANCIAL_CURRENCY", None
    if not px or px in {"NAN", "NONE", "<NA>"}:
        return np.nan, "MISSING_PRICE_CURRENCY", None
    if fin == px:
        return 1.0, "IDENTITY", None

    cache = globals().setdefault("_F2_FX_CACHE", {})
    key = (fin, px, str(pd.Timestamp(MARKET_AS_OF_DATE).date()))
    if key in cache:
        return cache[key]

    cutoff = pd.Timestamp(MARKET_AS_OF_DATE).normalize()
    start = cutoff - pd.Timedelta(days=14)
    # yfinance's end date is exclusive. Use cutoff + 1 day so the FX
    # observation never looks past MARKET_AS_OF_DATE.
    end = cutoff + pd.Timedelta(days=1)
    attempts = [
        (f"{fin}{px}=X", False),   # direct: px per fin
        (f"{px}{fin}=X", True),    # inverse: fin per px
    ]
    errors = []
    for symbol, invert in attempts:
        try:
            hist = yf.Ticker(symbol).history(
                start=start.strftime("%Y-%m-%d"),
                end=end.strftime("%Y-%m-%d"),
                auto_adjust=False,
            )
            if hist is None or hist.empty or "Close" not in hist.columns:
                raise RuntimeError("empty FX history")
            close = pd.to_numeric(hist["Close"], errors="coerce").dropna()
            if close.empty:
                raise RuntimeError("no finite FX close")
            # yfinance may return tz-aware dates. Normalize without timezone and
            # enforce an as-of cutoff so valuation cannot use future FX.
            try:
                _fx_idx = pd.to_datetime(close.index)
                if getattr(_fx_idx, "tz", None) is not None:
                    _fx_idx = _fx_idx.tz_localize(None)
                _asof_mask = _fx_idx.normalize() <= cutoff
                close = close.loc[_asof_mask]
            except Exception:
                pass
            if close.empty:
                raise RuntimeError("no FX close on or before valuation cutoff")
            rate_raw = float(close.iloc[-1])
            if not np.isfinite(rate_raw) or rate_raw <= 0:
                raise RuntimeError(f"invalid FX rate {rate_raw}")
            rate = (1.0 / rate_raw) if invert else rate_raw
            out = (float(rate), "YAHOO_FX", symbol)
            cache[key] = out
            return out
        except Exception as exc:
            errors.append(f"{symbol}:{type(exc).__name__}:{exc}")

    out = (np.nan, "FX_UNAVAILABLE:" + " | ".join(errors), None)
    cache[key] = out
    return out


def f2_currency_unit_reconciliation(row):
    ticker = str(row.get("ticker", "")).upper()
    override = f2_security_override(ticker)
    def _currency_text(value):
        if value is None or pd.isna(value):
            return ""
        text = str(value).upper().strip()
        return "" if text in {"NAN", "NONE", "<NA>"} else text

    px_ccy = _currency_text(row.get("currency"))
    fin_ccy = _currency_text(row.get("financial_currency"))

    # Explicit security metadata is an audit control, not a substitute for
    # dynamic market-cap/listed-unit reconciliation.
    security_type = str(override.get("security_type", "COMMON")).upper()
    expected_px_ccy = str(override.get("expected_price_currency", "")).upper().strip()
    expected_fin_ccy = str(override.get("expected_financial_currency", "")).upper().strip()

    # A security-specific override may fill a genuinely missing vendor field,
    # but it must never silently overwrite a conflicting live value.
    if not px_ccy and expected_px_ccy:
        px_ccy = expected_px_ccy
    if not fin_ccy and expected_fin_ccy:
        fin_ccy = expected_fin_ccy

    currency_override_match = bool(
        (not expected_px_ccy or expected_px_ccy == px_ccy)
        and (not expected_fin_ccy or expected_fin_ccy == fin_ccy)
    )
    underlying_per_listed = override.get("underlying_per_listed_unit", np.nan)
    try:
        underlying_per_listed = float(underlying_per_listed)
    except Exception:
        underlying_per_listed = np.nan

    fx_rate, fx_source, fx_symbol = f2_fetch_fx_to_price(fin_ccy, px_ccy)
    cross_currency = bool(fin_ccy and px_ccy and fin_ccy != px_ccy)

    implied = row.get("market_cap_implied_shares", np.nan)
    economic = row.get("economic_diluted_shares", np.nan)
    share_source = str(row.get("economic_share_count_source", ""))

    _listed = choose_listed_unit_count(
        cross_currency=cross_currency,
        market_cap_implied_units=implied,
        economic_units=economic,
        economic_source=share_source,
        security_type=security_type,
        underlying_per_listed_unit=underlying_per_listed,
    )
    listed_units = _listed["valuation_share_units"]
    listed_source = _listed["valuation_share_unit_source"]

    fx_ready = bool(np.isfinite(fx_rate) and fx_rate > 0)
    units_ready = bool(f2_valid_positive_number(listed_units))
    reconciliation_ready = bool(
        fx_ready and units_ready and currency_override_match
    )

    return pd.Series({
        "price_currency": px_ccy or np.nan,
        "valuation_financial_currency": fin_ccy or np.nan,
        "cross_currency_security": cross_currency,
        "security_type": security_type,
        "underlying_per_listed_unit": underlying_per_listed,
        "currency_override_expected_match": currency_override_match,
        "financial_to_price_fx": fx_rate,
        "financial_to_price_fx_source": fx_source,
        "financial_to_price_fx_symbol": fx_symbol,
        "valuation_share_units": listed_units,
        "valuation_share_unit_source": listed_source,
        "currency_unit_reconciliation_ready": reconciliation_ready,
    })


_F2_CURRENCY_UNIT = VALUATION_CURRENT_INPUTS.apply(
    f2_currency_unit_reconciliation, axis=1
)
