# ===== ORIGINAL NOTEBOOK CELL 60 =====
# ============================================================
# SECTION F — VALUATION ENGINE
# CELL F2A — CAPITAL INVESTMENT LINEAGE + SEC INLINE-XBRL
#            FALLBACK V1.3.0
# ============================================================
#
# Main correction vs V1.2.0:
#
#   SEC comparative-period values are extracted from the
#   INLINE XBRL FACTS themselves rather than from pandas'
#   rendered HTML table cells.
#
# Why:
#
#   SEC HTML tables often contain duplicated presentation
#   columns. Reading the first two numeric cells can therefore
#   accidentally produce:
#
#       current YTD = current YTD
#
#   instead of:
#
#       current YTD / prior comparable YTD
#
# V1.3.0:
#
#   - exact investing-section row matching
#   - inline-XBRL fact extraction
#   - de-duplication by XBRL contextRef
#   - FY + current YTD - prior YTD TTM bridge
#   - raw Yahoo remains first fallback
#   - SEC remains second fallback
#   - no hard-coded company-specific dollar values
#   - circular FCF-minus-CFO CapEx remains prohibited
#
# ============================================================


# ============================================================
# 1. IMPORTS
# ============================================================

from pathlib import Path

import os
import re
import time

import numpy as np
import pandas as pd
import requests

from bs4 import BeautifulSoup


# ============================================================
# 2. VALIDATE F2 BASELINE
# ============================================================

required_f2a_objects = [

    "F2_PASSED",

    "F2_CURRENT_INPUTS_PATH",
    "F2_ANNUAL_PATH",
    "F2_QUARTERLY_PATH",

    "VALUATION_STATEMENT_RAW_DIR",
    "VALUATION_SNAPSHOT_STRING",

    "F2_MODEL_ESSENTIAL_INPUTS",

    "STOCK_MODEL_DIR",
    "STOCK_OUTPUT_DIR",

]


missing_f2a_objects = [

    obj

    for obj in required_f2a_objects

    if obj not in globals()

]


if missing_f2a_objects:

    raise RuntimeError(

        "F2A requires F2 v1.1.2 first. Missing: "
        f"{missing_f2a_objects}"

    )


if not bool(
    F2_PASSED
):

    raise RuntimeError(
        "F2 production gate did not pass."
    )


# ============================================================
# 3. VERSION
# ============================================================

F2A_VERSION = "1.3.0"


# ============================================================
# 4. RELOAD CLEAN F2 BASELINE
# ============================================================
#
# Do NOT inherit previously patched F2A objects from memory.
# ============================================================

F2A_CURRENT_INPUTS = pd.read_parquet(

    F2_CURRENT_INPUTS_PATH

)


F2A_ANNUAL_HISTORY = pd.read_parquet(

    F2_ANNUAL_PATH

)


F2A_QUARTERLY_HISTORY = pd.read_parquet(

    F2_QUARTERLY_PATH

)


for frame in [

    F2A_ANNUAL_HISTORY,
    F2A_QUARTERLY_HISTORY,

]:

    if not frame.empty:

        frame[
            "period_end"
        ] = pd.to_datetime(

            frame[
                "period_end"
            ],

            errors="coerce",

        )


# ============================================================
# 5. FCFF MODEL FAMILIES
# ============================================================

F2A_FCFF_MODELS = {

    "FCFF_BLEND",

    "ENERGY_MIDCYCLE_FCFF",

    "REFINER_MIDCYCLE_FCFF",

    "BIOPHARMA_RISK_ADJUSTED_DCF",

}


F2A_CURRENT_INPUTS[
    "f2a_is_fcff_model"
] = (

    F2A_CURRENT_INPUTS[
        "valuation_model_family"
    ]

    .isin(
        F2A_FCFF_MODELS
    )

)


# ============================================================
# 6. IDENTIFY UNSAFE CAPEX
# ============================================================

capex_source_text = (

    F2A_CURRENT_INPUTS[
        "ttm_capex_source"
    ]

    .fillna("")

    .astype(str)

)


F2A_CURRENT_INPUTS[
    "f2a_circular_capex"
] = (

    capex_source_text

    .str.contains(

        "INFERRED_FROM_REPORTED_FCF_MINUS_CFO",

        regex=False,

    )

)


F2A_CURRENT_INPUTS[
    "f2a_requires_repair"
] = (

    F2A_CURRENT_INPUTS[
        "f2a_is_fcff_model"
    ]

    &

    (

        F2A_CURRENT_INPUTS[
            "f2a_circular_capex"
        ]

        |

        F2A_CURRENT_INPUTS[
            "ttm_capex"
        ]
        .isna()

        |

        (
            F2A_CURRENT_INPUTS[
                "ttm_capex"
            ]
            >=
            0
        )

    )

)


F2A_REPAIR_UNIVERSE = (

    F2A_CURRENT_INPUTS[

        F2A_CURRENT_INPUTS[
            "f2a_requires_repair"
        ]

    ]

    .copy()

    .reset_index(
        drop=True
    )

)


# ============================================================
# 7. INVALIDATE CIRCULAR HISTORICAL CAPEX
# ============================================================

for history in [

    F2A_ANNUAL_HISTORY,
    F2A_QUARTERLY_HISTORY,

]:

    if (

        not history.empty

        and

        "capital_expenditure_source"
        in history.columns

    ):

        bad_mask = (

            history[
                "capital_expenditure_source"
            ]

            .fillna("")

            .astype(str)

            .str.contains(

                "INFERRED_FROM_REPORTED_FCF_MINUS_CFO",

                regex=False,

            )

        )


        history.loc[

            bad_mask,
            "capital_expenditure",

        ] = np.nan


        history.loc[

            bad_mask,
            "capital_expenditure_source",

        ] = (
            "INVALIDATED_CIRCULAR_FCF_MINUS_CFO"
        )


# ============================================================
# 8. LABEL NORMALIZATION
# ============================================================

def f2a_normalize_label(
    value
):

    return re.sub(

        r"[^a-z0-9]",

        "",

        str(value).lower(),

    )


# ============================================================
# 9. CAPEX / INVESTMENT ALIASES
# ============================================================

F2A_DIRECT_CAPEX_ALIASES = [

    "Capital Expenditure",
    "Capital Expenditures",

    "Purchase Of PPE",
    "Purchases Of PPE",

    "Purchase Of Property Plant And Equipment",
    "Purchases Of Property Plant And Equipment",

    "Purchase Of Property Plant Equipment",
    "Purchases Of Property Plant Equipment",

    "Property Plant And Equipment Purchases",

    "Net PPE Purchases",

]


F2A_LONG_TERM_ASSET_ALIASES = [

    "Long-term assets",
    "Long term assets",

    "Purchase of long-term assets",
    "Purchases of long-term assets",

    "Long-term asset purchases",
    "Long term asset purchases",

]


# ============================================================
# 10. RAW YAHOO CASH-FLOW LOADER
# ============================================================

def f2a_load_raw_yahoo_cashflow(
    ticker,
    frequency,
):

    path = (

        Path(
            VALUATION_STATEMENT_RAW_DIR
        )

        /
        str(ticker)

        /
        str(
            VALUATION_SNAPSHOT_STRING
        )

        /
        f"{frequency}_cashflow.parquet"

    )


    if not path.exists():

        return pd.DataFrame()


    try:

        frame = pd.read_parquet(
            path
        )


    except Exception:

        return pd.DataFrame()


    return frame


# ============================================================
# 11. EXACT YAHOO LINE EXTRACTION
# ============================================================

def f2a_extract_yahoo_series(
    raw,
    aliases,
):

    if (

        raw.empty

        or

        "statement_line_item"
        not in raw.columns

    ):

        return (
            pd.Series(dtype=float),
            None,
        )


    alias_keys = {

        f2a_normalize_label(
            alias
        )

        for alias in aliases

    }


    matched_row = None
    matched_line = None


    for _, row in raw.iterrows():

        line = str(

            row[
                "statement_line_item"
            ]

        )


        if (

            f2a_normalize_label(
                line
            )

            in alias_keys

        ):

            matched_row = row
            matched_line = line

            break


    if matched_row is None:

        return (
            pd.Series(dtype=float),
            None,
        )


    values = {}


    for column in raw.columns:

        if column == "statement_line_item":

            continue


        date = pd.to_datetime(

            str(column),

            errors="coerce",

        )


        if pd.isna(date):

            continue


        value = pd.to_numeric(

            matched_row[
                column
            ],

            errors="coerce",

        )


        if pd.isna(value):

            continue


        values[
            pd.Timestamp(date)
        ] = -abs(
            float(value)
        )


    return (

        pd.Series(
            values,
            dtype=float,
        )
        .sort_index(
            ascending=False
        ),

        matched_line,

    )


# ============================================================
# 12. BEST RAW YAHOO CAPEX
# ============================================================

def f2a_get_yahoo_capex(
    ticker,
    frequency,
):

    raw = f2a_load_raw_yahoo_cashflow(

        ticker,
        frequency,

    )


    direct, direct_line = (

        f2a_extract_yahoo_series(

            raw,
            F2A_DIRECT_CAPEX_ALIASES,

        )

    )


    if not direct.empty:

        return {

            "series":
                direct,

            "source":
                "YAHOO_RAW_DIRECT_CAPEX",

            "line":
                direct_line,

        }


    proxy, proxy_line = (

        f2a_extract_yahoo_series(

            raw,
            F2A_LONG_TERM_ASSET_ALIASES,

        )

    )


    if not proxy.empty:

        return {

            "series":
                proxy,

            "source":
                "YAHOO_RAW_LONG_TERM_ASSET_PROXY",

            "line":
                proxy_line,

        }


    return {

        "series":
            pd.Series(
                dtype=float
            ),

        "source":
            "MISSING",

        "line":
            None,

    }


# ============================================================
# 13. SEC CONFIG
# ============================================================

SEC_USER_AGENT = os.getenv(

    "SEC_USER_AGENT",

    "MacroPortfolioResearch/1.0 research-contact@example.com",

)


SEC_HEADERS = {

    "User-Agent":
        SEC_USER_AGENT,

    "Accept-Encoding":
        "gzip, deflate",

    "Accept":
        "text/html,application/json",

}


SEC_TIMEOUT = 30


# ============================================================
# 14. SEC REQUEST HELPER
# ============================================================

def f2a_sec_get(
    url,
):

    response = requests.get(

        url,

        headers=SEC_HEADERS,

        timeout=SEC_TIMEOUT,

    )


    response.raise_for_status()


    time.sleep(
        0.12
    )


    return response


# ============================================================
# 15. SEC TICKER MAP
# ============================================================

def f2a_sec_ticker_map():

    response = f2a_sec_get(

        "https://www.sec.gov/files/company_tickers.json"

    )


    raw = response.json()


    rows = []


    for record in raw.values():

        rows.append({

            "ticker":
                str(
                    record[
                        "ticker"
                    ]
                )
                .upper(),

            "cik":
                int(
                    record[
                        "cik_str"
                    ]
                ),

        })


    return pd.DataFrame(
        rows
    )


# ============================================================
# 16. SEC FILINGS
# ============================================================

def f2a_sec_filings(
    cik,
):

    cik10 = str(
        int(cik)
    ).zfill(10)


    url = (

        "https://data.sec.gov/submissions/"
        f"CIK{cik10}.json"

    )


    data = f2a_sec_get(
        url
    ).json()


    recent = (

        data.get(
            "filings",
            {}
        )
        .get(
            "recent",
            {}
        )

    )


    if not recent:

        return pd.DataFrame()


    filings = pd.DataFrame(
        recent
    )


    for column in [

        "filingDate",
        "reportDate",

    ]:

        if column in filings.columns:

            filings[
                column
            ] = pd.to_datetime(

                filings[
                    column
                ],

                errors="coerce",

            )


    return filings


# ============================================================
# 17. SELECT LATEST ELIGIBLE FILING
# ============================================================

def f2a_latest_filing(
    filings,
    form,
):

    if filings.empty:

        return None


    snapshot = pd.Timestamp(

        VALUATION_SNAPSHOT_STRING

    )


    eligible = (

        filings[

            (
                filings[
                    "form"
                ]
                ==
                form
            )

            &

            (
                filings[
                    "filingDate"
                ]
                <=
                snapshot
            )

        ]

        .sort_values(

            "filingDate",

            ascending=False,

        )

    )


    if eligible.empty:

        return None


    return eligible.iloc[0]


# ============================================================
# 18. SEC FILING URL
# ============================================================

def f2a_sec_filing_url(
    cik,
    filing_row,
):

    accession = str(

        filing_row[
            "accessionNumber"
        ]

    ).replace(
        "-",
        ""
    )


    document = str(

        filing_row[
            "primaryDocument"
        ]

    )


    return (

        "https://www.sec.gov/Archives/edgar/data/"
        f"{int(cik)}/"
        f"{accession}/"
        f"{document}"

    )


# ============================================================
# 19. PARSE DISPLAYED NUMBER
# ============================================================

def f2a_parse_number(
    value,
):

    if value is None:

        return None


    text = (

        str(value)

        .replace("\xa0", " ")

        .replace("−", "-")

        .replace("$", "")

        .replace(",", "")

        .strip()

    )


    if text in {

        "",
        "-",
        "—",
        "--",

    }:

        return None


    negative = (

        text.startswith("(")

        and

        text.endswith(")")

    )


    if negative:

        text = text[
            1:-1
        ]


    try:

        number = float(
            text
        )


    except Exception:

        return None


    if negative:

        number = -number


    return number


# ============================================================
# 20. INLINE-XBRL FACT TAG DETECTOR
# ============================================================

def f2a_is_numeric_ix_fact(
    tag,
):

    if tag is None:

        return False


    if tag.name is None:

        return False


    name = str(
        tag.name
    ).lower()


    return (

        name.endswith(
            "nonfraction"
        )

        or

        name.endswith(
            "nonnumeric"
        )
        is False
        and
        "nonfraction"
        in name

    )


# ============================================================
# 21. EXTRACT ONE XBRL FACT VALUE
# ============================================================

def f2a_ix_fact_value(
    fact,
    fallback_scale=1.0,
):

    displayed = f2a_parse_number(

        fact.get_text(
            " ",
            strip=True,
        )

    )


    if displayed is None:

        return np.nan


    scale_attribute = fact.attrs.get(
        "scale",
        None
    )


    if scale_attribute is not None:

        try:

            multiplier = (

                10.0
                **
                int(
                    float(
                        scale_attribute
                    )
                )

            )


        except Exception:

            multiplier = (
                fallback_scale
            )


    else:

        multiplier = (
            fallback_scale
        )


    value = (

        float(displayed)
        *
        float(multiplier)

    )


    sign_attribute = str(

        fact.attrs.get(
            "sign",
            ""
        )

    )


    if (

        sign_attribute
        ==
        "-"

        and

        value > 0

    ):

        value = -value


    # Capital investment is standardized as an outflow.
    return (
        -abs(value)
    )


# ============================================================
# 22. FILING PRESENTATION SCALE
# ============================================================

def f2a_filing_scale(
    html_text,
):

    plain = re.sub(

        r"<[^>]+>",

        " ",

        html_text,

    ).lower()


    if "in thousands" in plain:

        return 1_000.0


    if "in millions" in plain:

        return 1_000_000.0


    if "in billions" in plain:

        return 1_000_000_000.0


    return 1.0


# ============================================================
# 23. ROW LABEL
# ============================================================

def f2a_html_row_label(
    tr,
):

    cells = tr.find_all(
        ["td", "th"]
    )


    for cell in cells:

        text = cell.get_text(
            " ",
            strip=True,
        )


        if re.search(
            r"[A-Za-z]",
            text,
        ):

            return text


    return ""


# ============================================================
# 24. INLINE-XBRL INVESTING-ROW EXTRACTOR
# ============================================================
#
# Critical properties:
#
#   1. Only searches between:
#
#         Cash flows from investing activities
#         ...
#         Cash flows from financing activities
#
#   2. Exact normalized line-item match.
#
#   3. Numeric facts are deduplicated by contextRef.
#
# This avoids duplicated SEC HTML presentation cells.
# ============================================================

def f2a_extract_sec_ix_investing_row(
    html_text,
    aliases,
):

    soup = BeautifulSoup(

        html_text,
        "lxml",

    )


    aliases_normalized = {

        f2a_normalize_label(
            alias
        )

        for alias in aliases

    }


    investing_markers = {

        f2a_normalize_label(
            "Cash flows from investing activities"
        ),

        f2a_normalize_label(
            "Cash Flows From Investing Activities"
        ),

    }


    financing_markers = {

        f2a_normalize_label(
            "Cash flows from financing activities"
        ),

        f2a_normalize_label(
            "Cash Flows From Financing Activities"
        ),

    }


    fallback_scale = (

        f2a_filing_scale(
            html_text
        )

    )


    inside_investing = False


    for tr in soup.find_all(
        "tr"
    ):

        row_label = (

            f2a_html_row_label(
                tr
            )

        )


        normalized_label = (

            f2a_normalize_label(
                row_label
            )

        )


        # ----------------------------------------------------
        # Enter investing section
        # ----------------------------------------------------

        if normalized_label in investing_markers:

            inside_investing = True

            continue


        # ----------------------------------------------------
        # Leave investing section
        # ----------------------------------------------------

        if (

            inside_investing

            and

            normalized_label
            in
            financing_markers

        ):

            break


        if not inside_investing:

            continue


        # ----------------------------------------------------
        # Exact line-item match only
        # ----------------------------------------------------

        if normalized_label not in aliases_normalized:

            continue


        ix_facts = [

            tag

            for tag in tr.find_all(
                True
            )

            if (

                tag.name

                and

                str(
                    tag.name
                )
                .lower()
                .endswith(
                    "nonfraction"
                )

            )

        ]


        # ----------------------------------------------------
        # Deduplicate by XBRL context.
        # ----------------------------------------------------

        facts_by_context = []


        seen_contexts = set()


        for fact in ix_facts:

            context = (

                fact.attrs.get(
                    "contextref"
                )

                or

                fact.attrs.get(
                    "contextRef"
                )

                or

                fact.attrs.get(
                    "context-ref"
                )

            )


            context_string = (

                str(context)

                if context is not None

                else ""

            )


            # ------------------------------------------------
            # If context exists, each period is retained once.
            # ------------------------------------------------

            if context_string:

                if context_string in seen_contexts:

                    continue


                seen_contexts.add(
                    context_string
                )


            value = f2a_ix_fact_value(

                fact,
                fallback_scale=fallback_scale,

            )


            if pd.isna(value):

                continue


            facts_by_context.append({

                "context":
                    context_string,

                "value":
                    float(value),

                "display":
                    fact.get_text(
                        " ",
                        strip=True,
                    ),

                "scale":
                    fact.attrs.get(
                        "scale",
                        None
                    ),

            })


        if not facts_by_context:

            return {

                "success":
                    False,

                "matched_line":
                    row_label,

                "facts":
                    [],

                "values":
                    [],

                "contexts":
                    [],

                "error":
                    "Exact row found but no numeric inline-XBRL facts found.",

            }


        return {

            "success":
                True,

            "matched_line":
                row_label,

            "facts":
                facts_by_context,

            "values": [

                record[
                    "value"
                ]

                for record
                in facts_by_context

            ],

            "contexts": [

                record[
                    "context"
                ]

                for record
                in facts_by_context

            ],

            "error":
                None,

        }


    return {

        "success":
            False,

        "matched_line":
            None,

        "facts":
            [],

        "values":
            [],

        "contexts":
            [],

        "error":
            "No exact investing-section row found.",

    }


# ============================================================
# 25. SEC CAPEX EXTRACTION
# ============================================================

def f2a_sec_capex(
    ticker,
    cik,
):

    filings = f2a_sec_filings(
        cik
    )


    ten_k = f2a_latest_filing(

        filings,
        "10-K",

    )


    ten_q = f2a_latest_filing(

        filings,
        "10-Q",

    )


    if ten_k is None:

        return {

            "success":
                False,

            "error":
                "No eligible SEC 10-K.",

        }


    # ========================================================
    # 10-K
    # ========================================================

    url_10k = f2a_sec_filing_url(

        cik,
        ten_k,

    )


    html_10k = f2a_sec_get(
        url_10k
    ).text


    annual = (

        f2a_extract_sec_ix_investing_row(

            html_10k,
            F2A_DIRECT_CAPEX_ALIASES,

        )

    )


    source = (
        "SEC_DIRECT_CAPEX"
    )


    if not annual[
        "success"
    ]:

        annual = (

            f2a_extract_sec_ix_investing_row(

                html_10k,
                F2A_LONG_TERM_ASSET_ALIASES,

            )

        )


        source = (
            "SEC_LONG_TERM_ASSET_PROXY"
        )


    if (

        not annual[
            "success"
        ]

        or

        not annual[
            "values"
        ]

    ):

        return {

            "success":
                False,

            "error":
                (
                    "No valid capital-investment row "
                    "in 10-K investing section."
                ),

            "url_10k":
                url_10k,

        }


    latest_annual = float(

        annual[
            "values"
        ][0]

    )


    ttm_capex = (
        latest_annual
    )


    current_ytd = np.nan

    prior_ytd = np.nan


    current_context = None
    prior_context = None


    ttm_method = (
        "LATEST_10K_ONLY"
    )


    url_10q = None


    # ========================================================
    # 10-Q BRIDGE
    # ========================================================

    if ten_q is not None:

        ten_k_report_date = pd.to_datetime(

            ten_k[
                "reportDate"
            ],

            errors="coerce",

        )


        ten_q_report_date = pd.to_datetime(

            ten_q[
                "reportDate"
            ],

            errors="coerce",

        )


        if (

            pd.notna(
                ten_k_report_date
            )

            and

            pd.notna(
                ten_q_report_date
            )

            and

            ten_q_report_date
            >
            ten_k_report_date

        ):

            url_10q = f2a_sec_filing_url(

                cik,
                ten_q,

            )


            html_10q = f2a_sec_get(
                url_10q
            ).text


            aliases = (

                F2A_DIRECT_CAPEX_ALIASES

                if source
                ==
                "SEC_DIRECT_CAPEX"

                else

                F2A_LONG_TERM_ASSET_ALIASES

            )


            quarter = (

                f2a_extract_sec_ix_investing_row(

                    html_10q,
                    aliases,

                )

            )


            # ------------------------------------------------
            # Require TWO distinct XBRL contexts.
            # ------------------------------------------------

            if (

                quarter[
                    "success"
                ]

                and

                len(
                    quarter[
                        "values"
                    ]
                )
                >=
                2

                and

                len(
                    set(
                        quarter[
                            "contexts"
                        ][:2]
                    )
                )
                ==
                2

            ):

                current_ytd = float(

                    quarter[
                        "values"
                    ][0]

                )


                prior_ytd = float(

                    quarter[
                        "values"
                    ][1]

                )


                current_context = (

                    quarter[
                        "contexts"
                    ][0]

                )


                prior_context = (

                    quarter[
                        "contexts"
                    ][1]

                )


                ttm_capex = (

                    latest_annual

                    +

                    current_ytd

                    -

                    prior_ytd

                )


                ttm_method = (

                    "10K_PLUS_CURRENT_YTD_MINUS_PRIOR_YTD"

                )


            elif quarter[
                "success"
            ]:

                # --------------------------------------------
                # Do not silently use a malformed bridge.
                # --------------------------------------------

                return {

                    "success":
                        False,

                    "error":
                        (
                            "10-Q investment row found, "
                            "but two distinct comparative "
                            "XBRL contexts were not available."
                        ),

                    "annual":
                        annual,

                    "quarter":
                        quarter,

                    "url_10k":
                        url_10k,

                    "url_10q":
                        url_10q,

                }


    return {

        "success":
            True,

        "ticker":
            ticker,

        "cik":
            int(cik),

        "source":
            source,

        "matched_line":
            annual[
                "matched_line"
            ],

        "annual_values":
            annual[
                "values"
            ],

        "annual_contexts":
            annual[
                "contexts"
            ],

        "latest_annual":
            latest_annual,

        "current_ytd":
            current_ytd,

        "prior_ytd":
            prior_ytd,

        "current_ytd_context":
            current_context,

        "prior_ytd_context":
            prior_context,

        "ttm_capex":
            float(
                ttm_capex
            ),

        "ttm_method":
            ttm_method,

        "url_10k":
            url_10k,

        "url_10q":
            url_10q,

        "error":
            None,

    }


# ============================================================
# 26. SEC TICKER MAP
# ============================================================

if not F2A_REPAIR_UNIVERSE.empty:

    try:

        F2A_SEC_MAP = (

            f2a_sec_ticker_map()

        )


    except Exception as exc:

        F2A_SEC_MAP = (
            pd.DataFrame()
        )


        F2A_SEC_MAP_ERROR = (

            f"{type(exc).__name__}: "
            f"{exc}"

        )


else:

    F2A_SEC_MAP = (
        pd.DataFrame()
    )


# ============================================================
# 27. PATCH ANNUAL HISTORY
# ============================================================

def f2a_patch_annual_history(
    history,
    ticker,
    annual_values,
    source,
):

    output = history.copy()


    company_rows = (

        output.loc[

            output[
                "ticker"
            ]
            ==
            ticker

        ]

        .sort_values(

            "period_end",

            ascending=False,

        )

    )


    patched = 0


    for row_index, capex in zip(

        company_rows.index,
        annual_values,

    ):

        output.loc[

            row_index,
            "capital_expenditure",

        ] = float(
            capex
        )


        output.loc[

            row_index,
            "capital_expenditure_source",

        ] = source


        if (

            "operating_cash_flow"
            in output.columns

            and

            pd.notna(

                output.loc[

                    row_index,
                    "operating_cash_flow",

                ]

            )

        ):

            output.loc[

                row_index,
                "free_cash_flow_effective",

            ] = (

                float(

                    output.loc[

                        row_index,
                        "operating_cash_flow",

                    ]

                )

                +

                float(
                    capex
                )

            )


            output.loc[

                row_index,
                "free_cash_flow_source",

            ] = (

                "RECALCULATED_FROM_VALIDATED_CAPEX"

            )


        patched += 1


    return (
        output,
        patched,
    )


# ============================================================
# 28. REPAIR ENGINE
# ============================================================

repair_rows = []


for _, company in (

    F2A_REPAIR_UNIVERSE
    .iterrows()

):

    ticker = str(

        company[
            "ticker"
        ]

    ).upper()


    repaired_capex = np.nan

    repair_method = None
    repair_source = None

    matched_line = None

    sec_result = None

    annual_rows_patched = 0

    error = None


    # ========================================================
    # A. YAHOO RAW — FIRST FALLBACK
    # ========================================================

    yahoo_quarterly = (

        f2a_get_yahoo_capex(

            ticker,
            "quarterly",

        )

    )


    if len(
        yahoo_quarterly[
            "series"
        ]
    ) >= 4:

        repaired_capex = float(

            yahoo_quarterly[
                "series"
            ]
            .iloc[:4]
            .sum()

        )


        repair_method = (
            "YAHOO_RAW_TTM"
        )


        repair_source = (

            yahoo_quarterly[
                "source"
            ]

        )


        matched_line = (

            yahoo_quarterly[
                "line"
            ]

        )


    # ========================================================
    # B. SEC INLINE-XBRL FALLBACK
    # ========================================================

    if pd.isna(
        repaired_capex
    ):

        try:

            if F2A_SEC_MAP.empty:

                raise RuntimeError(

                    "SEC ticker map unavailable."

                )


            cik_rows = (

                F2A_SEC_MAP[

                    F2A_SEC_MAP[
                        "ticker"
                    ]
                    .map(f2_sec_symbol)
                    ==
                    f2_sec_symbol(ticker)

                ]

            )


            if cik_rows.empty:

                raise RuntimeError(

                    f"No SEC CIK mapping for {ticker}."

                )


            cik = int(

                cik_rows.iloc[0][
                    "cik"
                ]

            )


            sec_result = (

                f2a_sec_capex(

                    ticker,
                    cik,

                )

            )


            if not sec_result.get(

                "success",
                False,

            ):

                raise RuntimeError(

                    sec_result.get(

                        "error",

                        "SEC extraction failed.",

                    )

                )


            repaired_capex = float(

                sec_result[
                    "ttm_capex"
                ]

            )


            repair_method = (
                "SEC_INLINE_XBRL_FALLBACK"
            )


            repair_source = (

                sec_result[
                    "source"
                ]

            )


            matched_line = (

                sec_result[
                    "matched_line"
                ]

            )


            # ------------------------------------------------
            # Patch annual historical CapEx.
            # ------------------------------------------------

            F2A_ANNUAL_HISTORY, annual_rows_patched = (

                f2a_patch_annual_history(

                    F2A_ANNUAL_HISTORY,

                    ticker,

                    sec_result[
                        "annual_values"
                    ],

                    (

                        repair_source

                        +
                        "::"

                        +
                        str(
                            matched_line
                        )

                    ),

                )

            )


        except Exception as exc:

            error = (

                f"{type(exc).__name__}: "
                f"{exc}"

            )


    # ========================================================
    # C. VALIDATE REPAIR
    # ========================================================

    repair_valid = (

        pd.notna(
            repaired_capex
        )

        and

        _f_isfinite(
            repaired_capex
        )

        and

        repaired_capex < 0

    )


    company_mask = (

        F2A_CURRENT_INPUTS[
            "ticker"
        ]
        ==
        ticker

    )


    if repair_valid:

        source_string = (

            f"{repair_method}::"
            f"{repair_source}::"
            f"{matched_line}"

        )


        if sec_result is not None:

            source_string += (

                "::"

                +

                str(
                    sec_result[
                        "ttm_method"
                    ]
                )

            )


        F2A_CURRENT_INPUTS.loc[

            company_mask,
            "ttm_capex",

        ] = repaired_capex


        F2A_CURRENT_INPUTS.loc[

            company_mask,
            "ttm_capex_source",

        ] = source_string


        # ----------------------------------------------------
        # Recalculate FCF:
        #
        #   FCF = CFO + signed CapEx
        # ----------------------------------------------------

        F2A_CURRENT_INPUTS.loc[

            company_mask,
            "ttm_free_cash_flow",

        ] = (

            F2A_CURRENT_INPUTS.loc[

                company_mask,
                "ttm_operating_cash_flow",

            ]

            +

            repaired_capex

        )


    else:

        F2A_CURRENT_INPUTS.loc[

            company_mask,
            "ttm_capex",

        ] = np.nan


        F2A_CURRENT_INPUTS.loc[

            company_mask,
            "ttm_capex_source",

        ] = "UNRESOLVED"


    repair_rows.append({

        "ticker":
            ticker,

        "company_name":
            company[
                "company_name"
            ],

        "before_capex":
            company[
                "ttm_capex"
            ],

        "before_source":
            company[
                "ttm_capex_source"
            ],

        "repair_method":
            repair_method,

        "repair_source":
            repair_source,

        "matched_line":
            matched_line,

        "repaired_ttm_capex":
            repaired_capex,

        "sec_latest_annual":
            (
                sec_result.get(
                    "latest_annual",
                    np.nan,
                )

                if sec_result is not None

                else np.nan
            ),

        "sec_current_ytd":
            (
                sec_result.get(
                    "current_ytd",
                    np.nan,
                )

                if sec_result is not None

                else np.nan
            ),

        "sec_prior_ytd":
            (
                sec_result.get(
                    "prior_ytd",
                    np.nan,
                )

                if sec_result is not None

                else np.nan
            ),

        "current_ytd_context":
            (
                sec_result.get(
                    "current_ytd_context",
                    None,
                )

                if sec_result is not None

                else None
            ),

        "prior_ytd_context":
            (
                sec_result.get(
                    "prior_ytd_context",
                    None,
                )

                if sec_result is not None

                else None
            ),

        "sec_ttm_method":
            (
                sec_result.get(
                    "ttm_method",
                    None,
                )

                if sec_result is not None

                else None
            ),

        "annual_rows_patched":
            annual_rows_patched,

        "repair_success":
            bool(
                repair_valid
            ),

        "error":
            error,

    })


F2A_CAPEX_REPAIR_AUDIT = (

    pd.DataFrame(
        repair_rows
    )

)


# ============================================================
# 29. REBUILD ESSENTIAL-INPUT COVERAGE
# ============================================================

coverage_rows = []


for _, row in (

    F2A_CURRENT_INPUTS
    .iterrows()

):

    required_fields = (

        F2_MODEL_ESSENTIAL_INPUTS.get(

            row[
                "valuation_model_family"
            ],

            [],

        )

    )


    missing_fields = [

        field

        for field in required_fields

        if pd.isna(

            row.get(
                field,
                np.nan,
            )

        )

    ]


    expected = len(
        required_fields
    )


    available = (

        expected
        -
        len(
            missing_fields
        )

    )


    coverage_rows.append({

        "essential_inputs_available":
            available,

        "essential_inputs_expected":
            expected,

        "essential_input_coverage":
            (

                available / expected

                if expected > 0

                else 0.0

            ),

        "essential_missing_fields":
            ",".join(
                missing_fields
            ),

    })


coverage_frame = pd.DataFrame(

    coverage_rows

)


for column in coverage_frame.columns:

    F2A_CURRENT_INPUTS[
        column
    ] = (

        coverage_frame[
            column
        ].values

    )


# ============================================================
# 30. RECOMPUTE READINESS
# ============================================================

if (

    "ttm_annual_revenue_anomaly"
    in
    F2A_CURRENT_INPUTS.columns

):

    revenue_integrity_ok = (

        ~

        F2A_CURRENT_INPUTS[
            "ttm_annual_revenue_anomaly"
        ]
        .fillna(False)

        |

        ~

        F2A_CURRENT_INPUTS[
            "uses_fcff_dcf"
        ]

    )


else:

    revenue_integrity_ok = pd.Series(

        True,

        index=F2A_CURRENT_INPUTS.index,

    )


F2A_CURRENT_INPUTS[
    "valuation_data_ready"
] = (

    np.isclose(

        F2A_CURRENT_INPUTS[
            "essential_input_coverage"
        ],

        1.0,

    )

    &

    (
        F2A_CURRENT_INPUTS[
            "current_price"
        ]
        >
        0
    )

    &

    (
        F2A_CURRENT_INPUTS[
            "valuation_share_units"
        ]
        >
        0
    )

    &

    F2A_CURRENT_INPUTS[
        "currency_unit_reconciliation_ready"
    ].fillna(False).astype(bool)

    &

    revenue_integrity_ok

)


# ============================================================
# 31. FINAL CAPEX INTEGRITY
# ============================================================

final_source = (

    F2A_CURRENT_INPUTS[
        "ttm_capex_source"
    ]

    .fillna("")

    .astype(str)

)


F2A_CURRENT_INPUTS[
    "f2a_final_circular_capex"
] = (

    F2A_CURRENT_INPUTS[
        "f2a_is_fcff_model"
    ]

    &

    final_source

    .str.contains(

        "INFERRED_FROM_REPORTED_FCF_MINUS_CFO",

        regex=False,

    )

)


F2A_CURRENT_INPUTS[
    "f2a_final_invalid_capex"
] = (

    F2A_CURRENT_INPUTS[
        "f2a_is_fcff_model"
    ]

    &

    (

        F2A_CURRENT_INPUTS[
            "ttm_capex"
        ]
        .isna()

        |

        (
            F2A_CURRENT_INPUTS[
                "ttm_capex"
            ]
            >=
            0
        )

    )

)


# ============================================================
# 32. FINAL FCFF AUDIT
# ============================================================

F2A_FCFF_CAPEX_AUDIT = (

    F2A_CURRENT_INPUTS[

        F2A_CURRENT_INPUTS[
            "f2a_is_fcff_model"
        ]

    ][
        [
            "valuation_queue_rank",

            "ticker",
            "company_name",

            "valuation_model_family",

            "ttm_operating_cash_flow",

            "ttm_capex",
            "ttm_capex_source",

            "ttm_free_cash_flow",

            "essential_input_coverage",

            "valuation_data_ready",

            "f2a_final_circular_capex",
            "f2a_final_invalid_capex",
        ]
    ]

    .copy()

    .sort_values(
        "valuation_queue_rank"
    )

    .reset_index(
        drop=True
    )

)


# ============================================================
# 33. HEALTH STATISTICS
# ============================================================

fcff_mask = (

    F2A_CURRENT_INPUTS[
        "f2a_is_fcff_model"
    ]

)


fcff_count = int(

    fcff_mask.sum()

)


circular_count = int(

    F2A_CURRENT_INPUTS[
        "f2a_final_circular_capex"
    ]
    .sum()

)


invalid_count = int(

    F2A_CURRENT_INPUTS[
        "f2a_final_invalid_capex"
    ]
    .sum()

)


valid_fcff_count = int(

    (

        fcff_mask

        &

        ~

        F2A_CURRENT_INPUTS[
            "f2a_final_circular_capex"
        ]

        &

        ~

        F2A_CURRENT_INPUTS[
            "f2a_final_invalid_capex"
        ]

    )

    .sum()

)


ready_count = int(

    F2A_CURRENT_INPUTS[
        "valuation_data_ready"
    ]
    .sum()

)


total_count = len(

    F2A_CURRENT_INPUTS

)


ready_rate = (

    ready_count
    /
    total_count

    if total_count > 0

    else 0.0

)


core = (

    F2A_CURRENT_INPUTS[

        F2A_CURRENT_INPUTS[
            "stock_research_scope"
        ]
        ==
        "CORE_LONG"

    ]

)


core_count = len(
    core
)


core_ready_count = int(

    core[
        "valuation_data_ready"
    ]
    .sum()

)


core_ready_rate = (

    core_ready_count
    /
    core_count

    if core_count > 0

    else 1.0

)


# ============================================================
# 34. EXTRA SEC BRIDGE INTEGRITY
# ============================================================

sec_bridge_failures = 0


if not F2A_CAPEX_REPAIR_AUDIT.empty:

    sec_bridge_rows = (

        F2A_CAPEX_REPAIR_AUDIT[

            F2A_CAPEX_REPAIR_AUDIT[
                "sec_ttm_method"
            ]
            ==
            "10K_PLUS_CURRENT_YTD_MINUS_PRIOR_YTD"

        ]

    )


    for _, row in sec_bridge_rows.iterrows():

        current_context = row[
            "current_ytd_context"
        ]


        prior_context = row[
            "prior_ytd_context"
        ]


        if (

            pd.isna(
                current_context
            )

            or

            pd.isna(
                prior_context
            )

            or

            str(
                current_context
            )
            ==
            str(
                prior_context
            )

        ):

            sec_bridge_failures += 1


# ============================================================
# 35. HEALTH ENGINE
# ============================================================

checks = []


def add_check(
    check,
    passed,
    detail,
    required=True,
):

    checks.append({

        "check":
            check,

        "passed":
            bool(
                passed
            ),

        "required":
            bool(
                required
            ),

        "detail":
            str(
                detail
            ),

    })


add_check(

    "All FCFF companies have validated CapEx",

    valid_fcff_count
    ==
    fcff_count,

    (
        f"valid="
        f"{valid_fcff_count}/"
        f"{fcff_count}"
    ),

)


add_check(

    "No circular FCF-minus-CFO CapEx remains",

    circular_count
    ==
    0,

    (
        f"circular="
        f"{circular_count}"
    ),

)


add_check(

    "No missing/zero FCFF CapEx remains",

    invalid_count
    ==
    0,

    (
        f"invalid="
        f"{invalid_count}"
    ),

)


add_check(

    "SEC TTM bridges use distinct comparative XBRL contexts",

    sec_bridge_failures
    ==
    0,

    (
        f"context_failures="
        f"{sec_bridge_failures}"
    ),

)


add_check(

    "Overall valuation readiness >= 95%",

    ready_rate
    >=
    0.95,

    (
        f"ready="
        f"{ready_count}/"
        f"{total_count} "
        f"({ready_rate:.1%})"
    ),

)


add_check(

    "Core-long valuation readiness >= 95%",

    core_ready_rate
    >=
    0.95,

    (
        f"ready="
        f"{core_ready_count}/"
        f"{core_count} "
        f"({core_ready_rate:.1%})"
    ),

)


F2A_HEALTH = pd.DataFrame(
    checks
)


F2A_HEALTH[
    "status"
] = np.where(

    F2A_HEALTH[
        "passed"
    ],

    "✓ PASS",

    np.where(

        F2A_HEALTH[
            "required"
        ],

        "✗ FAIL",

        "⚠ WARN",

    )

)


required_failures = (

    F2A_HEALTH[

        F2A_HEALTH[
            "required"
        ]

        &

        ~

        F2A_HEALTH[
            "passed"
        ]

    ]

)


F2A_PASSED = (

    required_failures.empty

)


F2_FINAL_PASSED = (

    F2A_PASSED

)


# ============================================================
# 36. PROMOTE ONLY AFTER PASS
# ============================================================

if F2A_PASSED:

    VALUATION_CURRENT_INPUTS = (

        F2A_CURRENT_INPUTS
        .copy()

    )


    VALUATION_ANNUAL_HISTORY = (

        F2A_ANNUAL_HISTORY
        .copy()

    )


    VALUATION_QUARTERLY_HISTORY = (

        F2A_QUARTERLY_HISTORY
        .copy()

    )


