# ============================================================
# 8. NUMERIC HELPERS
# ============================================================

def f3_numeric(
    value
):

    try:

        value = float(
            value
        )


        if _f_isfinite(
            value
        ):

            return value


    except Exception:

        pass


    return np.nan


def f3_clip(
    value,
    lower,
    upper,
):

    value = f3_numeric(
        value
    )


    if pd.isna(
        value
    ):

        return np.nan


    return float(

        np.clip(
            value,
            lower,
            upper,
        )

    )


def f3_safe_median(
    values
):

    series = pd.to_numeric(

        pd.Series(
            values
        ),

        errors="coerce",

    )


    series = series[

        _f_isfinite(
            series
        )

    ]


    if series.empty:

        return np.nan


    return float(
        series.median()
    )


def f3_weighted_average(
    values,
    weights,
):

    valid_pairs = [

        (
            f3_numeric(value),
            float(weight),
        )

        for value, weight in zip(
            values,
            weights,
        )

        if pd.notna(
            f3_numeric(value)
        )

        and

        float(weight) > 0

    ]


    if not valid_pairs:

        return np.nan


    numerator = sum(

        value * weight

        for value, weight
        in valid_pairs

    )


    denominator = sum(

        weight

        for _, weight
        in valid_pairs

    )


    return float(

        numerator
        /
        denominator

    )


# ============================================================
# 9. RECENT SERIES
# ============================================================

def f3_recent_numeric(
    dataframe,
    column,
    periods=3,
):

    if (

        dataframe.empty

        or

        column not in dataframe.columns

    ):

        return pd.Series(
            dtype=float
        )


    ordered = (

        dataframe

        .sort_values(
            "period_end",
            ascending=False,
        )

    )


    values = pd.to_numeric(

        ordered[
            column
        ],

        errors="coerce",

    )


    values = values[

        _f_isfinite(
            values
        )

    ]


    return (

        values
        .iloc[:periods]

    )


# ============================================================
# 10. HISTORICAL CAGR
# ============================================================

def f3_historical_cagr(
    dataframe,
    column,
    max_intervals=3,
):

    if (

        dataframe.empty

        or

        column not in dataframe.columns

    ):

        return np.nan


    temp = (

        dataframe[
            [
                "period_end",
                column,
            ]
        ]

        .copy()

    )


    temp[
        column
    ] = pd.to_numeric(

        temp[
            column
        ],

        errors="coerce",

    )


    temp = temp[

        temp[
            column
        ]
        >
        0

    ]


    temp = (

        temp
        .dropna()
        .sort_values(
            "period_end"
        )

    )


    if len(temp) < 2:

        return np.nan


    # --------------------------------------------------------
    # Use at most 4 annual observations = 3 intervals.
    # --------------------------------------------------------

    temp = temp.tail(

        max_intervals
        +
        1

    )


    beginning = float(

        temp.iloc[0][
            column
        ]

    )


    ending = float(

        temp.iloc[-1][
            column
        ]

    )


    elapsed_years = (

        (
            temp.iloc[-1][
                "period_end"
            ]

            -

            temp.iloc[0][
                "period_end"
            ]

        ).days

        /
        365.25

    )


    if (

        beginning <= 0

        or

        ending <= 0

        or

        elapsed_years <= 0.5

    ):

        return np.nan


    return float(

        (
            ending
            /
            beginning
        )
        **
        (
            1.0
            /
            elapsed_years
        )

        -
        1.0

    )


# ============================================================
# 11. HISTORICAL RATIO MEDIAN
# ============================================================

def f3_ratio_median(
    dataframe,
    numerator,
    denominator,
    periods=3,
    absolute_numerator=False,
):

    if (

        dataframe.empty

        or

        numerator not in dataframe.columns

        or

        denominator not in dataframe.columns

    ):

        return np.nan


    temp = (

        dataframe

        .sort_values(
            "period_end",
            ascending=False,
        )

        .head(
            periods
        )

        .copy()

    )


    num = pd.to_numeric(

        temp[
            numerator
        ],

        errors="coerce",

    )


    den = pd.to_numeric(

        temp[
            denominator
        ],

        errors="coerce",

    )


    if absolute_numerator:

        num = num.abs()


    ratio = np.where(

        den.abs()
        >
        1e-12,

        num
        /
        den,

        np.nan,

    )


    return f3_safe_median(
        ratio
    )


# ============================================================
# 12. NWC INVESTMENT RATIO
# ============================================================

def f3_nwc_investment_ratio(
    annual_company,
):

    # --------------------------------------------------------
    # Preferred:
    # Cash-flow statement change in working capital.
    #
    # Cash-flow convention:
    # negative = use of cash
    #
    # Therefore:
    # investment = - cash-flow change
    # --------------------------------------------------------

    if (

        "change_in_working_capital_cf"
        in annual_company.columns

        and

        "revenue"
        in annual_company.columns

    ):

        recent = (

            annual_company

            .sort_values(
                "period_end",
                ascending=False,
            )

            .head(3)

            .copy()

        )


        change_wc = pd.to_numeric(

            recent[
                "change_in_working_capital_cf"
            ],

            errors="coerce",

        )


        revenue = pd.to_numeric(

            recent[
                "revenue"
            ],

            errors="coerce",

        )


        ratio = np.where(

            revenue.abs()
            >
            1e-12,

            -
            change_wc
            /
            revenue,

            np.nan,

        )


        median_ratio = f3_safe_median(
            ratio
        )


        if pd.notna(
            median_ratio
        ):

            return f3_clip(

                median_ratio,
                -0.05,
                0.10,

            )


    # --------------------------------------------------------
    # Fallback:
    # Balance-sheet working-capital change.
    # --------------------------------------------------------

    if (

        "working_capital"
        in annual_company.columns

        and

        "revenue"
        in annual_company.columns

    ):

        temp = (

            annual_company[
                [
                    "period_end",
                    "working_capital",
                    "revenue",
                ]
            ]

            .copy()

            .sort_values(
                "period_end"
            )

        )


        temp[
            "working_capital"
        ] = pd.to_numeric(

            temp[
                "working_capital"
            ],

            errors="coerce",

        )


        temp[
            "revenue"
        ] = pd.to_numeric(

            temp[
                "revenue"
            ],

            errors="coerce",

        )


        temp[
            "delta_wc"
        ] = (

            temp[
                "working_capital"
            ]

            .diff()

        )


        temp[
            "ratio"
        ] = np.where(

            temp[
                "revenue"
            ].abs()
            >
            1e-12,

            temp[
                "delta_wc"
            ]

            /
            temp[
                "revenue"
            ],

            np.nan,

        )


        median_ratio = f3_safe_median(

            temp[
                "ratio"
            ]
            .tail(3)

        )


        if pd.notna(
            median_ratio
        ):

            return f3_clip(

                median_ratio,
                -0.05,
                0.10,

            )


    return 0.0


# ============================================================
# 13. FINANCIAL ROE HISTORY
# ============================================================

def f3_financial_roe_history(
    annual_company,
):

    if (

        annual_company.empty

        or

        "net_income"
        not in annual_company.columns

        or

        "equity"
        not in annual_company.columns

    ):

        return pd.Series(
            dtype=float
        )


    temp = (

        annual_company[
            [
                "period_end",
                "net_income",
                "equity",
            ]
        ]

        .copy()

        .sort_values(
            "period_end"
        )

    )


    temp[
        "net_income"
    ] = pd.to_numeric(

        temp[
            "net_income"
        ],

        errors="coerce",

    )


    temp[
        "equity"
    ] = pd.to_numeric(

        temp[
            "equity"
        ],

        errors="coerce",

    )


    temp[
        "average_equity"
    ] = (

        (
            temp[
                "equity"
            ]

            +

            temp[
                "equity"
            ]
            .shift(1)

        )

        /
        2.0

    )


    temp[
        "roe"
    ] = np.where(

        temp[
            "average_equity"
        ]
        >
        0,

        temp[
            "net_income"
        ]

        /
        temp[
            "average_equity"
        ],

        np.nan,

    )


    return (

        temp[
            "roe"
        ]

        .replace(
            [
                np.inf,
                -np.inf,
            ],
            np.nan,
        )

        .dropna()

    )


# ============================================================
# 14. PAYOUT RATIO
# ============================================================

def f3_financial_payout_ratio(
    annual_company,
):

    if (

        annual_company.empty

        or

        "dividends_paid"
        not in annual_company.columns

        or

        "net_income"
        not in annual_company.columns

    ):

        return np.nan


    recent = (

        annual_company

        .sort_values(
            "period_end",
            ascending=False,
        )

        .head(3)

        .copy()

    )


    dividends = pd.to_numeric(

        recent[
            "dividends_paid"
        ],

        errors="coerce",

    ).abs()


    net_income = pd.to_numeric(

        recent[
            "net_income"
        ],

        errors="coerce",

    )


    ratio = np.where(

        net_income
        >
        0,

        dividends
        /
        net_income,

        np.nan,

    )


    return f3_clip(

        f3_safe_median(
            ratio
        ),

        0.0,
        0.80,

    )


# ============================================================
# 15. ANALYST LOOKUP
# ============================================================

F3_ESTIMATE_LOOKUP = (

    F3_ESTIMATES

    .set_index(
        "ticker"
    )

)


def f3_estimate(
    ticker,
    field,
):

    if ticker not in F3_ESTIMATE_LOOKUP.index:

        return np.nan


    try:

        value = (

            F3_ESTIMATE_LOOKUP.loc[
                ticker,
                field,
            ]

        )


        if isinstance(
            value,
            pd.Series,
        ):

            value = value.iloc[0]


        return f3_numeric(
            value
        )


    except Exception:

        return np.nan


# ============================================================
# 16. REVENUE-GROWTH BOUNDS
# ============================================================

def f3_growth_bounds(
    model_family,
):

    if model_family in F3_ENERGY_MODELS:

        return (
            -0.10,
            0.12,
        )


    if model_family == "BIOPHARMA_RISK_ADJUSTED_DCF":

        return (
            -0.15,
            0.30,
        )


    if model_family == "FCFF_BLEND":

        return (
            -0.10,
            0.30,
        )


    return (
        -0.15,
        0.25,
    )


# ============================================================
# 17. NORMALIZED ECONOMICS
# ============================================================

normalized_rows = []


for _, current in (

    F3_CURRENT
    .iterrows()

):

    ticker = current[
        "ticker"
    ]


    model_family = current[
        "valuation_model_family"
    ]


    annual_company = (

        F3_ANNUAL[

            F3_ANNUAL[
                "ticker"
            ]
            ==
            ticker

        ]

        .sort_values(
            "period_end",
            ascending=False,
        )

        .copy()

    )


    # ========================================================
    # COMMON INPUTS
    # ========================================================

    annual_period_count = len(
        annual_company
    )


    history_depth_confidence = min(

        1.0,

        annual_period_count
        /
        4.0,

    )


    terminal_growth = (

        F3_TERMINAL_GROWTH.get(

            model_family,
            0.025,

        )

    )


    # ========================================================
    # OPERATING / FCFF COMPANY
    # ========================================================

    if model_family in F3_OPERATING_MODELS:

        historical_revenue_cagr = (

            f3_historical_cagr(

                annual_company,
                "revenue",
                max_intervals=3,

            )

        )


        growth_lower, growth_upper = (

            f3_growth_bounds(
                model_family
            )

        )


        historical_revenue_cagr = f3_clip(

            historical_revenue_cagr,

            growth_lower,
            growth_upper,

        )


        # ----------------------------------------------------
        # Analyst near-term revenue growth
        # ----------------------------------------------------

        analyst_revenue_growth = f3_estimate(

            ticker,
            "next_year_revenue_growth_estimate",

        )


        analyst_revenue_growth = f3_clip(

            analyst_revenue_growth,

            growth_lower,
            growth_upper,

        )


        if pd.isna(
            analyst_revenue_growth
        ):

            next_year_revenue = f3_estimate(

                ticker,
                "next_year_revenue_estimate",

            )


            ttm_revenue = f3_numeric(

                current[
                    "ttm_revenue"
                ]

            )


            if (

                pd.notna(
                    next_year_revenue
                )

                and

                pd.notna(
                    ttm_revenue
                )

                and

                ttm_revenue > 0

            ):

                analyst_revenue_growth = f3_clip(

                    (
                        next_year_revenue
                        /
                        ttm_revenue
                    )
                    -
                    1.0,

                    growth_lower,
                    growth_upper,

                )


        # ----------------------------------------------------
        # Historical EBIT margin
        # ----------------------------------------------------

        historical_ebit_margin = (

            f3_ratio_median(

                annual_company,
                "ebit_effective",
                "revenue",

                periods=3,

            )

        )


        ttm_ebit_margin = np.nan


        if (

            f3_numeric(
                current[
                    "ttm_revenue"
                ]
            )
            >
            0

        ):

            ttm_ebit_margin = (

                f3_numeric(

                    current[
                        "ttm_ebit"
                    ]

                )

                /

                f3_numeric(

                    current[
                        "ttm_revenue"
                    ]

                )

            )


        # ----------------------------------------------------
        # Energy = deliberately more mid-cycle.
        # ----------------------------------------------------

        if model_family in F3_ENERGY_MODELS:

            normalized_ebit_margin = (

                f3_weighted_average(

                    [
                        historical_ebit_margin,
                        ttm_ebit_margin,
                    ],

                    [
                        0.80,
                        0.20,
                    ],

                )

            )


        else:

            normalized_ebit_margin = (

                f3_weighted_average(

                    [
                        historical_ebit_margin,
                        ttm_ebit_margin,
                    ],

                    [
                        0.60,
                        0.40,
                    ],

                )

            )


        normalized_ebit_margin = f3_clip(

            normalized_ebit_margin,

            -0.10,
            0.75,

        )


        # ----------------------------------------------------
        # Historical EBIT-margin volatility
        # ----------------------------------------------------

        if (

            "ebit_effective"
            in annual_company.columns

            and

            "revenue"
            in annual_company.columns

        ):

            recent_margin_frame = (

                annual_company

                .sort_values(
                    "period_end",
                    ascending=False,
                )

                .head(4)

            )


            margin_series = (

                pd.to_numeric(

                    recent_margin_frame[
                        "ebit_effective"
                    ],

                    errors="coerce",

                )

                /

                pd.to_numeric(

                    recent_margin_frame[
                        "revenue"
                    ],

                    errors="coerce",

                )

            )


            margin_volatility = float(

                margin_series
                .replace(
                    [
                        np.inf,
                        -np.inf,
                    ],
                    np.nan,
                )
                .dropna()
                .std(
                    ddof=0
                )

            ) if (

                margin_series
                .replace(
                    [
                        np.inf,
                        -np.inf,
                    ],
                    np.nan,
                )
                .dropna()
                .shape[0]
                >=
                2

            ) else np.nan


        else:

            margin_volatility = np.nan


        # ----------------------------------------------------
        # Normalized tax rate
        # ----------------------------------------------------

        historical_tax_rates = []


        if (

            "effective_tax_rate_raw"
            in annual_company.columns

        ):

            raw_tax = pd.to_numeric(

                annual_company[
                    "effective_tax_rate_raw"
                ],

                errors="coerce",

            )


            raw_tax = raw_tax[

                (
                    raw_tax >= 0.0
                )

                &

                (
                    raw_tax <= 0.50
                )

            ]


            historical_tax_rates.extend(

                raw_tax
                .head(4)
                .tolist()

            )


        ttm_tax = f3_numeric(

            current[
                "ttm_effective_tax_rate_raw"
            ]

        )


        if (

            pd.notna(
                ttm_tax
            )

            and

            0.0 <= ttm_tax <= 0.50

        ):

            historical_tax_rates.append(
                ttm_tax
            )


        normalized_tax_rate = f3_safe_median(

            historical_tax_rates

        )


        if pd.isna(
            normalized_tax_rate
        ):

            normalized_tax_rate = (
                0.21
            )


        normalized_tax_rate = f3_clip(

            normalized_tax_rate,
            0.15,
            0.30,

        )


        # ----------------------------------------------------
        # CapEx intensity
        # ----------------------------------------------------

        historical_capex_ratio = (

            f3_ratio_median(

                annual_company,

                "capital_expenditure",
                "revenue",

                periods=3,

                absolute_numerator=True,

            )

        )


        ttm_capex_ratio = np.nan


        if (

            f3_numeric(
                current[
                    "ttm_revenue"
                ]
            )
            >
            0

        ):

            ttm_capex_ratio = (

                abs(

                    f3_numeric(

                        current[
                            "ttm_capex"
                        ]

                    )

                )

                /

                f3_numeric(

                    current[
                        "ttm_revenue"
                    ]

                )

            )


        if model_family in F3_ENERGY_MODELS:

            normalized_capex_ratio = (

                f3_weighted_average(

                    [
                        historical_capex_ratio,
                        ttm_capex_ratio,
                    ],

                    [
                        0.75,
                        0.25,
                    ],

                )

            )


        else:

            normalized_capex_ratio = (

                f3_weighted_average(

                    [
                        historical_capex_ratio,
                        ttm_capex_ratio,
                    ],

                    [
                        0.55,
                        0.45,
                    ],

                )

            )


        normalized_capex_ratio = f3_clip(

            normalized_capex_ratio,
            0.0,
            0.60,

        )


        # ----------------------------------------------------
        # D&A intensity
        # ----------------------------------------------------

        historical_da_ratio = (

            f3_ratio_median(

                annual_company,

                "depreciation_amortization",
                "revenue",

                periods=3,

                absolute_numerator=True,

            )

        )


        ttm_da_ratio = np.nan


        if (

            f3_numeric(
                current[
                    "ttm_revenue"
                ]
            )
            >
            0

        ):

            ttm_da_ratio = (

                abs(

                    f3_numeric(

                        current[
                            "ttm_depreciation_amortization"
                        ]

                    )

                )

                /

                f3_numeric(

                    current[
                        "ttm_revenue"
                    ]

                )

            )


        normalized_da_ratio = (

            f3_weighted_average(

                [
                    historical_da_ratio,
                    ttm_da_ratio,
                ],

                [
                    0.60,
                    0.40,
                ],

            )

        )


        normalized_da_ratio = f3_clip(

            normalized_da_ratio,
            0.0,
            0.35,

        )


        # ----------------------------------------------------
        # NWC investment
        # ----------------------------------------------------

        normalized_nwc_ratio = (

            f3_nwc_investment_ratio(

                annual_company

            )

        )


        # ----------------------------------------------------
        # Historical FCF margin
        # ----------------------------------------------------

        historical_fcf_margin = (

            f3_ratio_median(

                annual_company,

                "free_cash_flow_effective",
                "revenue",

                periods=3,

            )

        )


        ttm_fcf_margin = np.nan


        if (

            f3_numeric(
                current[
                    "ttm_revenue"
                ]
            )
            >
            0

        ):

            ttm_fcf_margin = (

                f3_numeric(

                    current[
                        "ttm_free_cash_flow"
                    ]

                )

                /

                f3_numeric(

                    current[
                        "ttm_revenue"
                    ]

                )

            )


        normalized_fcf_margin = (

            f3_weighted_average(

                [
                    historical_fcf_margin,
                    ttm_fcf_margin,
                ],

                [
                    0.60,
                    0.40,
                ],

            )

        )


        # ----------------------------------------------------
        # Base Year-1 growth anchor
        # ----------------------------------------------------

        if model_family in F3_ENERGY_MODELS:

            growth_weights = (
                0.55,
                0.45,
            )


        elif (
            model_family
            ==
            "BIOPHARMA_RISK_ADJUSTED_DCF"
        ):

            growth_weights = (
                0.75,
                0.25,
            )


        else:

            growth_weights = (
                0.65,
                0.35,
            )


        base_year1_growth = (

            f3_weighted_average(

                [
                    analyst_revenue_growth,
                    historical_revenue_cagr,
                ],

                growth_weights,

            )

        )


        if pd.isna(
            base_year1_growth
        ):

            base_year1_growth = (
                terminal_growth
                +
                0.02
            )


        base_year1_growth = f3_clip(

            base_year1_growth,

            growth_lower,
            growth_upper,

        )


        # ----------------------------------------------------
        # Confidence
        # ----------------------------------------------------

        analyst_available = float(

            pd.notna(
                analyst_revenue_growth
            )

        )


        analyst_confidence = (

            1.0

            if analyst_available

            else 0.60

        )


        if model_family in F3_ENERGY_MODELS:

            model_confidence_cap = (
                0.75
            )


        elif (
            model_family
            ==
            "BIOPHARMA_RISK_ADJUSTED_DCF"
        ):

            model_confidence_cap = (
                0.65
            )


        else:

            model_confidence_cap = (
                0.90
            )


        assumption_confidence = (

            np.sqrt(

                max(
                    history_depth_confidence,
                    0.25,
                )

                *

                analyst_confidence

            )

            *

            model_confidence_cap

        )


        assumption_confidence = f3_clip(

            assumption_confidence,
            0.0,
            1.0,

        )


        specialized_review_required = bool(

            model_family in F3_ENERGY_MODELS

            or

            model_family
            ==
            "BIOPHARMA_RISK_ADJUSTED_DCF"

        )


        specialized_review_type = (

            "ENERGY_MIDCYCLE_AND_ASSET_NAV"

            if model_family
            in F3_ENERGY_MODELS

            else

            (
                "BIOPHARMA_PIPELINE_RISK_REVIEW"

                if model_family
                ==
                "BIOPHARMA_RISK_ADJUSTED_DCF"

                else
                ""
            )

        )


        normalized_rows.append({

            "ticker":
                ticker,

            "company_name":
                current[
                    "company_name"
                ],

            "sector_ticker":
                current[
                    "sector_ticker"
                ],

            "sector_name":
                current[
                    "sector_name"
                ],

            "valuation_model_family":
                model_family,

            "assumption_mode":
                "OPERATING_FCFF",

            "stock_research_scope":
                current[
                    "stock_research_scope"
                ],

            "ttm_revenue":
                current[
                    "ttm_revenue"
                ],

            "ttm_ebit":
                current[
                    "ttm_ebit"
                ],

            "ttm_ebit_margin":
                ttm_ebit_margin,

            "historical_revenue_cagr":
                historical_revenue_cagr,

            "analyst_revenue_growth":
                analyst_revenue_growth,

            "base_year1_growth":
                base_year1_growth,

            "historical_ebit_margin":
                historical_ebit_margin,

            "normalized_ebit_margin":
                normalized_ebit_margin,

            "ebit_margin_volatility":
                margin_volatility,

            "normalized_tax_rate":
                normalized_tax_rate,

            "historical_capex_ratio":
                historical_capex_ratio,

            "ttm_capex_ratio":
                ttm_capex_ratio,

            "normalized_capex_ratio":
                normalized_capex_ratio,

            "normalized_da_ratio":
                normalized_da_ratio,

            "normalized_nwc_investment_ratio":
                normalized_nwc_ratio,

            "historical_fcf_margin":
                historical_fcf_margin,

            "ttm_fcf_margin":
                ttm_fcf_margin,

            "normalized_fcf_margin":
                normalized_fcf_margin,

            "normalized_roe":
                np.nan,

            "normalized_payout_ratio":
                np.nan,

            "base_eps_growth":
                np.nan,

            "current_book_value":
                np.nan,

            "book_value_per_share":
                np.nan,

            "terminal_growth":
                terminal_growth,

            "annual_period_count":
                annual_period_count,

            "history_depth_confidence":
                history_depth_confidence,

            "assumption_confidence":
                assumption_confidence,

            "specialized_review_required":
                specialized_review_required,

            "specialized_review_type":
                specialized_review_type,

            "historical_backtest_eligible":
                False,

        })


    # ========================================================
    # FINANCIAL COMPANY
    # ========================================================

    elif model_family in F3_FINANCIAL_MODELS:

        roe_history = (

            f3_financial_roe_history(

                annual_company

            )

        )


        historical_roe = f3_safe_median(

            roe_history.tail(3)

        )


        ttm_roe = np.nan


        if (

            f3_numeric(
                current[
                    "current_equity"
                ]
            )
            >
            0

        ):

            ttm_roe = (

                f3_numeric(

                    current[
                        "ttm_net_income"
                    ]

                )

                /

                f3_numeric(

                    current[
                        "current_equity"
                    ]

                )

            )


        normalized_roe = (

            f3_weighted_average(

                [
                    historical_roe,
                    ttm_roe,
                ],

                [
                    0.70,
                    0.30,
                ],

            )

        )


        normalized_roe = f3_clip(

            normalized_roe,
            0.03,
            0.35,

        )


        historical_payout = (

            f3_financial_payout_ratio(

                annual_company

            )

        )


        ttm_payout = np.nan


        if (

            pd.notna(

                f3_numeric(

                    current.get(
                        "ttm_dividends_paid",
                        np.nan
                    )

                )

            )

            and

            f3_numeric(

                current[
                    "ttm_net_income"
                ]

            )
            >
            0

        ):

            ttm_payout = (

                abs(

                    f3_numeric(

                        current[
                            "ttm_dividends_paid"
                        ]

                    )

                )

                /

                f3_numeric(

                    current[
                        "ttm_net_income"
                    ]

                )

            )


        normalized_payout = (

            f3_weighted_average(

                [
                    historical_payout,
                    ttm_payout,
                ],

                [
                    0.70,
                    0.30,
                ],

            )

        )


        # ----------------------------------------------------
        # Model-specific fallback payout.
        # ----------------------------------------------------

        if pd.isna(
            normalized_payout
        ):

            normalized_payout = {

                "BANK_RESIDUAL_INCOME":
                    0.35,

                "INSURANCE_EXCESS_RETURN":
                    0.30,

                "FINANCIAL_FCFE_EXCESS_RETURN":
                    0.20,

                "HEALTH_INSURER_FCFE":
                    0.20,

            }.get(
                model_family,
                0.25,
            )


        normalized_payout = f3_clip(

            normalized_payout,
            0.0,
            0.80,

        )


        # ----------------------------------------------------
        # Historical earnings growth
        # ----------------------------------------------------

        historical_net_income_cagr = (

            f3_historical_cagr(

                annual_company,
                "net_income",

                max_intervals=3,

            )

        )


        # ----------------------------------------------------
        # Analyst EPS growth
        # ----------------------------------------------------

        analyst_eps_growth = f3_estimate(

            ticker,
            "next_year_earnings_growth_estimate",

        )


        if pd.isna(
            analyst_eps_growth
        ):

            forward_eps = f3_numeric(

                current.get(
                    "forward_eps",
                    np.nan
                )

            )


            trailing_eps = f3_numeric(

                current.get(
                    "trailing_eps",
                    np.nan
                )

            )


            if (

                pd.notna(
                    forward_eps
                )

                and

                pd.notna(
                    trailing_eps
                )

                and

                abs(
                    trailing_eps
                )
                >
                1e-12

            ):

                analyst_eps_growth = (

                    forward_eps
                    /
                    trailing_eps
                    -
                    1.0

                )


        analyst_eps_growth = f3_clip(

            analyst_eps_growth,
            -0.20,
            0.30,

        )


        historical_net_income_cagr = f3_clip(

            historical_net_income_cagr,
            -0.20,
            0.30,

        )


        base_eps_growth = (

            f3_weighted_average(

                [
                    analyst_eps_growth,
                    historical_net_income_cagr,
                ],

                [
                    0.70,
                    0.30,
                ],

            )

        )


        if pd.isna(
            base_eps_growth
        ):

            # Sustainable-growth fallback.
            base_eps_growth = (

                normalized_roe

                *

                (
                    1.0
                    -
                    normalized_payout
                )

            )


        base_eps_growth = f3_clip(

            base_eps_growth,
            -0.10,
            0.20,

        )


        current_equity = f3_numeric(

            current[
                "current_equity"
            ]

        )


        economic_shares = f3_numeric(

            current[
                "economic_diluted_shares"
            ]

        )


        book_value_per_share = np.nan


        if (

            pd.notna(
                current_equity
            )

            and

            pd.notna(
                economic_shares
            )

            and

            economic_shares > 0

        ):

            book_value_per_share = (

                current_equity
                /
                economic_shares

            )


        analyst_confidence = (

            1.0

            if pd.notna(
                analyst_eps_growth
            )

            else 0.60

        )


        model_confidence_cap = {

            "BANK_RESIDUAL_INCOME":
                0.90,

            "INSURANCE_EXCESS_RETURN":
                0.85,

            "FINANCIAL_FCFE_EXCESS_RETURN":
                0.80,

            "HEALTH_INSURER_FCFE":
                0.80,

        }.get(
            model_family,
            0.80,
        )


        assumption_confidence = (

            np.sqrt(

                max(
                    history_depth_confidence,
                    0.25,
                )

                *

                analyst_confidence

            )

            *

            model_confidence_cap

        )


        assumption_confidence = f3_clip(

            assumption_confidence,
            0.0,
            1.0,

        )


        normalized_rows.append({

            "ticker":
                ticker,

            "company_name":
                current[
                    "company_name"
                ],

            "sector_ticker":
                current[
                    "sector_ticker"
                ],

            "sector_name":
                current[
                    "sector_name"
                ],

            "valuation_model_family":
                model_family,

            "assumption_mode":
                (
                    "FINANCIAL_RESIDUAL_INCOME"

                    if model_family
                    in {
                        "BANK_RESIDUAL_INCOME",
                        "INSURANCE_EXCESS_RETURN",
                    }

                    else
                    "FINANCIAL_FCFE"
                ),

            "stock_research_scope":
                current[
                    "stock_research_scope"
                ],

            "ttm_revenue":
                np.nan,

            "ttm_ebit":
                np.nan,

            "ttm_ebit_margin":
                np.nan,

            "historical_revenue_cagr":
                np.nan,

            "analyst_revenue_growth":
                np.nan,

            "base_year1_growth":
                np.nan,

            "historical_ebit_margin":
                np.nan,

            "normalized_ebit_margin":
                np.nan,

            "ebit_margin_volatility":
                np.nan,

            "normalized_tax_rate":
                np.nan,

            "historical_capex_ratio":
                np.nan,

            "ttm_capex_ratio":
                np.nan,

            "normalized_capex_ratio":
                np.nan,

            "normalized_da_ratio":
                np.nan,

            "normalized_nwc_investment_ratio":
                np.nan,

            "historical_fcf_margin":
                np.nan,

            "ttm_fcf_margin":
                np.nan,

            "normalized_fcf_margin":
                np.nan,

            "historical_roe":
                historical_roe,

            "ttm_roe":
                ttm_roe,

            "normalized_roe":
                normalized_roe,

            "historical_payout_ratio":
                historical_payout,

            "normalized_payout_ratio":
                normalized_payout,

            "historical_net_income_cagr":
                historical_net_income_cagr,

            "analyst_eps_growth":
                analyst_eps_growth,

            "base_eps_growth":
                base_eps_growth,

            "current_book_value":
                current_equity,

            "book_value_per_share":
                book_value_per_share,

            "terminal_growth":
                terminal_growth,

            "annual_period_count":
                annual_period_count,

            "history_depth_confidence":
                history_depth_confidence,

            "assumption_confidence":
                assumption_confidence,

            "specialized_review_required":
                True,

            "specialized_review_type":
                "FINANCIAL_BALANCE_SHEET_AND_CAPITAL_REVIEW",

            "historical_backtest_eligible":
                False,

        })


    else:

        raise RuntimeError(

            "Unknown valuation model family in F3: "
            f"{ticker} -> {model_family}"

        )


F3_NORMALIZED_ECONOMICS = pd.DataFrame(

    normalized_rows

)


# ============================================================
# 18. FINANCIAL PEER ROE ANCHORS
# ============================================================

financial_mask = (

    F3_NORMALIZED_ECONOMICS[
        "valuation_model_family"
    ]
    .isin(
        F3_FINANCIAL_MODELS
    )

)


F3_FINANCIAL_PEER_ANCHORS = (

    F3_NORMALIZED_ECONOMICS[

        financial_mask

    ]

    .groupby(
        "valuation_model_family",
        as_index=False,
    )

    .agg(

        peer_median_roe=(
            "normalized_roe",
            "median",
        ),

        peer_median_payout=(
            "normalized_payout_ratio",
            "median",
        ),

        peer_median_eps_growth=(
            "base_eps_growth",
            "median",
        ),

    )

)


# ============================================================
# 19. FORECAST-PATH HELPERS
# ============================================================

def f3_linear_path(
    start,
    end,
    years=5,
):

    return np.linspace(

        float(start),
        float(end),

        int(years),

    )


def f3_margin_shock(
    volatility,
):

    if pd.isna(
        volatility
    ):

        return 0.025


    return float(

        np.clip(

            max(

                0.020,

                0.50
                *
                float(
                    volatility
                ),

            ),

            0.020,
            0.080,

        )

    )


# ============================================================
# 20. BUILD 5-YEAR SCENARIO ASSUMPTIONS
# ============================================================

forecast_rows = []


for _, normalized in (

    F3_NORMALIZED_ECONOMICS
    .iterrows()

):

    ticker = normalized[
        "ticker"
    ]


    model_family = normalized[
        "valuation_model_family"
    ]


    terminal_growth = float(

        normalized[
            "terminal_growth"
        ]

    )


    growth_shock = float(

        F3_GROWTH_SHOCK.get(

            model_family,
            0.035,

        )

    )


    # ========================================================
    # OPERATING / FCFF
    # ========================================================

    if model_family in F3_OPERATING_MODELS:

        base_y1_growth = float(

            normalized[
                "base_year1_growth"
            ]

        )


        # ----------------------------------------------------
        # Long-run fade target at Year 5.
        #
        # Year-5 growth remains modestly above terminal growth.
        # ----------------------------------------------------

        base_y5_growth = (

            terminal_growth
            +
            0.010

        )


        bull_y5_growth = (

            terminal_growth
            +
            0.020

        )


        bear_y5_growth = max(

            0.0,

            terminal_growth
            -
            0.005,

        )


        growth_paths = {

            "BASE":

                f3_linear_path(

                    base_y1_growth,
                    base_y5_growth,

                    F3_FORECAST_YEARS,

                ),

            "BULL":

                f3_linear_path(

                    base_y1_growth
                    +
                    growth_shock,

                    bull_y5_growth,

                    F3_FORECAST_YEARS,

                ),

            "BEAR":

                f3_linear_path(

                    base_y1_growth
                    -
                    1.25
                    *
                    growth_shock,

                    bear_y5_growth,

                    F3_FORECAST_YEARS,

                ),

        }


        # ----------------------------------------------------
        # Margin paths
        # ----------------------------------------------------

        normalized_margin = float(

            normalized[
                "normalized_ebit_margin"
            ]

        )


        starting_margin = normalized[
            "ttm_ebit_margin"
        ]


        if pd.isna(
            starting_margin
        ):

            starting_margin = (
                normalized_margin
            )


        margin_shock = f3_margin_shock(

            normalized[
                "ebit_margin_volatility"
            ]

        )


        bull_target_margin = f3_clip(

            normalized_margin
            +
            margin_shock,

            -0.10,
            0.80,

        )


        bear_target_margin = f3_clip(

            normalized_margin
            -
            1.25
            *
            margin_shock,

            -0.20,
            0.75,

        )


        margin_paths = {

            "BASE":

                f3_linear_path(

                    starting_margin,
                    normalized_margin,

                    F3_FORECAST_YEARS,

                ),

            "BULL":

                f3_linear_path(

                    starting_margin,
                    bull_target_margin,

                    F3_FORECAST_YEARS,

                ),

            "BEAR":

                f3_linear_path(

                    starting_margin,
                    bear_target_margin,

                    F3_FORECAST_YEARS,

                ),

        }


        for scenario in F3_SCENARIOS:

            for year in range(
                1,
                F3_FORECAST_YEARS + 1,
            ):

                forecast_rows.append({

                    "ticker":
                        ticker,

                    "company_name":
                        normalized[
                            "company_name"
                        ],

                    "valuation_model_family":
                        model_family,

                    "assumption_mode":
                        normalized[
                            "assumption_mode"
                        ],

                    "scenario":
                        scenario,

                    "forecast_year":
                        year,

                    "revenue_growth":
                        float(

                            growth_paths[
                                scenario
                            ][
                                year - 1
                            ]

                        ),

                    "ebit_margin":
                        float(

                            margin_paths[
                                scenario
                            ][
                                year - 1
                            ]

                        ),

                    "tax_rate":
                        float(

                            normalized[
                                "normalized_tax_rate"
                            ]

                        ),

                    "da_ratio":
                        float(

                            normalized[
                                "normalized_da_ratio"
                            ]

                        ),

                    "capex_ratio":
                        float(

                            normalized[
                                "normalized_capex_ratio"
                            ]

                        ),

                    "nwc_investment_ratio":
                        float(

                            normalized[
                                "normalized_nwc_investment_ratio"
                            ]

                        ),

                    "roe":
                        np.nan,

                    "payout_ratio":
                        np.nan,

                    "earnings_growth":
                        np.nan,

                    "terminal_growth":
                        terminal_growth,

                    "assumption_confidence":
                        normalized[
                            "assumption_confidence"
                        ],

                    "specialized_review_required":
                        normalized[
                            "specialized_review_required"
                        ],

                    "specialized_review_type":
                        normalized[
                            "specialized_review_type"
                        ],

                    "historical_backtest_eligible":
                        False,

                })


    # ========================================================
    # FINANCIALS
    # ========================================================

    else:

        model_peer = (

            F3_FINANCIAL_PEER_ANCHORS[

                F3_FINANCIAL_PEER_ANCHORS[
                    "valuation_model_family"
                ]
                ==
                model_family

            ]

        )


        if not model_peer.empty:

            peer_roe = float(

                model_peer.iloc[0][
                    "peer_median_roe"
                ]

            )


            peer_payout = float(

                model_peer.iloc[0][
                    "peer_median_payout"
                ]

            )


        else:

            peer_roe = float(

                normalized[
                    "normalized_roe"
                ]

            )


            peer_payout = float(

                normalized[
                    "normalized_payout_ratio"
                ]

            )


        normalized_roe = float(

            normalized[
                "normalized_roe"
            ]

        )


        base_eps_growth = float(

            normalized[
                "base_eps_growth"
            ]

        )


        # ----------------------------------------------------
        # Fade ROE toward model-peer sustainable ROE.
        # ----------------------------------------------------

        base_roe_path = f3_linear_path(

            normalized_roe,
            peer_roe,

            F3_FORECAST_YEARS,

        )


        roe_shock = {

            "BANK_RESIDUAL_INCOME":
                0.020,

            "INSURANCE_EXCESS_RETURN":
                0.025,

            "FINANCIAL_FCFE_EXCESS_RETURN":
                0.030,

            "HEALTH_INSURER_FCFE":
                0.025,

        }.get(
            model_family,
            0.025,
        )


        roe_paths = {

            "BASE":

                base_roe_path,

            "BULL":

                np.clip(

                    base_roe_path
                    +
                    roe_shock,

                    0.0,
                    0.40,

                ),

            "BEAR":

                np.clip(

                    base_roe_path
                    -
                    1.25
                    *
                    roe_shock,

                    0.0,
                    0.40,

                ),

        }


        earnings_paths = {

            "BASE":

                f3_linear_path(

                    base_eps_growth,

                    terminal_growth
                    +
                    0.010,

                    F3_FORECAST_YEARS,

                ),

            "BULL":

                f3_linear_path(

                    base_eps_growth
                    +
                    growth_shock,

                    terminal_growth
                    +
                    0.020,

                    F3_FORECAST_YEARS,

                ),

            "BEAR":

                f3_linear_path(

                    base_eps_growth
                    -
                    1.25
                    *
                    growth_shock,

                    max(

                        0.0,

                        terminal_growth
                        -
                        0.005,

                    ),

                    F3_FORECAST_YEARS,

                ),

        }


        payout_ratio = f3_clip(

            f3_weighted_average(

                [
                    normalized[
                        "normalized_payout_ratio"
                    ],
                    peer_payout,
                ],

                [
                    0.70,
                    0.30,
                ],

            ),

            0.0,
            0.80,

        )


        for scenario in F3_SCENARIOS:

            for year in range(
                1,
                F3_FORECAST_YEARS + 1,
            ):

                forecast_rows.append({

                    "ticker":
                        ticker,

                    "company_name":
                        normalized[
                            "company_name"
                        ],

                    "valuation_model_family":
                        model_family,

                    "assumption_mode":
                        normalized[
                            "assumption_mode"
                        ],

                    "scenario":
                        scenario,

                    "forecast_year":
                        year,

                    "revenue_growth":
                        np.nan,

                    "ebit_margin":
                        np.nan,

                    "tax_rate":
                        np.nan,

                    "da_ratio":
                        np.nan,

                    "capex_ratio":
                        np.nan,

                    "nwc_investment_ratio":
                        np.nan,

                    "roe":
                        float(

                            roe_paths[
                                scenario
                            ][
                                year - 1
                            ]

                        ),

                    "payout_ratio":
                        float(
                            payout_ratio
                        ),

                    "earnings_growth":
                        float(

                            earnings_paths[
                                scenario
                            ][
                                year - 1
                            ]

                        ),

                    "terminal_growth":
                        terminal_growth,

                    "assumption_confidence":
                        normalized[
                            "assumption_confidence"
                        ],

                    "specialized_review_required":
                        normalized[
                            "specialized_review_required"
                        ],

                    "specialized_review_type":
                        normalized[
                            "specialized_review_type"
                        ],

                    "historical_backtest_eligible":
                        False,

                })


F3_FORECAST_ASSUMPTIONS = pd.DataFrame(

    forecast_rows

)


# ============================================================
# 21. IMPLIED NORMALIZED FCFF MARGIN
# ============================================================
#
# Approximation:
#
# FCFF margin =
#
#     EBIT margin × (1 - tax)
#     + D&A / Revenue
#     - CapEx / Revenue
#     - ΔNWC / Revenue
#
# Used as a QA diagnostic only.
# ============================================================

operating_normalized_mask = (

    F3_NORMALIZED_ECONOMICS[
        "assumption_mode"
    ]
    ==
    "OPERATING_FCFF"

)


F3_NORMALIZED_ECONOMICS[
    "implied_normalized_fcff_margin"
] = np.nan


F3_NORMALIZED_ECONOMICS.loc[

    operating_normalized_mask,

    "implied_normalized_fcff_margin",

] = (

    F3_NORMALIZED_ECONOMICS.loc[

        operating_normalized_mask,
        "normalized_ebit_margin",

    ]

    *

    (

        1.0

        -

        F3_NORMALIZED_ECONOMICS.loc[

            operating_normalized_mask,
            "normalized_tax_rate",

        ]

    )

    +

    F3_NORMALIZED_ECONOMICS.loc[

        operating_normalized_mask,
        "normalized_da_ratio",

    ]

    -

    F3_NORMALIZED_ECONOMICS.loc[

        operating_normalized_mask,
        "normalized_capex_ratio",

    ]

    -

    F3_NORMALIZED_ECONOMICS.loc[

        operating_normalized_mask,
        "normalized_nwc_investment_ratio",

    ]

)


# ============================================================
# 22. FCFF-MARGIN RECONCILIATION GAP
# ============================================================

F3_NORMALIZED_ECONOMICS[
    "fcff_margin_reconciliation_gap"
] = (

    F3_NORMALIZED_ECONOMICS[
        "implied_normalized_fcff_margin"
    ]

    -

    F3_NORMALIZED_ECONOMICS[
        "normalized_fcf_margin"
    ]

)


F3_NORMALIZED_ECONOMICS[
    "large_fcff_reconciliation_gap"
] = (

    F3_NORMALIZED_ECONOMICS[
        "fcff_margin_reconciliation_gap"
    ]
    .abs()

    >
    0.15

)


# ============================================================
# 23. SCENARIO ORDERING AUDIT
# ============================================================

ordering_rows = []


for ticker in (

    F3_NORMALIZED_ECONOMICS[
        "ticker"
    ]

):

    company_forecasts = (

        F3_FORECAST_ASSUMPTIONS[

            F3_FORECAST_ASSUMPTIONS[
                "ticker"
            ]
            ==
            ticker

        ]

    )


    model_family = (

        company_forecasts[
            "valuation_model_family"
        ]
        .iloc[0]

    )


    ordering_pass = True


    for year in range(
        1,
        F3_FORECAST_YEARS + 1,
    ):

        year_frame = (

            company_forecasts[

                company_forecasts[
                    "forecast_year"
                ]
                ==
                year

            ]

            .set_index(
                "scenario"
            )

        )


        if model_family in F3_OPERATING_MODELS:

            growth_order = (

                year_frame.loc[
                    "BULL",
                    "revenue_growth",
                ]

                >=

                year_frame.loc[
                    "BASE",
                    "revenue_growth",
                ]

                >=

                year_frame.loc[
                    "BEAR",
                    "revenue_growth",
                ]

            )


            margin_order = (

                year_frame.loc[
                    "BULL",
                    "ebit_margin",
                ]

                >=

                year_frame.loc[
                    "BASE",
                    "ebit_margin",
                ]

                >=

                year_frame.loc[
                    "BEAR",
                    "ebit_margin",
                ]

            )


            ordering_pass = bool(

                ordering_pass

                and

                growth_order

                and

                margin_order

            )


        else:

            roe_order = (

                year_frame.loc[
                    "BULL",
                    "roe",
                ]

                >=

                year_frame.loc[
                    "BASE",
                    "roe",
                ]

                >=

                year_frame.loc[
                    "BEAR",
                    "roe",
                ]

            )


            earnings_order = (

                year_frame.loc[
                    "BULL",
                    "earnings_growth",
                ]

                >=

                year_frame.loc[
                    "BASE",
                    "earnings_growth",
                ]

                >=

                year_frame.loc[
                    "BEAR",
                    "earnings_growth",
                ]

            )


            ordering_pass = bool(

                ordering_pass

                and

                roe_order

                and

                earnings_order

            )


    ordering_rows.append({

        "ticker":
            ticker,

        "scenario_ordering_pass":
            ordering_pass,

    })


F3_SCENARIO_ORDERING_AUDIT = pd.DataFrame(

    ordering_rows

)


# ============================================================
# 24. ASSUMPTION AUDIT
# ============================================================

F3_ASSUMPTION_AUDIT = (

    F3_NORMALIZED_ECONOMICS[
        [
            "ticker",
            "company_name",

            "sector_ticker",

            "valuation_model_family",
            "assumption_mode",

            "historical_revenue_cagr",
            "analyst_revenue_growth",
            "base_year1_growth",

            "ttm_ebit_margin",
            "historical_ebit_margin",
            "normalized_ebit_margin",

            "normalized_tax_rate",

            "normalized_capex_ratio",
            "normalized_da_ratio",
            "normalized_nwc_investment_ratio",

            "normalized_fcf_margin",
            "implied_normalized_fcff_margin",
            "fcff_margin_reconciliation_gap",
            "large_fcff_reconciliation_gap",

            "normalized_roe",
            "normalized_payout_ratio",
            "base_eps_growth",

            "terminal_growth",

            "assumption_confidence",

            "specialized_review_required",
            "specialized_review_type",

        ]
    ]

    .copy()

)


# ============================================================
# 25. HEALTH CHECK ENGINE
# ============================================================

f3_checks = []


def add_f3_check(
    check,
    passed,
    detail,
    required=True,
):

    f3_checks.append({

        "check":
            check,

        "passed":
            bool(
                passed
            ),

        "required":
            bool(
                required
            ),

        "detail":
            str(
                detail
            ),

    })


# ------------------------------------------------------------
# Universe
# ------------------------------------------------------------

entity_count = len(
    F3_CURRENT
)


normalized_count = len(
    F3_NORMALIZED_ECONOMICS
)


forecast_entity_count = (

    F3_FORECAST_ASSUMPTIONS[
        "ticker"
    ]
    .nunique()

)


add_f3_check(

    "F2 valuation universe preserved",

    normalized_count
    ==
    entity_count,

    (
        f"F3={normalized_count}, "
        f"F2={entity_count}"
    ),

)


add_f3_check(

    "Every company has forecast assumptions",

    forecast_entity_count
    ==
    entity_count,

    (
        f"forecast_entities="
        f"{forecast_entity_count}/"
        f"{entity_count}"
    ),

)


# ------------------------------------------------------------
# Expected row count
# ------------------------------------------------------------

expected_forecast_rows = (

    entity_count
    *
    len(
        F3_SCENARIOS
    )
    *
    F3_FORECAST_YEARS

)


add_f3_check(

    "Forecast assumption panel has complete dimensions",

    len(
        F3_FORECAST_ASSUMPTIONS
    )
    ==
    expected_forecast_rows,

    (
        f"rows="
        f"{len(F3_FORECAST_ASSUMPTIONS)}/"
        f"{expected_forecast_rows}"
    ),

)


# ------------------------------------------------------------
# Operating assumptions
# ------------------------------------------------------------

operating_forecasts = (

    F3_FORECAST_ASSUMPTIONS[

        F3_FORECAST_ASSUMPTIONS[
            "valuation_model_family"
        ]
        .isin(
            F3_OPERATING_MODELS
        )

    ]

)


required_operating_fields = [

    "revenue_growth",
    "ebit_margin",
    "tax_rate",

    "da_ratio",
    "capex_ratio",

    "nwc_investment_ratio",

]


operating_missing = int(

    operating_forecasts[
        required_operating_fields
    ]
    .isna()
    .sum()
    .sum()

)


add_f3_check(

    "Operating forecasts have all required economic drivers",

    operating_missing
    ==
    0,

    (
        f"missing_cells="
        f"{operating_missing}"
    ),

)


# ------------------------------------------------------------
# Financial assumptions
# ------------------------------------------------------------

financial_forecasts = (

    F3_FORECAST_ASSUMPTIONS[

        F3_FORECAST_ASSUMPTIONS[
            "valuation_model_family"
        ]
        .isin(
            F3_FINANCIAL_MODELS
        )

    ]

)


required_financial_fields = [

    "roe",
    "payout_ratio",
    "earnings_growth",

]


financial_missing = int(

    financial_forecasts[
        required_financial_fields
    ]
    .isna()
    .sum()
    .sum()

)


add_f3_check(

    "Financial forecasts have ROE / payout / earnings drivers",

    financial_missing
    ==
    0,

    (
        f"missing_cells="
        f"{financial_missing}"
    ),

)


# ------------------------------------------------------------
# Scenario ordering
# ------------------------------------------------------------

scenario_ordering_pass = bool(

    F3_SCENARIO_ORDERING_AUDIT[
        "scenario_ordering_pass"
    ]
    .all()

)


add_f3_check(

    "Bull/Base/Bear scenario ordering is internally consistent",

    scenario_ordering_pass,

    (
        f"passed="
        f"{int(F3_SCENARIO_ORDERING_AUDIT['scenario_ordering_pass'].sum())}/"
        f"{len(F3_SCENARIO_ORDERING_AUDIT)}"
    ),

)


# ------------------------------------------------------------
# Terminal growth
# ------------------------------------------------------------

terminal_growth_valid = bool(

    F3_FORECAST_ASSUMPTIONS[
        "terminal_growth"
    ]
    .between(
        0.01,
        0.035,
        inclusive="both",
    )
    .all()

)


add_f3_check(

    "Terminal growth assumptions remain conservative",

    terminal_growth_valid,

    (
        "required range = "
        "1.0% to 3.5%"
    ),

)


# ------------------------------------------------------------
# Confidence
# ------------------------------------------------------------

confidence_valid = bool(

    F3_NORMALIZED_ECONOMICS[
        "assumption_confidence"
    ]
    .between(
        0.0,
        1.0,
        inclusive="both",
    )
    .all()

)


add_f3_check(

    "Assumption confidence bounded to [0,1]",

    confidence_valid,

    (
        f"min="
        f"{F3_NORMALIZED_ECONOMICS['assumption_confidence'].min():.3f}, "
        f"max="
        f"{F3_NORMALIZED_ECONOMICS['assumption_confidence'].max():.3f}"
    ),

)


# ------------------------------------------------------------
# No price contamination
# ------------------------------------------------------------

price_columns_in_forecasts = [

    column

    for column in F3_FORECAST_ASSUMPTIONS.columns

    if "price" in column.lower()

]


add_f3_check(

    "Forecast assumptions contain no stock-price inputs",

    len(
        price_columns_in_forecasts
    )
    ==
    0,

    (
        f"price_columns="
        f"{price_columns_in_forecasts}"
    ),

)


# ------------------------------------------------------------
# No valuation output yet
# ------------------------------------------------------------

valuation_output_columns = [

    column

    for column in F3_FORECAST_ASSUMPTIONS.columns

    if any(

        keyword in column.lower()

        for keyword in [

            "fair_value",
            "enterprise_value",
            "equity_value",
            "upside",
            "target_price",

        ]

    )

]


add_f3_check(

    "F3 contains no intrinsic-value output",

    len(
        valuation_output_columns
    )
    ==
    0,

    (
        f"valuation_columns="
        f"{valuation_output_columns}"
    ),

)


# ------------------------------------------------------------
# Historical governance
# ------------------------------------------------------------

historical_backtest_blocked = bool(

    (
        F3_FORECAST_ASSUMPTIONS[
            "historical_backtest_eligible"
        ]
        ==
        False
    )
    .all()

)


add_f3_check(

    "Historical valuation backtest remains blocked",

    historical_backtest_blocked,

    "LIVE_ONLY valuation assumptions",

)


# ------------------------------------------------------------
# FCFF reconciliation — diagnostic, not hard gate
# ------------------------------------------------------------

large_gap_count = int(

    F3_NORMALIZED_ECONOMICS[
        "large_fcff_reconciliation_gap"
    ]
    .fillna(False)
    .sum()

)


add_f3_check(

    "FCFF accounting reconciliation gaps disclosed",

    True,

    (
        f"large_gap_companies="
        f"{large_gap_count}"
    ),

    required=False,

)


specialized_review_count = int(

    F3_NORMALIZED_ECONOMICS[
        "specialized_review_required"
    ]
    .sum()

)


add_f3_check(

    "Specialized valuation-review requirements disclosed",

    True,

    (
        f"specialized_review_companies="
        f"{specialized_review_count}"
    ),

    required=False,

)


F3_HEALTH = pd.DataFrame(

    f3_checks

)


F3_HEALTH[
    "status"
] = np.where(

    F3_HEALTH[
        "passed"
    ],

    "✓ PASS",

    np.where(

        F3_HEALTH[
            "required"
        ],

        "✗ FAIL",

        "⚠ WARN",

    )

)


required_f3_failures = (

    F3_HEALTH[

        F3_HEALTH[
            "required"
        ]

        &

        ~

        F3_HEALTH[
            "passed"
        ]

    ]

)


F3_PASSED = (

    required_f3_failures.empty

)


# ============================================================
# 26. SUMMARY
# ============================================================

F3_SUMMARY = pd.DataFrame([{

    "valuation_assumption_engine_version":
        VALUATION_ASSUMPTION_ENGINE_VERSION,

    "market_data_as_of":
        pd.Timestamp(
            MARKET_AS_OF_DATE
        ),

    "companies":
        entity_count,

    "operating_fcff_companies":
        int(

            F3_NORMALIZED_ECONOMICS[
                "valuation_model_family"
            ]
            .isin(
                F3_OPERATING_MODELS
            )
            .sum()

        ),

    "financial_companies":
        int(

            F3_NORMALIZED_ECONOMICS[
                "valuation_model_family"
            ]
            .isin(
                F3_FINANCIAL_MODELS
            )
            .sum()

        ),

    "forecast_years":
        F3_FORECAST_YEARS,

    "scenarios":
        len(
            F3_SCENARIOS
        ),

    "forecast_rows":
        len(
            F3_FORECAST_ASSUMPTIONS
        ),

    "mean_assumption_confidence":
        float(

            F3_NORMALIZED_ECONOMICS[
                "assumption_confidence"
            ]
            .mean()

        ),

    "specialized_review_companies":
        specialized_review_count,

    "large_fcff_reconciliation_gaps":
        large_gap_count,

    "historical_backtest_eligible":
        False,

    "f3_passed":
        F3_PASSED,

}])


