# ===== ORIGINAL NOTEBOOK CELL 62 =====
# ============================================================
# SECTION F — VALUATION ENGINE
# CELL F3A — FCFF ACCOUNTING BRIDGE + ASSUMPTION QUALITY GATE
#            V1.1.0
# ============================================================
#
# Corrections vs V1.0.0
#
# 1. Operating FCFF no longer depends on interest availability.
#
#       Operating FCFF =
#           EBIT(1-T)
#           + D&A
#           + signed CapEx
#           + working-capital cash-flow contribution
#
#
# 2. Financing completeness is evaluated separately:
#
#       Levered cash FCF =
#           CFO + CapEx
#
#       Cash FCFF =
#           Levered cash FCF + after-tax interest
#
#
# 3. Missing interest is set to zero ONLY where balance-sheet
#    debt is demonstrably negligible relative to revenue.
#
#
# 4. Raw working-capital cash flows are NOT blindly used.
#
#    When raw TTM working-capital movements are economically
#    extreme or sharply inconsistent with the normalized F3
#    reinvestment ratio, the bridge uses F3's normalized NWC
#    assumption instead.
#
#    Raw values remain stored for audit.
#
#
# 5. SBC-adjusted "owner cash flow" remains explicit.
#
#
# 6. Moderate residual non-cash / timing differences receive
#    a confidence haircut rather than being silently erased.
#
#
# F3A still:
#
#   - does NOT change forecast assumptions
#   - does NOT calculate WACC
#   - does NOT calculate fair value
#
# F4 must require:
#
#       F3_FINAL_PASSED == True
#
# ============================================================


# ============================================================
# 1. IMPORTS
# ============================================================

from pathlib import Path

import numpy as np
import pandas as pd


# ============================================================
# 2. VALIDATE F3
# ============================================================

required_f3a_objects = [

    "F3_PASSED",

    "F3_NORMALIZED_ECONOMICS",
    "F3_FORECAST_ASSUMPTIONS",
    "F3_FORECAST_YEARS",
    "F3_SCENARIOS",

    "VALUATION_CURRENT_INPUTS",
    "VALUATION_ANNUAL_HISTORY",
    "VALUATION_QUARTERLY_HISTORY",

    "STOCK_MODEL_DIR",
    "STOCK_OUTPUT_DIR",

]


missing_f3a_objects = [

    obj

    for obj in required_f3a_objects

    if obj not in globals()

]


if missing_f3a_objects:

    raise RuntimeError(

        "F3A requires F3 first. Missing: "
        f"{missing_f3a_objects}"

    )


if not bool(
    F3_PASSED
):

    raise RuntimeError(
        "F3 production gate did not pass."
    )


# ============================================================
# 3. VERSION
# ============================================================

F3A_VERSION = "1.1.0"


# ============================================================
# 4. MODEL GROUPS
# ============================================================

F3A_OPERATING_MODELS = {

    "FCFF_BLEND",

    "ENERGY_MIDCYCLE_FCFF",

    "REFINER_MIDCYCLE_FCFF",

    "BIOPHARMA_RISK_ADJUSTED_DCF",

}


# ============================================================
# 5. QUALITY THRESHOLDS
# ============================================================

# ------------------------------------------------------------
# Raw working-capital movement is treated as structurally
# distorted when it exceeds 15% of revenue.
# ------------------------------------------------------------

F3A_RAW_WC_EXTREME_THRESHOLD = 0.15


# ------------------------------------------------------------
# Or when it differs from normalized F3 working-capital
# cash-flow assumption by >15% of revenue.
# ------------------------------------------------------------

F3A_RAW_WC_DIVERGENCE_THRESHOLD = 0.15


# ------------------------------------------------------------
# Negligible debt threshold for zero-interest fallback.
# ------------------------------------------------------------

F3A_NEGLIGIBLE_DEBT_TO_REVENUE = 0.01


# ------------------------------------------------------------
# Bridge classification thresholds.
# ------------------------------------------------------------

F3A_DIRECT_RECONCILIATION_THRESHOLD = 0.10

F3A_TIMING_REVIEW_THRESHOLD = 0.20


# ------------------------------------------------------------
# FCF accounting identity tolerance.
# ------------------------------------------------------------

F3A_MAX_FCF_IDENTITY_GAP = 0.01


# ============================================================
# 6. WORKING COPIES
# ============================================================

F3A_CURRENT = (

    VALUATION_CURRENT_INPUTS
    .copy()

)


F3A_NORMALIZED = (

    F3_NORMALIZED_ECONOMICS
    .copy()

)


F3A_ANNUAL = (

    VALUATION_ANNUAL_HISTORY
    .copy()

)


F3A_QUARTERLY = (

    VALUATION_QUARTERLY_HISTORY
    .copy()

)


for frame in [

    F3A_ANNUAL,
    F3A_QUARTERLY,

]:

    if not frame.empty:

        frame[
            "period_end"
        ] = pd.to_datetime(

            frame[
                "period_end"
            ],

            errors="coerce",

        )


# ============================================================
# 7. HELPERS
# ============================================================

def f3a_numeric(
    value
):

    try:

        value = float(
            value
        )


        if _f_isfinite(
            value
        ):

            return value


    except Exception:

        pass


    return np.nan


def f3a_ttm_sum(
    dataframe,
    column,
):

    if (

        dataframe.empty

        or

        column not in dataframe.columns

    ):

        return np.nan


    ordered = (

        dataframe

        .sort_values(
            "period_end",
            ascending=False,
        )

    )


    values = pd.to_numeric(

        ordered[
            column
        ],

        errors="coerce",

    )


    values = values[

        _f_isfinite(
            values
        )

    ]


    if len(values) < 4:

        return np.nan


    return float(

        values.iloc[:4]
        .sum()

    )


def f3a_latest_value(
    dataframe,
    column,
):

    if (

        dataframe.empty

        or

        column not in dataframe.columns

    ):

        return np.nan


    ordered = (

        dataframe

        .sort_values(
            "period_end",
            ascending=False,
        )

    )


    values = pd.to_numeric(

        ordered[
            column
        ],

        errors="coerce",

    )


    values = values[

        _f_isfinite(
            values
        )

    ]


    if values.empty:

        return np.nan


    return float(
        values.iloc[0]
    )


def f3a_ttm_or_annual(
    quarterly,
    annual,
    column,
):

    value = f3a_ttm_sum(

        quarterly,
        column,

    )


    if pd.notna(
        value
    ):

        return (
            value,
            "TTM_QUARTERLY",
        )


    value = f3a_latest_value(

        annual,
        column,

    )


    if pd.notna(
        value
    ):

        return (
            value,
            "LATEST_ANNUAL_FALLBACK",
        )


    return (
        np.nan,
        "MISSING",
    )


def f3a_margin(
    value,
    revenue,
):

    if (

        pd.notna(
            value
        )

        and

        pd.notna(
            revenue
        )

        and

        abs(
            revenue
        )
        >
        1e-12

    ):

        return float(

            value
            /
            revenue

        )


    return np.nan


# ============================================================
# 8. NORMALIZED LOOKUP
# ============================================================

F3A_NORMALIZED_LOOKUP = (

    F3A_NORMALIZED

    .drop_duplicates(
        subset=["ticker"]
    )

    .set_index(
        "ticker"
    )

)


# ============================================================
# 9. BUILD ACCOUNTING BRIDGE
# ============================================================

bridge_rows = []


for _, current in (

    F3A_CURRENT
    .iterrows()

):

    ticker = current[
        "ticker"
    ]


    company_name = current[
        "company_name"
    ]


    model_family = current[
        "valuation_model_family"
    ]


    operating_model = (

        model_family
        in
        F3A_OPERATING_MODELS

    )


    # ========================================================
    # FINANCIAL COMPANIES
    # ========================================================

    if not operating_model:

        bridge_rows.append({

            "ticker":
                ticker,

            "company_name":
                company_name,

            "valuation_model_family":
                model_family,

            "bridge_applicable":
                False,

            "ttm_revenue":
                np.nan,

            "ttm_ebit":
                np.nan,

            "ttm_tax_rate_bridge":
                np.nan,

            "tax_rate_source":
                "NOT_APPLICABLE",

            "ttm_cfo":
                np.nan,

            "ttm_capex":
                np.nan,

            "ttm_da":
                np.nan,

            "current_debt_bridge":
                np.nan,

            "debt_to_revenue":
                np.nan,

            "ttm_interest_expense":
                np.nan,

            "interest_source":
                "NOT_APPLICABLE",

            "ttm_after_tax_interest":
                np.nan,

            "ttm_stock_based_compensation":
                np.nan,

            "sbc_source":
                "NOT_APPLICABLE",

            "raw_change_working_capital_cf":
                np.nan,

            "raw_working_capital_cashflow_margin":
                np.nan,

            "normalized_working_capital_cf":
                np.nan,

            "normalized_working_capital_cashflow_margin":
                np.nan,

            "working_capital_cf_used":
                np.nan,

            "working_capital_cashflow_margin_used":
                np.nan,

            "working_capital_source_used":
                "NOT_APPLICABLE",

            "working_capital_distortion_flag":
                False,

            "levered_cash_fcf":
                np.nan,

            "owner_levered_cash_fcf":
                np.nan,

            "cash_fcff_proxy":
                np.nan,

            "owner_cash_fcff":
                np.nan,

            "operating_fcff_proxy":
                np.nan,

            "levered_cash_fcf_margin":
                np.nan,

            "owner_levered_cash_fcf_margin":
                np.nan,

            "cash_fcff_margin":
                np.nan,

            "owner_cash_fcff_margin":
                np.nan,

            "operating_fcff_margin":
                np.nan,

            "sbc_margin":
                np.nan,

            "after_tax_interest_margin":
                np.nan,

            "cash_vs_operating_gap":
                np.nan,

            "owner_vs_operating_gap":
                np.nan,

            "owner_comparison_basis":
                "NOT_APPLICABLE",

            "reported_fcf_identity_gap":
                np.nan,

            "reported_fcf_identity_gap_margin":
                np.nan,

            "operating_bridge_complete":
                True,

            "financing_bridge_complete":
                True,

            "bridge_classification":
                "NOT_APPLICABLE_FINANCIAL",

            "accounting_quality_multiplier":
                1.00,

            "historical_backtest_eligible":
                False,

        })


        continue


    # ========================================================
    # COMPANY HISTORY
    # ========================================================

    quarterly_company = (

        F3A_QUARTERLY[

            F3A_QUARTERLY[
                "ticker"
            ]
            ==
            ticker

        ]

        .sort_values(
            "period_end",
            ascending=False,
        )

        .copy()

    )


    annual_company = (

        F3A_ANNUAL[

            F3A_ANNUAL[
                "ticker"
            ]
            ==
            ticker

        ]

        .sort_values(
            "period_end",
            ascending=False,
        )

        .copy()

    )


    # ========================================================
    # CURRENT CORE VALUES
    # ========================================================

    revenue = f3a_numeric(

        current.get(
            "ttm_revenue",
            np.nan,
        )

    )


    ebit = f3a_numeric(

        current.get(
            "ttm_ebit",
            np.nan,
        )

    )


    cfo = f3a_numeric(

        current.get(
            "ttm_operating_cash_flow",
            np.nan,
        )

    )


    capex = f3a_numeric(

        current.get(
            "ttm_capex",
            np.nan,
        )

    )


    da = f3a_numeric(

        current.get(
            "ttm_depreciation_amortization",
            np.nan,
        )

    )


    reported_fcf = f3a_numeric(

        current.get(
            "ttm_free_cash_flow",
            np.nan,
        )

    )


    # ========================================================
    # TAX
    # ========================================================

    raw_tax = f3a_numeric(

        current.get(
            "ttm_effective_tax_rate_raw",
            np.nan,
        )

    )


    normalized_tax = np.nan


    if ticker in F3A_NORMALIZED_LOOKUP.index:

        normalized_tax = f3a_numeric(

            F3A_NORMALIZED_LOOKUP.loc[

                ticker,
                "normalized_tax_rate",

            ]

        )


    if (

        pd.notna(
            raw_tax
        )

        and

        0.0
        <=
        raw_tax
        <=
        0.50

    ):

        bridge_tax_rate = (
            raw_tax
        )


        tax_source = (
            "TTM_EFFECTIVE_TAX"
        )


    elif pd.notna(
        normalized_tax
    ):

        bridge_tax_rate = (
            normalized_tax
        )


        tax_source = (
            "F3_NORMALIZED_TAX"
        )


    else:

        bridge_tax_rate = (
            0.21
        )


        tax_source = (
            "DEFAULT_21_PERCENT"
        )


    # ========================================================
    # DEBT
    # ========================================================

    current_debt = f3a_numeric(

        current.get(
            "current_debt",
            np.nan,
        )

    )


    if pd.isna(
        current_debt
    ):

        current_debt = f3a_latest_value(

            quarterly_company,
            "total_debt",

        )


    if pd.isna(
        current_debt
    ):

        current_debt = f3a_latest_value(

            annual_company,
            "total_debt",

        )


    debt_to_revenue = (

        current_debt
        /
        revenue

        if (

            pd.notna(
                current_debt
            )

            and

            pd.notna(
                revenue
            )

            and

            revenue > 0

        )

        else np.nan

    )


    # ========================================================
    # INTEREST EXPENSE
    # ========================================================

    current_interest = f3a_numeric(

        current.get(
            "ttm_interest_expense",
            np.nan,
        )

    )


    if pd.notna(
        current_interest
    ):

        interest_expense = abs(
            current_interest
        )


        interest_source = (
            "F2_CURRENT_TTM"
        )


    else:

        interest_expense, interest_source = (

            f3a_ttm_or_annual(

                quarterly_company,
                annual_company,

                "interest_expense",

            )

        )


        if pd.notna(
            interest_expense
        ):

            interest_expense = abs(

                float(
                    interest_expense
                )

            )


    # --------------------------------------------------------
    # Missing interest can be zeroed only if balance-sheet
    # evidence shows debt is negligible.
    # --------------------------------------------------------

    if (

        pd.isna(
            interest_expense
        )

        and

        pd.notna(
            debt_to_revenue
        )

        and

        debt_to_revenue
        <=
        F3A_NEGLIGIBLE_DEBT_TO_REVENUE

    ):

        interest_expense = (
            0.0
        )


        interest_source = (
            "NEGLIGIBLE_DEBT_ZERO_INTEREST"
        )


    after_tax_interest = (

        interest_expense

        *
        (
            1.0
            -
            bridge_tax_rate
        )

        if pd.notna(
            interest_expense
        )

        else np.nan

    )


    # ========================================================
    # STOCK-BASED COMPENSATION
    # ========================================================

    sbc = f3a_numeric(

        current.get(
            "ttm_stock_based_compensation",
            np.nan,
        )

    )


    sbc_source = (
        "F2_CURRENT_TTM"
    )


    if pd.isna(
        sbc
    ):

        sbc, sbc_source = (

            f3a_ttm_or_annual(

                quarterly_company,
                annual_company,

                "stock_based_compensation",

            )

        )


    if pd.notna(
        sbc
    ):

        sbc = abs(
            float(sbc)
        )


    # ========================================================
    # RAW WORKING-CAPITAL CASH FLOW
    # ========================================================

    raw_wc_cf, raw_wc_source = (

        f3a_ttm_or_annual(

            quarterly_company,
            annual_company,

            "change_in_working_capital_cf",

        )

    )


    raw_wc_margin = f3a_margin(

        raw_wc_cf,
        revenue,

    )


    # ========================================================
    # NORMALIZED F3 WORKING-CAPITAL CASH FLOW
    # ========================================================

    normalized_nwc_ratio = np.nan


    if ticker in F3A_NORMALIZED_LOOKUP.index:

        normalized_nwc_ratio = f3a_numeric(

            F3A_NORMALIZED_LOOKUP.loc[

                ticker,
                "normalized_nwc_investment_ratio",

            ]

        )


    normalized_wc_cf = (

        -
        normalized_nwc_ratio

        *
        revenue

        if (

            pd.notna(
                normalized_nwc_ratio
            )

            and

            pd.notna(
                revenue
            )

        )

        else np.nan

    )


    normalized_wc_margin = f3a_margin(

        normalized_wc_cf,
        revenue,

    )


    # ========================================================
    # WORKING-CAPITAL DISTORTION TEST
    # ========================================================

    wc_extreme = bool(

        pd.notna(
            raw_wc_margin
        )

        and

        abs(
            raw_wc_margin
        )
        >
        F3A_RAW_WC_EXTREME_THRESHOLD

    )


    wc_divergent = bool(

        pd.notna(
            raw_wc_margin
        )

        and

        pd.notna(
            normalized_wc_margin
        )

        and

        abs(

            raw_wc_margin

            -
            normalized_wc_margin

        )
        >
        F3A_RAW_WC_DIVERGENCE_THRESHOLD

    )


    working_capital_distortion = bool(

        wc_extreme

        or

        wc_divergent

    )


    # --------------------------------------------------------
    # Selection hierarchy
    # --------------------------------------------------------

    if (

        working_capital_distortion

        and

        pd.notna(
            normalized_wc_cf
        )

    ):

        wc_cf_used = (
            normalized_wc_cf
        )


        wc_source_used = (
            "F3_NORMALIZED_WC_DISTORTION_FALLBACK"
        )


    elif pd.notna(
        raw_wc_cf
    ):

        wc_cf_used = (
            raw_wc_cf
        )


        wc_source_used = (
            raw_wc_source
        )


    elif pd.notna(
        normalized_wc_cf
    ):

        wc_cf_used = (
            normalized_wc_cf
        )


        wc_source_used = (
            "F3_NORMALIZED_WC_MISSING_RAW_FALLBACK"
        )


    else:

        wc_cf_used = np.nan


        wc_source_used = (
            "MISSING"
        )


    wc_margin_used = f3a_margin(

        wc_cf_used,
        revenue,

    )


    # ========================================================
    # COMPLETENESS
    # ========================================================

    operating_required = [

        revenue,
        ebit,
        cfo,
        capex,
        da,
        wc_cf_used,

    ]


    operating_bridge_complete = bool(

        all(

            pd.notna(
                value
            )

            for value
            in operating_required

        )

    )


    financing_bridge_complete = bool(

        pd.notna(
            after_tax_interest
        )

    )


    # ========================================================
    # LEVERED CASH FCF
    # ========================================================

    levered_cash_fcf = (

        cfo
        +
        capex

        if (

            pd.notna(
                cfo
            )

            and

            pd.notna(
                capex
            )

        )

        else np.nan

    )


    # ========================================================
    # OWNER LEVERED CASH FCF
    # ========================================================

    owner_levered_cash_fcf = (

        levered_cash_fcf
        -
        sbc

        if (

            pd.notna(
                levered_cash_fcf
            )

            and

            pd.notna(
                sbc
            )

        )

        else np.nan

    )


    # ========================================================
    # UNLEVERED CASH FCFF
    # ========================================================

    cash_fcff_proxy = (

        levered_cash_fcf

        +
        after_tax_interest

        if (

            pd.notna(
                levered_cash_fcf
            )

            and

            pd.notna(
                after_tax_interest
            )

        )

        else np.nan

    )


    # ========================================================
    # OWNER CASH FCFF
    # ========================================================

    owner_cash_fcff = (

        cash_fcff_proxy

        -
        sbc

        if (

            pd.notna(
                cash_fcff_proxy
            )

            and

            pd.notna(
                sbc
            )

        )

        else np.nan

    )


    # ========================================================
    # OPERATING FCFF
    # ========================================================
    #
    # IMPORTANT:
    #
    # Interest is NOT required here.
    # ========================================================

    operating_fcff_proxy = (

        ebit

        *
        (
            1.0
            -
            bridge_tax_rate
        )

        +
        da

        +
        capex

        +
        wc_cf_used

        if operating_bridge_complete

        else np.nan

    )


    # ========================================================
    # MARGINS
    # ========================================================

    levered_cash_fcf_margin = f3a_margin(

        levered_cash_fcf,
        revenue,

    )


    owner_levered_cash_fcf_margin = f3a_margin(

        owner_levered_cash_fcf,
        revenue,

    )


    cash_fcff_margin = f3a_margin(

        cash_fcff_proxy,
        revenue,

    )


    owner_cash_fcff_margin = f3a_margin(

        owner_cash_fcff,
        revenue,

    )


    operating_fcff_margin = f3a_margin(

        operating_fcff_proxy,
        revenue,

    )


    sbc_margin = f3a_margin(

        sbc,
        revenue,

    )


    after_tax_interest_margin = f3a_margin(

        after_tax_interest,
        revenue,

    )


    # ========================================================
    # COMPARISON BASIS
    # ========================================================
    #
    # Prefer unlevered owner cash FCFF.
    #
    # If interest cannot be observed, use owner levered FCF
    # as a secondary diagnostic rather than making the entire
    # operating bridge NaN.
    # ========================================================

    if pd.notna(
        owner_cash_fcff_margin
    ):

        owner_comparison_margin = (
            owner_cash_fcff_margin
        )


        owner_comparison_basis = (
            "OWNER_CASH_FCFF"
        )


    elif pd.notna(
        owner_levered_cash_fcf_margin
    ):

        owner_comparison_margin = (
            owner_levered_cash_fcf_margin
        )


        owner_comparison_basis = (
            "OWNER_LEVERED_CASH_FCF_INTEREST_UNAVAILABLE"
        )


    elif pd.notna(
        cash_fcff_margin
    ):

        owner_comparison_margin = (
            cash_fcff_margin
        )


        owner_comparison_basis = (
            "CASH_FCFF_SBC_UNAVAILABLE"
        )


    else:

        owner_comparison_margin = np.nan


        owner_comparison_basis = (
            "UNAVAILABLE"
        )


    # ========================================================
    # CASH COMPARISON
    # ========================================================

    if pd.notna(
        cash_fcff_margin
    ):

        cash_comparison_margin = (
            cash_fcff_margin
        )


    else:

        cash_comparison_margin = (
            levered_cash_fcf_margin
        )


    cash_vs_operating_gap = (

        cash_comparison_margin

        -
        operating_fcff_margin

        if (

            pd.notna(
                cash_comparison_margin
            )

            and

            pd.notna(
                operating_fcff_margin
            )

        )

        else np.nan

    )


    owner_vs_operating_gap = (

        owner_comparison_margin

        -
        operating_fcff_margin

        if (

            pd.notna(
                owner_comparison_margin
            )

            and

            pd.notna(
                operating_fcff_margin
            )

        )

        else np.nan

    )


    # ========================================================
    # FCF IDENTITY
    # ========================================================

    reported_fcf_identity_gap = (

        reported_fcf

        -
        levered_cash_fcf

        if (

            pd.notna(
                reported_fcf
            )

            and

            pd.notna(
                levered_cash_fcf
            )

        )

        else np.nan

    )


    reported_fcf_identity_gap_margin = (

        f3a_margin(

            reported_fcf_identity_gap,
            revenue,

        )

    )


    # ========================================================
    # CLASSIFICATION
    # ========================================================

    raw_gap_abs = (

        abs(
            cash_vs_operating_gap
        )

        if pd.notna(
            cash_vs_operating_gap
        )

        else np.nan

    )


    owner_gap_abs = (

        abs(
            owner_vs_operating_gap
        )

        if pd.notna(
            owner_vs_operating_gap
        )

        else np.nan

    )


    if not operating_bridge_complete:

        classification = (
            "INCOMPLETE_OPERATING_BRIDGE"
        )


        quality_multiplier = (
            0.50
        )


    elif (

        pd.notna(
            raw_gap_abs
        )

        and

        raw_gap_abs
        <=
        F3A_DIRECT_RECONCILIATION_THRESHOLD

    ):

        classification = (
            "DIRECTLY_RECONCILED"
        )


        quality_multiplier = (
            1.00
        )


    elif (

        pd.notna(
            owner_gap_abs
        )

        and

        owner_gap_abs
        <=
        F3A_DIRECT_RECONCILIATION_THRESHOLD

        and

        working_capital_distortion

    ):

        classification = (
            "WORKING_CAPITAL_DISTORTION_RECONCILED"
        )


        quality_multiplier = (
            0.90
        )


    elif (

        pd.notna(
            owner_gap_abs
        )

        and

        owner_gap_abs
        <=
        F3A_DIRECT_RECONCILIATION_THRESHOLD

    ):

        classification = (
            "SBC_DRIVEN_RECONCILED"
        )


        quality_multiplier = (
            0.90
        )


    elif (

        pd.notna(
            owner_gap_abs
        )

        and

        owner_gap_abs
        <=
        F3A_TIMING_REVIEW_THRESHOLD

    ):

        classification = (
            "NONCASH_OR_TIMING_REVIEW"
        )


        quality_multiplier = (
            0.75
        )


    else:

        classification = (
            "UNRESOLVED_ACCOUNTING_GAP"
        )


        quality_multiplier = (
            0.55
        )


    # ========================================================
    # SAVE ROW
    # ========================================================

    bridge_rows.append({

        "ticker":
            ticker,

        "company_name":
            company_name,

        "valuation_model_family":
            model_family,

        "bridge_applicable":
            True,

        "ttm_revenue":
            revenue,

        "ttm_ebit":
            ebit,

        "ttm_tax_rate_bridge":
            bridge_tax_rate,

        "tax_rate_source":
            tax_source,

        "ttm_cfo":
            cfo,

        "ttm_capex":
            capex,

        "ttm_da":
            da,

        "current_debt_bridge":
            current_debt,

        "debt_to_revenue":
            debt_to_revenue,

        "ttm_interest_expense":
            interest_expense,

        "interest_source":
            interest_source,

        "ttm_after_tax_interest":
            after_tax_interest,

        "ttm_stock_based_compensation":
            sbc,

        "sbc_source":
            sbc_source,

        "raw_change_working_capital_cf":
            raw_wc_cf,

        "raw_working_capital_cashflow_margin":
            raw_wc_margin,

        "normalized_working_capital_cf":
            normalized_wc_cf,

        "normalized_working_capital_cashflow_margin":
            normalized_wc_margin,

        "working_capital_cf_used":
            wc_cf_used,

        "working_capital_cashflow_margin_used":
            wc_margin_used,

        "working_capital_source_used":
            wc_source_used,

        "working_capital_distortion_flag":
            working_capital_distortion,

        "levered_cash_fcf":
            levered_cash_fcf,

        "owner_levered_cash_fcf":
            owner_levered_cash_fcf,

        "cash_fcff_proxy":
            cash_fcff_proxy,

        "owner_cash_fcff":
            owner_cash_fcff,

        "operating_fcff_proxy":
            operating_fcff_proxy,

        "levered_cash_fcf_margin":
            levered_cash_fcf_margin,

        "owner_levered_cash_fcf_margin":
            owner_levered_cash_fcf_margin,

        "cash_fcff_margin":
            cash_fcff_margin,

        "owner_cash_fcff_margin":
            owner_cash_fcff_margin,

        "operating_fcff_margin":
            operating_fcff_margin,

        "sbc_margin":
            sbc_margin,

        "after_tax_interest_margin":
            after_tax_interest_margin,

        "cash_vs_operating_gap":
            cash_vs_operating_gap,

        "owner_vs_operating_gap":
            owner_vs_operating_gap,

        "owner_comparison_basis":
            owner_comparison_basis,

        "reported_fcf_identity_gap":
            reported_fcf_identity_gap,

        "reported_fcf_identity_gap_margin":
            reported_fcf_identity_gap_margin,

        "operating_bridge_complete":
            operating_bridge_complete,

        "financing_bridge_complete":
            financing_bridge_complete,

        "bridge_classification":
            classification,

        "accounting_quality_multiplier":
            quality_multiplier,

        "historical_backtest_eligible":
            False,

    })


F3A_ACCOUNTING_BRIDGE = pd.DataFrame(

    bridge_rows

)


# ============================================================
# 10. ATTACH F3 RECONCILIATION METRICS
# ============================================================

reconciliation_columns = [

    "ticker",

    "normalized_fcf_margin",

    "implied_normalized_fcff_margin",

    "fcff_margin_reconciliation_gap",

    "large_fcff_reconciliation_gap",

]


available_reconciliation_columns = [

    column

    for column
    in reconciliation_columns

    if column
    in
    F3A_NORMALIZED.columns

]


F3A_ACCOUNTING_BRIDGE = (

    F3A_ACCOUNTING_BRIDGE

    .merge(

        F3A_NORMALIZED[

            available_reconciliation_columns

        ],

        on="ticker",

        how="left",

        validate="one_to_one",

    )

)


# ============================================================
# 11. CONFIDENCE ADJUSTMENT
# ============================================================

F3A_CONFIDENCE = (

    F3A_NORMALIZED[
        [
            "ticker",
            "assumption_confidence",
        ]
    ]

    .merge(

        F3A_ACCOUNTING_BRIDGE[
            [
                "ticker",

                "bridge_classification",

                "accounting_quality_multiplier",

            ]
        ],

        on="ticker",

        how="left",

        validate="one_to_one",

    )

)


F3A_CONFIDENCE[
    "accounting_quality_multiplier"
] = (

    F3A_CONFIDENCE[
        "accounting_quality_multiplier"
    ]

    .fillna(
        1.0
    )

)


F3A_CONFIDENCE[
    "effective_assumption_confidence"
] = (

    F3A_CONFIDENCE[
        "assumption_confidence"
    ]

    *

    F3A_CONFIDENCE[
        "accounting_quality_multiplier"
    ]

)


F3A_CONFIDENCE[
    "effective_assumption_confidence"
] = (

    F3A_CONFIDENCE[
        "effective_assumption_confidence"
    ]

    .clip(
        lower=0.0,
        upper=1.0,
    )

)


# ============================================================
# 12. PROMOTED NORMALIZED ECONOMICS
# ============================================================

F3A_NORMALIZED_ECONOMICS = (

    F3A_NORMALIZED

    .merge(

        F3A_CONFIDENCE[
            [
                "ticker",

                "bridge_classification",

                "accounting_quality_multiplier",

                "effective_assumption_confidence",
            ]
        ],

        on="ticker",

        how="left",

        validate="one_to_one",

    )

)


# ============================================================
# 13. LARGE F3 GAP AUDIT
# ============================================================

F3A_LARGE_GAP_AUDIT = (

    F3A_ACCOUNTING_BRIDGE[

        F3A_ACCOUNTING_BRIDGE[
            "large_fcff_reconciliation_gap"
        ]
        .fillna(False)

    ][
        [
            "ticker",
            "company_name",

            "valuation_model_family",

            "normalized_fcf_margin",
            "implied_normalized_fcff_margin",
            "fcff_margin_reconciliation_gap",

            "levered_cash_fcf_margin",
            "cash_fcff_margin",

            "owner_levered_cash_fcf_margin",
            "owner_cash_fcff_margin",

            "operating_fcff_margin",

            "sbc_margin",

            "after_tax_interest_margin",

            "raw_working_capital_cashflow_margin",

            "normalized_working_capital_cashflow_margin",

            "working_capital_cashflow_margin_used",

            "working_capital_distortion_flag",

            "cash_vs_operating_gap",
            "owner_vs_operating_gap",

            "owner_comparison_basis",

            "bridge_classification",

            "accounting_quality_multiplier",

            "operating_bridge_complete",
            "financing_bridge_complete",
        ]
    ]

    .copy()

    .reset_index(
        drop=True
    )

)


# ============================================================
# 14. OPERATING BRIDGE AUDIT
# ============================================================

F3A_OPERATING_AUDIT = (

    F3A_ACCOUNTING_BRIDGE[

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ]

    ]

    .copy()

)


F3A_OPERATING_AUDIT[
    "abs_cash_vs_operating_gap"
] = (

    F3A_OPERATING_AUDIT[
        "cash_vs_operating_gap"
    ]
    .abs()

)


F3A_OPERATING_AUDIT[
    "abs_owner_vs_operating_gap"
] = (

    F3A_OPERATING_AUDIT[
        "owner_vs_operating_gap"
    ]
    .abs()

)


F3A_OPERATING_AUDIT = (

    F3A_OPERATING_AUDIT

    .sort_values(

        "abs_owner_vs_operating_gap",

        ascending=False,

        na_position="last",

    )

    .reset_index(
        drop=True
    )

)


# ============================================================
# 15. QUALITY STATISTICS
# ============================================================

operating_count = int(

    F3A_ACCOUNTING_BRIDGE[
        "bridge_applicable"
    ]
    .sum()

)


operating_complete_count = int(

    (

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ]

        &

        F3A_ACCOUNTING_BRIDGE[
            "operating_bridge_complete"
        ]

    )
    .sum()

)


prior_large_gap_count = int(

    F3A_ACCOUNTING_BRIDGE[
        "large_fcff_reconciliation_gap"
    ]
    .fillna(False)
    .sum()

)


large_gap_complete_count = int(

    (

        F3A_ACCOUNTING_BRIDGE[
            "large_fcff_reconciliation_gap"
        ]
        .fillna(False)

        &

        F3A_ACCOUNTING_BRIDGE[
            "operating_bridge_complete"
        ]

    )
    .sum()

)


large_gap_unresolved_count = int(

    (

        F3A_ACCOUNTING_BRIDGE[
            "large_fcff_reconciliation_gap"
        ]
        .fillna(False)

        &

        F3A_ACCOUNTING_BRIDGE[
            "bridge_classification"
        ]
        .isin(
            [
                "UNRESOLVED_ACCOUNTING_GAP",
                "INCOMPLETE_OPERATING_BRIDGE",
            ]
        )

    )
    .sum()

)


all_operating_unresolved_count = int(

    (

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ]

        &

        F3A_ACCOUNTING_BRIDGE[
            "bridge_classification"
        ]
        .isin(
            [
                "UNRESOLVED_ACCOUNTING_GAP",
                "INCOMPLETE_OPERATING_BRIDGE",
            ]
        )

    )
    .sum()

)


wc_distortion_count = int(

    (

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ]

        &

        F3A_ACCOUNTING_BRIDGE[
            "working_capital_distortion_flag"
        ]

    )
    .sum()

)


# ============================================================
# 16. FCF IDENTITY
# ============================================================

identity_values = (

    F3A_ACCOUNTING_BRIDGE.loc[

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ],

        "reported_fcf_identity_gap_margin",

    ]

    .dropna()
    .abs()

)


identity_failure_count = int(

    (
        identity_values
        >
        F3A_MAX_FCF_IDENTITY_GAP
    )
    .sum()

)


# ============================================================
# 17. LARGE-GAP SBC COVERAGE
# ============================================================

large_gap_rows = (

    F3A_ACCOUNTING_BRIDGE[

        F3A_ACCOUNTING_BRIDGE[
            "large_fcff_reconciliation_gap"
        ]
        .fillna(False)

    ]

)


large_gap_sbc_available = int(

    large_gap_rows[
        "ttm_stock_based_compensation"
    ]
    .notna()
    .sum()

)


# ============================================================
# 18. CONFIDENCE VALIDATION
# ============================================================

confidence_valid = bool(

    F3A_NORMALIZED_ECONOMICS[
        "effective_assumption_confidence"
    ]

    .between(
        0.0,
        1.0,
        inclusive="both",
    )

    .all()

)


# ============================================================
# 19. HEALTH ENGINE
# ============================================================

f3a_checks = []


def add_f3a_check(
    check,
    passed,
    detail,
    required=True,
):

    f3a_checks.append({

        "check":
            check,

        "passed":
            bool(
                passed
            ),

        "required":
            bool(
                required
            ),

        "detail":
            str(
                detail
            ),

    })


add_f3a_check(

    "F3 normalized universe preserved",

    len(
        F3A_NORMALIZED_ECONOMICS
    )
    ==
    len(
        F3_NORMALIZED_ECONOMICS
    ),

    (
        f"F3A="
        f"{len(F3A_NORMALIZED_ECONOMICS)}, "
        f"F3="
        f"{len(F3_NORMALIZED_ECONOMICS)}"
    ),

)


add_f3a_check(

    "All operating companies have complete operating FCFF bridges",

    operating_complete_count
    ==
    operating_count,

    (
        f"complete="
        f"{operating_complete_count}/"
        f"{operating_count}"
    ),

)


add_f3a_check(

    "Every F3 large FCFF gap has a complete operating bridge",

    large_gap_complete_count
    ==
    prior_large_gap_count,

    (
        f"complete="
        f"{large_gap_complete_count}/"
        f"{prior_large_gap_count}"
    ),

)


add_f3a_check(

    "SBC data available for every F3 large-gap company",

    large_gap_sbc_available
    ==
    prior_large_gap_count,

    (
        f"SBC_available="
        f"{large_gap_sbc_available}/"
        f"{prior_large_gap_count}"
    ),

)


add_f3a_check(

    "No F3 large FCFF gap remains fundamentally unresolved",

    large_gap_unresolved_count
    ==
    0,

    (
        f"unresolved="
        f"{large_gap_unresolved_count}"
    ),

)


add_f3a_check(

    "Reported FCF agrees with CFO + signed CapEx",

    identity_failure_count
    ==
    0,

    (
        f"identity_failures="
        f"{identity_failure_count}"
    ),

)


add_f3a_check(

    "Effective assumption confidence remains in [0,1]",

    confidence_valid,

    (
        f"min="
        f"{F3A_NORMALIZED_ECONOMICS['effective_assumption_confidence'].min():.3f}, "
        f"max="
        f"{F3A_NORMALIZED_ECONOMICS['effective_assumption_confidence'].max():.3f}"
    ),

)


# ------------------------------------------------------------
# Diagnostic:
#
# Other operating companies may still be under review.
# That is disclosed rather than hidden.
# ------------------------------------------------------------

add_f3a_check(

    "All operating unresolved accounting gaps disclosed",

    True,

    (
        f"unresolved_operating="
        f"{all_operating_unresolved_count}"
    ),

    required=False,

)


add_f3a_check(

    "Working-capital structural distortions disclosed",

    True,

    (
        f"distortion_companies="
        f"{wc_distortion_count}"
    ),

    required=False,

)


# ------------------------------------------------------------
# No intrinsic-value output
# ------------------------------------------------------------

valuation_keywords = [

    "fair_value",
    "intrinsic_value",
    "enterprise_value",
    "equity_value",
    "target_price",
    "upside",

]


valuation_columns = [

    column

    for column
    in F3A_NORMALIZED_ECONOMICS.columns

    if any(

        keyword
        in
        column.lower()

        for keyword
        in valuation_keywords

    )

]


add_f3a_check(

    "F3A contains no intrinsic-value output",

    len(
        valuation_columns
    )
    ==
    0,

    (
        f"valuation_columns="
        f"{valuation_columns}"
    ),

)


historical_blocked = bool(

    (

        F3A_ACCOUNTING_BRIDGE[
            "historical_backtest_eligible"
        ]
        ==
        False

    )
    .all()

)


add_f3a_check(

    "Historical valuation backtest remains blocked",

    historical_blocked,

    "LIVE_ONLY accounting reconciliation",

)


# ============================================================
# 20. HEALTH TABLE
# ============================================================

F3A_HEALTH = pd.DataFrame(

    f3a_checks

)


F3A_HEALTH[
    "status"
] = np.where(

    F3A_HEALTH[
        "passed"
    ],

    "✓ PASS",

    np.where(

        F3A_HEALTH[
            "required"
        ],

        "✗ FAIL",

        "⚠ WARN",

    )

)


required_f3a_failures = (

    F3A_HEALTH[

        F3A_HEALTH[
            "required"
        ]

        &

        ~

        F3A_HEALTH[
            "passed"
        ]

    ]

)


F3A_PASSED = (

    required_f3a_failures.empty

)


F3_FINAL_PASSED = (

    bool(
        F3_PASSED
    )

    and

    bool(
        F3A_PASSED
    )

)


# ============================================================
# 21. PROMOTE ONLY AFTER PASS
# ============================================================

if F3A_PASSED:

    F3_NORMALIZED_ECONOMICS = (

        F3A_NORMALIZED_ECONOMICS
        .copy()

    )


# ============================================================
# 22. SUMMARY
# ============================================================

classification_counts = (

    F3A_ACCOUNTING_BRIDGE.loc[

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ],

        "bridge_classification",

    ]

    .value_counts()

    .to_dict()

)


F3A_SUMMARY = pd.DataFrame([{

    "f3a_version":
        F3A_VERSION,

    "companies":
        len(
            F3A_ACCOUNTING_BRIDGE
        ),

    "operating_companies":
        operating_count,

    "complete_operating_bridges":
        operating_complete_count,

    "f3_large_gap_companies":
        prior_large_gap_count,

    "unresolved_f3_large_gap_companies":
        large_gap_unresolved_count,

    "all_operating_unresolved_companies":
        all_operating_unresolved_count,

    "working_capital_distortion_companies":
        wc_distortion_count,

    "fcf_identity_failures":
        identity_failure_count,

    "mean_original_assumption_confidence":
        float(

            F3A_NORMALIZED_ECONOMICS[
                "assumption_confidence"
            ]
            .mean()

        ),

    "mean_effective_assumption_confidence":
        float(

            F3A_NORMALIZED_ECONOMICS[
                "effective_assumption_confidence"
            ]
            .mean()

        ),

    "historical_backtest_eligible":
        False,

    "f3a_passed":
        F3A_PASSED,

    "f3_final_passed":
        F3_FINAL_PASSED,

}])


