# ===== ORIGINAL NOTEBOOK CELL 63 =====
# ============================================================
# SECTION F — VALUATION ENGINE
# CELL F3B — STRUCTURAL WORKING-CAPITAL NORMALIZATION
#            + FINAL FORECAST QUALITY GATE V1.0.0
# ============================================================
#
# Purpose:
#
#   Repair forecast working-capital assumptions when F3A has
#   identified the company's reported working-capital cash
#   flow as structurally distorted.
#
#
# Why this cell is necessary:
#
#   F3A repairs the ACCOUNTING BRIDGE only.
#
#   It deliberately does not alter the original F3 forecast
#   assumptions.
#
#   Therefore a company whose raw WC cash flow was extreme may
#   still carry a clipped / contaminated normalized WC ratio
#   into the five-year DCF.
#
#
# Systematic replacement hierarchy:
#
#   1. Same sector + same valuation model
#   2. Same valuation model
#   3. Broad operating-FCFF peer set
#
#
# Only NON-DISTORTED peers are eligible.
#
# The repair uses the robust peer MEDIAN.
#
#
# Sign convention:
#
#   normalized_nwc_investment_ratio > 0
#       = use of cash
#
#   normalized_nwc_investment_ratio < 0
#       = source of cash
#
#
# This cell:
#
#   - repairs only structurally distorted names
#   - updates normalized economics
#   - updates all 5-year scenario rows for those names
#   - leaves growth / margins / tax / CapEx / D&A untouched
#   - applies a confidence haircut for peer-imputed WC
#   - does NOT calculate intrinsic value
#
#
# F4 must require:
#
#       F3_FINAL_PASSED == True
#
# ============================================================


# ============================================================
# 1. IMPORTS
# ============================================================

from pathlib import Path

import numpy as np
import pandas as pd


# ============================================================
# 2. VALIDATE F3A
# ============================================================

required_f3b_objects = [

    "F3_PASSED",
    "F3A_PASSED",

    "F3A_ACCOUNTING_BRIDGE",
    "F3A_NORMALIZED_ECONOMICS",

    "F3_FORECAST_ASSUMPTIONS",

    "STOCK_MODEL_DIR",
    "STOCK_OUTPUT_DIR",

]


missing_f3b_objects = [

    obj

    for obj in required_f3b_objects

    if obj not in globals()

]


if missing_f3b_objects:

    raise RuntimeError(

        "F3B requires F3/F3A first. Missing: "
        f"{missing_f3b_objects}"

    )


if not bool(
    F3A_PASSED
):

    raise RuntimeError(

        "F3A production gate did not pass."

    )


# ============================================================
# 3. VERSION
# ============================================================

F3B_VERSION = "1.0.0"


# ============================================================
# 4. MODEL GROUPS
# ============================================================

F3B_OPERATING_MODELS = {

    "FCFF_BLEND",

    "ENERGY_MIDCYCLE_FCFF",

    "REFINER_MIDCYCLE_FCFF",

    "BIOPHARMA_RISK_ADJUSTED_DCF",

}


# ============================================================
# 5. CONFIGURATION
# ============================================================

# ------------------------------------------------------------
# Peer observations outside this range are excluded from the
# anchor calculation.
#
# This is NOT the final forecast bound.
# ------------------------------------------------------------

F3B_PEER_VALID_MIN = -0.08

F3B_PEER_VALID_MAX = 0.08


# ------------------------------------------------------------
# Final peer-imputed forecast ratio is constrained to a
# conservative operating range.
# ------------------------------------------------------------

F3B_REPAIR_MIN = -0.05

F3B_REPAIR_MAX = 0.05


# ------------------------------------------------------------
# Minimum peer observations required for a repair.
# ------------------------------------------------------------

F3B_MIN_PEERS = 2


# ------------------------------------------------------------
# Confidence haircut by fallback hierarchy.
# ------------------------------------------------------------

F3B_PEER_QUALITY = {

    "SAME_SECTOR_SAME_MODEL":
        0.95,

    "SAME_MODEL":
        0.90,

    "BROAD_OPERATING":
        0.80,

}


# ------------------------------------------------------------
# Same threshold used by F3 to flag large FCFF differences.
# ------------------------------------------------------------

F3B_LARGE_FCFF_GAP_THRESHOLD = 0.15


# ============================================================
# 6. LOAD CLEAN F3 FORECAST BASELINE
# ============================================================
#
# Reload the original F3 forecast artifact so repeated F3B runs
# cannot compound earlier repairs.
# ============================================================

F3_FORECAST_BASELINE_PATH = (

    Path(
        STOCK_MODEL_DIR
    )

    /
    "valuation_forecast_assumptions.parquet"

)


if not F3_FORECAST_BASELINE_PATH.exists():

    raise RuntimeError(

        "Original F3 forecast artifact is missing: "
        f"{F3_FORECAST_BASELINE_PATH}"

    )


F3B_FORECAST_BASELINE = pd.read_parquet(

    F3_FORECAST_BASELINE_PATH

)


# ============================================================
# 7. CLEAN NORMALIZED BASELINE
# ============================================================

F3B_NORMALIZED_BASELINE = (

    F3A_NORMALIZED_ECONOMICS
    .copy()

)


F3B_FORECAST_ASSUMPTIONS = (

    F3B_FORECAST_BASELINE
    .copy()

)


F3B_NORMALIZED_ECONOMICS = (

    F3B_NORMALIZED_BASELINE
    .copy()

)


# ============================================================
# 8. REQUIRED COLUMNS
# ============================================================

required_normalized_columns = [

    "ticker",
    "company_name",

    "sector_ticker",

    "valuation_model_family",

    "normalized_nwc_investment_ratio",

    "normalized_ebit_margin",
    "normalized_tax_rate",

    "normalized_da_ratio",
    "normalized_capex_ratio",

    "normalized_fcf_margin",

    "assumption_confidence",

]


missing_normalized_columns = [

    column

    for column in required_normalized_columns

    if column
    not in
    F3B_NORMALIZED_ECONOMICS.columns

]


if missing_normalized_columns:

    raise RuntimeError(

        "F3B normalized economics missing columns: "
        f"{missing_normalized_columns}"

    )


required_forecast_columns = [

    "ticker",
    "scenario",
    "forecast_year",

    "nwc_investment_ratio",

]


missing_forecast_columns = [

    column

    for column in required_forecast_columns

    if column
    not in
    F3B_FORECAST_ASSUMPTIONS.columns

]


if missing_forecast_columns:

    raise RuntimeError(

        "F3B forecast panel missing columns: "
        f"{missing_forecast_columns}"

    )


# ============================================================
# 9. DISTORTION UNIVERSE
# ============================================================

F3B_DISTORTION_UNIVERSE = (

    F3A_ACCOUNTING_BRIDGE[

        F3A_ACCOUNTING_BRIDGE[
            "bridge_applicable"
        ]
        .fillna(False)

        &

        F3A_ACCOUNTING_BRIDGE[
            "working_capital_distortion_flag"
        ]
        .fillna(False)

    ][
        [
            "ticker",
            "company_name",

            "valuation_model_family",

            "raw_working_capital_cashflow_margin",

            "normalized_working_capital_cashflow_margin",

            "working_capital_cashflow_margin_used",

            "working_capital_source_used",

            "bridge_classification",
        ]
    ]

    .copy()

    .reset_index(
        drop=True
    )

)


F3B_DISTORTED_TICKERS = set(

    F3B_DISTORTION_UNIVERSE[
        "ticker"
    ]

)


# ============================================================
# 10. PEER UNIVERSE
# ============================================================

F3B_PEER_UNIVERSE = (

    F3B_NORMALIZED_BASELINE[

        F3B_NORMALIZED_BASELINE[
            "valuation_model_family"
        ]
        .isin(
            F3B_OPERATING_MODELS
        )

        &

        ~

        F3B_NORMALIZED_BASELINE[
            "ticker"
        ]
        .isin(
            F3B_DISTORTED_TICKERS
        )

    ]

    .copy()

)


F3B_PEER_UNIVERSE[
    "normalized_nwc_investment_ratio"
] = pd.to_numeric(

    F3B_PEER_UNIVERSE[
        "normalized_nwc_investment_ratio"
    ],

    errors="coerce",

)


F3B_PEER_UNIVERSE = (

    F3B_PEER_UNIVERSE[

        F3B_PEER_UNIVERSE[
            "normalized_nwc_investment_ratio"
        ]
        .between(

            F3B_PEER_VALID_MIN,
            F3B_PEER_VALID_MAX,

            inclusive="both",

        )

    ]

    .copy()

)


# ============================================================
# 11. PEER-ANCHOR HELPER
# ============================================================

def f3b_peer_anchor(
    target_row,
):

    ticker = target_row[
        "ticker"
    ]


    sector = target_row[
        "sector_ticker"
    ]


    model_family = target_row[
        "valuation_model_family"
    ]


    # ========================================================
    # LEVEL 1 — SAME SECTOR + SAME MODEL
    # ========================================================

    pool = (

        F3B_PEER_UNIVERSE[

            (
                F3B_PEER_UNIVERSE[
                    "sector_ticker"
                ]
                ==
                sector
            )

            &

            (
                F3B_PEER_UNIVERSE[
                    "valuation_model_family"
                ]
                ==
                model_family
            )

            &

            (
                F3B_PEER_UNIVERSE[
                    "ticker"
                ]
                !=
                ticker
            )

        ]

    )


    if len(
        pool
    ) >= F3B_MIN_PEERS:

        values = (

            pool[
                "normalized_nwc_investment_ratio"
            ]

            .dropna()

        )


        anchor = float(
            values.median()
        )


        return {

            "peer_anchor_source":
                "SAME_SECTOR_SAME_MODEL",

            "peer_count":
                len(values),

            "peer_median":
                anchor,

            "peer_tickers":
                ",".join(
                    sorted(
                        pool[
                            "ticker"
                        ]
                        .astype(str)
                        .tolist()
                    )
                ),

            "repair_quality_multiplier":
                F3B_PEER_QUALITY[
                    "SAME_SECTOR_SAME_MODEL"
                ],

        }


    # ========================================================
    # LEVEL 2 — SAME MODEL
    # ========================================================

    pool = (

        F3B_PEER_UNIVERSE[

            (
                F3B_PEER_UNIVERSE[
                    "valuation_model_family"
                ]
                ==
                model_family
            )

            &

            (
                F3B_PEER_UNIVERSE[
                    "ticker"
                ]
                !=
                ticker
            )

        ]

    )


    if len(
        pool
    ) >= F3B_MIN_PEERS:

        values = (

            pool[
                "normalized_nwc_investment_ratio"
            ]

            .dropna()

        )


        anchor = float(
            values.median()
        )


        return {

            "peer_anchor_source":
                "SAME_MODEL",

            "peer_count":
                len(values),

            "peer_median":
                anchor,

            "peer_tickers":
                ",".join(
                    sorted(
                        pool[
                            "ticker"
                        ]
                        .astype(str)
                        .tolist()
                    )
                ),

            "repair_quality_multiplier":
                F3B_PEER_QUALITY[
                    "SAME_MODEL"
                ],

        }


    # ========================================================
    # LEVEL 3 — BROAD OPERATING UNIVERSE
    # ========================================================

    pool = (

        F3B_PEER_UNIVERSE[

            F3B_PEER_UNIVERSE[
                "ticker"
            ]
            !=
            ticker

        ]

    )


    if len(
        pool
    ) >= F3B_MIN_PEERS:

        values = (

            pool[
                "normalized_nwc_investment_ratio"
            ]

            .dropna()

        )


        anchor = float(
            values.median()
        )


        return {

            "peer_anchor_source":
                "BROAD_OPERATING",

            "peer_count":
                len(values),

            "peer_median":
                anchor,

            "peer_tickers":
                ",".join(
                    sorted(
                        pool[
                            "ticker"
                        ]
                        .astype(str)
                        .tolist()
                    )
                ),

            "repair_quality_multiplier":
                F3B_PEER_QUALITY[
                    "BROAD_OPERATING"
                ],

        }


    return {

        "peer_anchor_source":
            "UNRESOLVED",

        "peer_count":
            0,

        "peer_median":
            np.nan,

        "peer_tickers":
            "",

        "repair_quality_multiplier":
            np.nan,

    }


# ============================================================
# 12. BUILD REPAIR TABLE
# ============================================================

repair_rows = []


for ticker in sorted(

    F3B_DISTORTED_TICKERS

):

    target = (

        F3B_NORMALIZED_ECONOMICS[

            F3B_NORMALIZED_ECONOMICS[
                "ticker"
            ]
            ==
            ticker

        ]

    )


    if target.empty:

        repair_rows.append({

            "ticker":
                ticker,

            "repair_success":
                False,

            "repair_error":
                "Ticker missing from normalized economics",

        })


        continue


    target_row = target.iloc[0]


    peer_result = f3b_peer_anchor(

        target_row

    )


    original_ratio = pd.to_numeric(

        target_row[
            "normalized_nwc_investment_ratio"
        ],

        errors="coerce",

    )


    peer_median = (

        peer_result[
            "peer_median"
        ]

    )


    if pd.notna(
        peer_median
    ):

        repaired_ratio = float(

            np.clip(

                peer_median,

                F3B_REPAIR_MIN,
                F3B_REPAIR_MAX,

            )

        )


        repair_success = True

        repair_error = ""


    else:

        repaired_ratio = np.nan

        repair_success = False

        repair_error = (
            "Insufficient valid peer observations"
        )


    distortion_row = (

        F3B_DISTORTION_UNIVERSE[

            F3B_DISTORTION_UNIVERSE[
                "ticker"
            ]
            ==
            ticker

        ]

        .iloc[0]

    )


    repair_rows.append({

        "ticker":
            ticker,

        "company_name":
            target_row[
                "company_name"
            ],

        "sector_ticker":
            target_row[
                "sector_ticker"
            ],

        "valuation_model_family":
            target_row[
                "valuation_model_family"
            ],

        "raw_wc_cashflow_margin":
            distortion_row[
                "raw_working_capital_cashflow_margin"
            ],

        "f3_original_nwc_investment_ratio":
            original_ratio,

        "peer_anchor_source":
            peer_result[
                "peer_anchor_source"
            ],

        "peer_count":
            peer_result[
                "peer_count"
            ],

        "peer_median_nwc_investment_ratio":
            peer_median,

        "peer_tickers":
            peer_result[
                "peer_tickers"
            ],

        "repaired_nwc_investment_ratio":
            repaired_ratio,

        "repair_delta":
            (

                repaired_ratio
                -
                original_ratio

                if (

                    pd.notna(
                        repaired_ratio
                    )

                    and

                    pd.notna(
                        original_ratio
                    )

                )

                else np.nan

            ),

        "repair_quality_multiplier":
            peer_result[
                "repair_quality_multiplier"
            ],

        "repair_success":
            repair_success,

        "repair_error":
            repair_error,

    })


F3B_REPAIR_AUDIT = pd.DataFrame(

    repair_rows

)


# ============================================================
# 13. APPLY REPAIRS TO NORMALIZED ECONOMICS
# ============================================================

F3B_NORMALIZED_ECONOMICS[
    "nwc_assumption_repaired"
] = False


F3B_NORMALIZED_ECONOMICS[
    "nwc_assumption_source"
] = "F3_ORIGINAL"


F3B_NORMALIZED_ECONOMICS[
    "original_normalized_nwc_investment_ratio"
] = (

    F3B_NORMALIZED_ECONOMICS[
        "normalized_nwc_investment_ratio"
    ]

)


F3B_NORMALIZED_ECONOMICS[
    "working_capital_forecast_quality_multiplier"
] = 1.0


for _, repair in (

    F3B_REPAIR_AUDIT
    .iterrows()

):

    if not bool(

        repair.get(
            "repair_success",
            False,
        )

    ):

        continue


    ticker = repair[
        "ticker"
    ]


    repaired_ratio = float(

        repair[
            "repaired_nwc_investment_ratio"
        ]

    )


    target_mask = (

        F3B_NORMALIZED_ECONOMICS[
            "ticker"
        ]
        ==
        ticker

    )


    F3B_NORMALIZED_ECONOMICS.loc[

        target_mask,
        "normalized_nwc_investment_ratio",

    ] = repaired_ratio


    F3B_NORMALIZED_ECONOMICS.loc[

        target_mask,
        "nwc_assumption_repaired",

    ] = True


    F3B_NORMALIZED_ECONOMICS.loc[

        target_mask,
        "nwc_assumption_source",

    ] = (

        "PEER_MEDIAN::"

        +

        str(
            repair[
                "peer_anchor_source"
            ]
        )

    )


    F3B_NORMALIZED_ECONOMICS.loc[

        target_mask,
        "working_capital_forecast_quality_multiplier",

    ] = float(

        repair[
            "repair_quality_multiplier"
        ]

    )


# ============================================================
# 14. RECOMPUTE NORMALIZED FCFF MARGIN
# ============================================================

operating_mask = (

    F3B_NORMALIZED_ECONOMICS[
        "valuation_model_family"
    ]
    .isin(
        F3B_OPERATING_MODELS
    )

)


F3B_NORMALIZED_ECONOMICS.loc[

    operating_mask,

    "implied_normalized_fcff_margin",

] = (

    F3B_NORMALIZED_ECONOMICS.loc[

        operating_mask,
        "normalized_ebit_margin",

    ]

    *

    (

        1.0

        -

        F3B_NORMALIZED_ECONOMICS.loc[

            operating_mask,
            "normalized_tax_rate",

        ]

    )

    +

    F3B_NORMALIZED_ECONOMICS.loc[

        operating_mask,
        "normalized_da_ratio",

    ]

    -

    F3B_NORMALIZED_ECONOMICS.loc[

        operating_mask,
        "normalized_capex_ratio",

    ]

    -

    F3B_NORMALIZED_ECONOMICS.loc[

        operating_mask,
        "normalized_nwc_investment_ratio",

    ]

)


F3B_NORMALIZED_ECONOMICS[
    "fcff_margin_reconciliation_gap"
] = (

    F3B_NORMALIZED_ECONOMICS[
        "implied_normalized_fcff_margin"
    ]

    -

    F3B_NORMALIZED_ECONOMICS[
        "normalized_fcf_margin"
    ]

)


F3B_NORMALIZED_ECONOMICS[
    "large_fcff_reconciliation_gap"
] = (

    F3B_NORMALIZED_ECONOMICS[
        "fcff_margin_reconciliation_gap"
    ]
    .abs()

    >
    F3B_LARGE_FCFF_GAP_THRESHOLD

)


# ============================================================
# 15. FINAL ASSUMPTION CONFIDENCE
# ============================================================

if (

    "effective_assumption_confidence"
    in
    F3B_NORMALIZED_ECONOMICS.columns

):

    confidence_base_column = (
        "effective_assumption_confidence"
    )


else:

    confidence_base_column = (
        "assumption_confidence"
    )


F3B_NORMALIZED_ECONOMICS[
    "pre_f3b_effective_assumption_confidence"
] = (

    F3B_NORMALIZED_ECONOMICS[
        confidence_base_column
    ]

)


F3B_NORMALIZED_ECONOMICS[
    "final_assumption_confidence"
] = (

    F3B_NORMALIZED_ECONOMICS[
        confidence_base_column
    ]

    *

    F3B_NORMALIZED_ECONOMICS[
        "working_capital_forecast_quality_multiplier"
    ]

)


F3B_NORMALIZED_ECONOMICS[
    "final_assumption_confidence"
] = (

    F3B_NORMALIZED_ECONOMICS[
        "final_assumption_confidence"
    ]

    .clip(
        lower=0.0,
        upper=1.0,
    )

)


# ============================================================
# 16. APPLY REPAIRS TO FIVE-YEAR FORECAST PANEL
# ============================================================

for _, repair in (

    F3B_REPAIR_AUDIT
    .iterrows()

):

    if not bool(

        repair.get(
            "repair_success",
            False,
        )

    ):

        continue


    ticker = repair[
        "ticker"
    ]


    repaired_ratio = float(

        repair[
            "repaired_nwc_investment_ratio"
        ]

    )


    forecast_mask = (

        F3B_FORECAST_ASSUMPTIONS[
            "ticker"
        ]
        ==
        ticker

    )


    F3B_FORECAST_ASSUMPTIONS.loc[

        forecast_mask,
        "nwc_investment_ratio",

    ] = repaired_ratio


# ============================================================
# 17. ATTACH FINAL CONFIDENCE TO FORECASTS
# ============================================================

final_confidence_map = (

    F3B_NORMALIZED_ECONOMICS[
        [
            "ticker",

            "final_assumption_confidence",

            "nwc_assumption_repaired",

            "nwc_assumption_source",
        ]
    ]

    .drop_duplicates(
        subset=["ticker"]
    )

)


# Remove previous versions if rerun.
for column in [

    "final_assumption_confidence",
    "nwc_assumption_repaired",
    "nwc_assumption_source",

]:

    if column in F3B_FORECAST_ASSUMPTIONS.columns:

        F3B_FORECAST_ASSUMPTIONS = (

            F3B_FORECAST_ASSUMPTIONS

            .drop(
                columns=[column]
            )

        )


F3B_FORECAST_ASSUMPTIONS = (

    F3B_FORECAST_ASSUMPTIONS

    .merge(

        final_confidence_map,

        on="ticker",

        how="left",

        validate="many_to_one",

    )

)


# ============================================================
# 18. NON-WC FORECAST INTEGRITY TEST
# ============================================================

forecast_keys = [

    "ticker",
    "scenario",
    "forecast_year",

]


untouched_forecast_columns = [

    "revenue_growth",
    "ebit_margin",
    "tax_rate",

    "da_ratio",
    "capex_ratio",

    "roe",
    "payout_ratio",
    "earnings_growth",

    "terminal_growth",

]


untouched_forecast_columns = [

    column

    for column
    in untouched_forecast_columns

    if (

        column
        in
        F3B_FORECAST_BASELINE.columns

        and

        column
        in
        F3B_FORECAST_ASSUMPTIONS.columns

    )

]


comparison = (

    F3B_FORECAST_BASELINE[

        forecast_keys
        +
        untouched_forecast_columns

    ]

    .merge(

        F3B_FORECAST_ASSUMPTIONS[

            forecast_keys
            +
            untouched_forecast_columns

        ],

        on=forecast_keys,

        how="outer",

        suffixes=(
            "_before",
            "_after",
        ),

        validate="one_to_one",

    )

)


unexpected_change_count = 0


for column in untouched_forecast_columns:

    before = pd.to_numeric(

        comparison[
            f"{column}_before"
        ],

        errors="coerce",

    )


    after = pd.to_numeric(

        comparison[
            f"{column}_after"
        ],

        errors="coerce",

    )


    equal_mask = (

        np.isclose(

            before.fillna(0.0),
            after.fillna(0.0),

            rtol=1e-12,
            atol=1e-12,

        )

        &

        (
            before.isna()
            ==
            after.isna()
        )

    )


    unexpected_change_count += int(

        (
            ~equal_mask
        )
        .sum()

    )


# ============================================================
# 19. REPAIR COMPLETENESS AUDIT
# ============================================================

F3B_REPAIRED_FORECAST_AUDIT_ROWS = []


for _, repair in (

    F3B_REPAIR_AUDIT
    .iterrows()

):

    ticker = repair[
        "ticker"
    ]


    repaired_ratio = repair.get(

        "repaired_nwc_investment_ratio",
        np.nan,

    )


    company_forecasts = (

        F3B_FORECAST_ASSUMPTIONS[

            F3B_FORECAST_ASSUMPTIONS[
                "ticker"
            ]
            ==
            ticker

        ]

    )


    if (

        bool(
            repair.get(
                "repair_success",
                False,
            )
        )

        and

        pd.notna(
            repaired_ratio
        )

    ):

        all_rows_match = bool(

            np.isclose(

                pd.to_numeric(

                    company_forecasts[
                        "nwc_investment_ratio"
                    ],

                    errors="coerce",

                ),

                float(
                    repaired_ratio
                ),

                rtol=1e-12,
                atol=1e-12,

            )
            .all()

        )


    else:

        all_rows_match = False


    F3B_REPAIRED_FORECAST_AUDIT_ROWS.append({

        "ticker":
            ticker,

        "forecast_rows":
            len(
                company_forecasts
            ),

        "repair_success":
            bool(

                repair.get(
                    "repair_success",
                    False,
                )

            ),

        "peer_count":
            repair.get(
                "peer_count",
                0,
            ),

        "repaired_nwc_investment_ratio":
            repaired_ratio,

        "all_forecast_rows_match_repair":
            all_rows_match,

    })


F3B_REPAIRED_FORECAST_AUDIT = (

    pd.DataFrame(

        F3B_REPAIRED_FORECAST_AUDIT_ROWS

    )

)


# ============================================================
# 20. HEALTH STATISTICS
# ============================================================

distortion_count = len(

    F3B_DISTORTION_UNIVERSE

)


repair_success_count = int(

    F3B_REPAIR_AUDIT[
        "repair_success"
    ]
    .fillna(False)
    .sum()

) if not F3B_REPAIR_AUDIT.empty else 0


sufficient_peer_count = int(

    (

        F3B_REPAIR_AUDIT[
            "peer_count"
        ]
        .fillna(0)
        >=
        F3B_MIN_PEERS

    )
    .sum()

) if not F3B_REPAIR_AUDIT.empty else 0


forecast_repair_match_count = int(

    F3B_REPAIRED_FORECAST_AUDIT[
        "all_forecast_rows_match_repair"
    ]
    .fillna(False)
    .sum()

) if not F3B_REPAIRED_FORECAST_AUDIT.empty else 0


repaired_ratio_valid_count = int(

    (

        pd.to_numeric(

            F3B_REPAIR_AUDIT[
                "repaired_nwc_investment_ratio"
            ],

            errors="coerce",

        )

        .between(

            F3B_REPAIR_MIN,
            F3B_REPAIR_MAX,

            inclusive="both",

        )

    )
    .sum()

) if not F3B_REPAIR_AUDIT.empty else 0


# ============================================================
# 21. FORECAST DIMENSION CHECK
# ============================================================

baseline_forecast_rows = len(

    F3B_FORECAST_BASELINE

)


final_forecast_rows = len(

    F3B_FORECAST_ASSUMPTIONS

)


baseline_entity_count = (

    F3B_FORECAST_BASELINE[
        "ticker"
    ]
    .nunique()

)


final_entity_count = (

    F3B_FORECAST_ASSUMPTIONS[
        "ticker"
    ]
    .nunique()

)


# ============================================================
# 22. NWC COVERAGE CHECK
# ============================================================

operating_forecasts = (

    F3B_FORECAST_ASSUMPTIONS[

        F3B_FORECAST_ASSUMPTIONS[
            "valuation_model_family"
        ]
        .isin(
            F3B_OPERATING_MODELS
        )

    ]

)


missing_operating_nwc_cells = int(

    operating_forecasts[
        "nwc_investment_ratio"
    ]
    .isna()
    .sum()

)


# ============================================================
# 23. CONFIDENCE CHECK
# ============================================================

final_confidence_valid = bool(

    F3B_NORMALIZED_ECONOMICS[
        "final_assumption_confidence"
    ]

    .between(
        0.0,
        1.0,
        inclusive="both",
    )

    .all()

)


# ============================================================
# 24. PRICE / VALUATION CONTAMINATION CHECK
# ============================================================

prohibited_keywords = [

    "fair_value",
    "intrinsic_value",
    "enterprise_value",
    "equity_value",
    "target_price",
    "upside",

]


prohibited_columns = [

    column

    for column
    in F3B_FORECAST_ASSUMPTIONS.columns

    if any(

        keyword
        in
        column.lower()

        for keyword
        in prohibited_keywords

    )

]


# ============================================================
# 25. HEALTH ENGINE
# ============================================================

f3b_checks = []


def add_f3b_check(
    check,
    passed,
    detail,
    required=True,
):

    f3b_checks.append({

        "check":
            check,

        "passed":
            bool(
                passed
            ),

        "required":
            bool(
                required
            ),

        "detail":
            str(
                detail
            ),

    })


add_f3b_check(

    "F3A normalized universe preserved",

    len(
        F3B_NORMALIZED_ECONOMICS
    )
    ==
    len(
        F3A_NORMALIZED_ECONOMICS
    ),

    (
        f"F3B="
        f"{len(F3B_NORMALIZED_ECONOMICS)}, "
        f"F3A="
        f"{len(F3A_NORMALIZED_ECONOMICS)}"
    ),

)


add_f3b_check(

    "Every structural WC distortion receives a repair",

    repair_success_count
    ==
    distortion_count,

    (
        f"repaired="
        f"{repair_success_count}/"
        f"{distortion_count}"
    ),

)


add_f3b_check(

    "Every repair has sufficient peer observations",

    sufficient_peer_count
    ==
    distortion_count,

    (
        f"sufficient_peers="
        f"{sufficient_peer_count}/"
        f"{distortion_count}, "
        f"minimum={F3B_MIN_PEERS}"
    ),

)


add_f3b_check(

    "All repaired NWC ratios lie inside production bounds",

    repaired_ratio_valid_count
    ==
    distortion_count,

    (
        f"valid="
        f"{repaired_ratio_valid_count}/"
        f"{distortion_count}, "
        f"range=[{F3B_REPAIR_MIN:.1%}, "
        f"{F3B_REPAIR_MAX:.1%}]"
    ),

)


add_f3b_check(

    "Every repaired company has repair applied to all forecast rows",

    forecast_repair_match_count
    ==
    distortion_count,

    (
        f"matching="
        f"{forecast_repair_match_count}/"
        f"{distortion_count}"
    ),

)


add_f3b_check(

    "Forecast panel dimensions preserved",

    (

        baseline_forecast_rows
        ==
        final_forecast_rows

        and

        baseline_entity_count
        ==
        final_entity_count

    ),

    (
        f"rows="
        f"{final_forecast_rows}/"
        f"{baseline_forecast_rows}, "
        f"entities="
        f"{final_entity_count}/"
        f"{baseline_entity_count}"
    ),

)


add_f3b_check(

    "No non-WC forecast assumptions were changed",

    unexpected_change_count
    ==
    0,

    (
        f"unexpected_changed_cells="
        f"{unexpected_change_count}"
    ),

)


add_f3b_check(

    "All operating forecast rows retain NWC assumptions",

    missing_operating_nwc_cells
    ==
    0,

    (
        f"missing_cells="
        f"{missing_operating_nwc_cells}"
    ),

)


add_f3b_check(

    "Final assumption confidence remains in [0,1]",

    final_confidence_valid,

    (
        f"min="
        f"{F3B_NORMALIZED_ECONOMICS['final_assumption_confidence'].min():.3f}, "
        f"max="
        f"{F3B_NORMALIZED_ECONOMICS['final_assumption_confidence'].max():.3f}"
    ),

)


add_f3b_check(

    "F3B contains no intrinsic-value output",

    len(
        prohibited_columns
    )
    ==
    0,

    (
        f"valuation_columns="
        f"{prohibited_columns}"
    ),

)


historical_blocked = bool(

    (

        F3B_FORECAST_ASSUMPTIONS[
            "historical_backtest_eligible"
        ]
        .fillna(False)
        ==
        False

    )
    .all()

)


add_f3b_check(

    "Historical valuation backtest remains blocked",

    historical_blocked,

    "LIVE_ONLY forecast normalization",

)


# ------------------------------------------------------------
# Diagnostic
# ------------------------------------------------------------

add_f3b_check(

    "Structural WC repairs disclosed",

    True,

    (
        f"distortion_companies="
        f"{distortion_count}"
    ),

    required=False,

)


# ============================================================
# 26. HEALTH TABLE
# ============================================================

F3B_HEALTH = pd.DataFrame(

    f3b_checks

)


F3B_HEALTH[
    "status"
] = np.where(

    F3B_HEALTH[
        "passed"
    ],

    "✓ PASS",

    np.where(

        F3B_HEALTH[
            "required"
        ],

        "✗ FAIL",

        "⚠ WARN",

    )

)


required_f3b_failures = (

    F3B_HEALTH[

        F3B_HEALTH[
            "required"
        ]

        &

        ~

        F3B_HEALTH[
            "passed"
        ]

    ]

)


F3B_PASSED = (

    required_f3b_failures.empty

)


F3_FINAL_PASSED = (

    bool(
        F3_PASSED
    )

    and

    bool(
        F3A_PASSED
    )

    and

    bool(
        F3B_PASSED
    )

)


# ============================================================
# 27. PROMOTE ONLY AFTER PASS
# ============================================================

if F3B_PASSED:

    F3_NORMALIZED_ECONOMICS = (

        F3B_NORMALIZED_ECONOMICS
        .copy()

    )


    F3_FORECAST_ASSUMPTIONS = (

        F3B_FORECAST_ASSUMPTIONS
        .copy()

    )


# ============================================================
# 28. SUMMARY
# ============================================================

F3B_SUMMARY = pd.DataFrame([{

    "f3b_version":
        F3B_VERSION,

    "companies":
        len(
            F3B_NORMALIZED_ECONOMICS
        ),

    "structural_wc_distortions":
        distortion_count,

    "successful_wc_repairs":
        repair_success_count,

    "forecast_rows":
        final_forecast_rows,

    "mean_pre_f3b_confidence":
        float(

            F3B_NORMALIZED_ECONOMICS[
                "pre_f3b_effective_assumption_confidence"
            ]
            .mean()

        ),

    "mean_final_assumption_confidence":
        float(

            F3B_NORMALIZED_ECONOMICS[
                "final_assumption_confidence"
            ]
            .mean()

        ),

    "unexpected_non_wc_changes":
        unexpected_change_count,

    "historical_backtest_eligible":
        False,

    "f3b_passed":
        F3B_PASSED,

    "f3_final_passed":
        F3_FINAL_PASSED,

}])


# ============================================================
# 29. SAVE OUTPUTS
# ============================================================

F3B_NORMALIZED_ECONOMICS.to_parquet(

    STOCK_MODEL_DIR
    /
    "valuation_normalized_economics_f3b.parquet",

    index=False,

)


F3B_FORECAST_ASSUMPTIONS.to_parquet(

    STOCK_MODEL_DIR
    /
    "valuation_forecast_assumptions_f3b.parquet",

    index=False,

)


F3B_REPAIR_AUDIT.to_csv(

    STOCK_OUTPUT_DIR
    /
    "f3b_working_capital_repair_audit.csv",

    index=False,

)


F3B_REPAIRED_FORECAST_AUDIT.to_csv(

    STOCK_OUTPUT_DIR
    /
    "f3b_repaired_forecast_audit.csv",

    index=False,

)


F3B_HEALTH.to_csv(

    STOCK_OUTPUT_DIR
    /
    "f3b_health.csv",

    index=False,

)


F3B_SUMMARY.to_csv(

    STOCK_OUTPUT_DIR
    /
    "f3b_summary.csv",

    index=False,

)


