# 13. ATTACH FINANCIAL NORMALIZATION INPUTS
# ============================================================

financial_normalized_columns = [

    "ticker",

    "normalized_roe",

    "normalized_payout_ratio",

    "base_eps_growth",

    "book_value_per_share",

]


available_financial_normalized = [

    column

    for column
    in financial_normalized_columns

    if column
    in F4C_NORMALIZED.columns

]


additional_financial_columns = [

    column

    for column
    in available_financial_normalized

    if (

        column == "ticker"

        or

        column
        not in
        F4C_MANIFEST.columns

    )

]


if len(
    additional_financial_columns
) > 1:

    F4C_MANIFEST = (

        F4C_MANIFEST

        .merge(

            F4C_NORMALIZED[
                additional_financial_columns
            ],

            on="ticker",

            how="left",

            validate="one_to_one",

        )

    )


# ============================================================
# 14. MODEL ROUTER
# ============================================================

def f4c_route_model(
    model_family,
):

    # --------------------------------------------------------
    # Standard corporate FCFF.
    # --------------------------------------------------------

    if model_family == "FCFF_BLEND":

        return {

            "execution_model":
                "CORPORATE_FCFF_DCF",

            "specialist_completion_status":
                "COMPLETE",

            "specialist_overlay_required":
                False,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                1.00,

            "interpretation":
                (
                    "Standard corporate FCFF valuation."
                ),

        }


    # --------------------------------------------------------
    # Upstream / integrated energy.
    #
    # Corporate mid-cycle FCFF is executable.
    # Asset NAV / commodity-strip valuation remains a useful
    # specialist cross-check rather than an absolute blocker.
    # --------------------------------------------------------

    if model_family == "ENERGY_MIDCYCLE_FCFF":

        return {

            "execution_model":
                "MIDCYCLE_CORPORATE_FCFF",

            "specialist_completion_status":
                "CORE_MODEL_COMPLETE_NAV_CROSSCHECK_PENDING",

            "specialist_overlay_required":
                True,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                0.90,

            "interpretation":
                (
                    "Executable mid-cycle corporate FCFF. "
                    "Reserve/NAV and commodity-price cross-check "
                    "still recommended."
                ),

        }


    # --------------------------------------------------------
    # Refiners.
    # --------------------------------------------------------

    if model_family == "REFINER_MIDCYCLE_FCFF":

        return {

            "execution_model":
                "REFINER_MIDCYCLE_CORPORATE_FCFF",

            "specialist_completion_status":
                "CORE_MODEL_COMPLETE_CYCLE_CROSSCHECK_PENDING",

            "specialist_overlay_required":
                True,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                0.90,

            "interpretation":
                (
                    "Executable normalized refinery FCFF. "
                    "Crack-spread / throughput-cycle cross-check "
                    "still recommended."
                ),

        }


    # --------------------------------------------------------
    # Biopharma.
    #
    # We MUST NOT claim a true risk-adjusted pipeline DCF
    # without asset-level pipeline probabilities.
    # --------------------------------------------------------

    if model_family == "BIOPHARMA_RISK_ADJUSTED_DCF":

        return {

            "execution_model":
                "BIOPHARMA_CORPORATE_FCFF_PROXY",

            "specialist_completion_status":
                "PIPELINE_RNPV_PENDING",

            "specialist_overlay_required":
                True,

            "ranking_eligible_after_f5":
                False,

            "model_confidence_multiplier":
                0.70,

            "interpretation":
                (
                    "Corporate FCFF proxy only. NOT a completed "
                    "drug/pipeline risk-adjusted rNPV."
                ),

        }


    # --------------------------------------------------------
    # Banks.
    # --------------------------------------------------------

    if model_family == "BANK_RESIDUAL_INCOME":

        return {

            "execution_model":
                "BANK_RESIDUAL_INCOME",

            "specialist_completion_status":
                "COMPLETE",

            "specialist_overlay_required":
                False,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                1.00,

            "interpretation":
                (
                    "Book-value / ROE residual-income framework."
                ),

        }


    # --------------------------------------------------------
    # Insurers.
    # --------------------------------------------------------

    if model_family == "INSURANCE_EXCESS_RETURN":

        return {

            "execution_model":
                "INSURANCE_EXCESS_RETURN",

            "specialist_completion_status":
                "COMPLETE",

            "specialist_overlay_required":
                False,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                0.95,

            "interpretation":
                (
                    "Book-value / ROE excess-return framework."
                ),

        }


    # --------------------------------------------------------
    # Other financials.
    # --------------------------------------------------------

    if model_family == "FINANCIAL_FCFE_EXCESS_RETURN":

        return {

            "execution_model":
                "FINANCIAL_EXCESS_RETURN_FCFE",

            "specialist_completion_status":
                "COMPLETE",

            "specialist_overlay_required":
                False,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                0.95,

            "interpretation":
                (
                    "Equity-based FCFE / excess-return framework."
                ),

        }


    # --------------------------------------------------------
    # Health insurers.
    # --------------------------------------------------------

    if model_family == "HEALTH_INSURER_FCFE":

        return {

            "execution_model":
                "HEALTH_INSURER_EXCESS_RETURN_FCFE",

            "specialist_completion_status":
                "CORE_MODEL_COMPLETE_MEDICAL_COST_REVIEW_PENDING",

            "specialist_overlay_required":
                True,

            "ranking_eligible_after_f5":
                True,

            "model_confidence_multiplier":
                0.90,

            "interpretation":
                (
                    "Equity-based insurer valuation. "
                    "Medical-cost / reimbursement trend review "
                    "remains desirable."
                ),

        }


    return {

        "execution_model":
            "UNSUPPORTED",

        "specialist_completion_status":
            "UNSUPPORTED",

        "specialist_overlay_required":
            True,

        "ranking_eligible_after_f5":
            False,

        "model_confidence_multiplier":
            0.0,

        "interpretation":
            (
                "Unsupported valuation model family."
            ),

    }


# ============================================================
# 15. APPLY MODEL ROUTER
# ============================================================

route_rows = []


for _, row in (

    F4C_MANIFEST
    .iterrows()

):

    route = f4c_route_model(

        row[
            "valuation_model_family"
        ]

    )


    route_rows.append(
        route
    )


route_frame = pd.DataFrame(

    route_rows

)


for column in route_frame.columns:

    F4C_MANIFEST[
        column
    ] = (

        route_frame[
            column
        ]
        .values

    )


