# 16. FINAL MODEL CONFIDENCE
# ============================================================

if (

    "final_assumption_confidence"
    in
    F4C_MANIFEST.columns

):

    base_confidence = pd.to_numeric(

        F4C_MANIFEST[
            "final_assumption_confidence"
        ],

        errors="coerce",

    )


elif (

    "effective_assumption_confidence"
    in
    F4C_MANIFEST.columns

):

    base_confidence = pd.to_numeric(

        F4C_MANIFEST[
            "effective_assumption_confidence"
        ],

        errors="coerce",

    )


else:

    base_confidence = pd.to_numeric(

        F4C_MANIFEST[
            "assumption_confidence"
        ],

        errors="coerce",

    )


F4C_MANIFEST[
    "pre_specialist_model_confidence"
] = (

    base_confidence

)


F4C_MANIFEST[
    "final_model_confidence"
] = (

    base_confidence

    *

    F4C_MANIFEST[
        "model_confidence_multiplier"
    ]

)


F4C_MANIFEST[
    "final_model_confidence"
] = (

    F4C_MANIFEST[
        "final_model_confidence"
    ]

    .clip(
        lower=0.0,
        upper=1.0,
    )

)


# ============================================================
# 17. FORECAST COMPLETENESS HELPER
# ============================================================

def f4c_forecast_health(
    ticker,
    model_family,
):

    company = (

        F4C_FORECAST[

            F4C_FORECAST[
                "ticker"
            ]
            ==
            ticker

        ]

        .copy()

    )


    row_count = len(
        company
    )


    scenarios = set(

        company[
            "scenario"
        ]
        .dropna()
        .astype(str)
        .tolist()

    )


    years = set(

        pd.to_numeric(

            company[
                "forecast_year"
            ],

            errors="coerce",

        )

        .dropna()
        .astype(int)
        .tolist()

    )


    dimensions_complete = bool(

        row_count
        ==
        F4C_EXPECTED_ROWS_PER_COMPANY

        and

        scenarios
        ==
        F4C_EXPECTED_SCENARIOS

        and

        years
        ==
        F4C_EXPECTED_YEARS

    )


    if model_family in F4C_OPERATING_MODELS:

        required_fields = [

            "revenue_growth",
            "ebit_margin",

            "tax_rate",

            "da_ratio",
            "capex_ratio",
            "nwc_investment_ratio",

            "terminal_growth",

        ]


    else:

        required_fields = [

            "roe",
            "payout_ratio",

            "earnings_growth",

            "terminal_growth",

        ]


    missing_required_columns = [

        field

        for field in required_fields

        if field
        not in
        company.columns

    ]


    if missing_required_columns:

        complete_required_inputs = False

        missing_cells = np.nan


    else:

        missing_cells = int(

            company[
                required_fields
            ]
            .isna()
            .sum()
            .sum()

        )


        complete_required_inputs = (

            missing_cells == 0

        )


    return {

        "forecast_rows":
            row_count,

        "forecast_dimensions_complete":
            dimensions_complete,

        "forecast_missing_cells":
            missing_cells,

        "forecast_inputs_complete":
            complete_required_inputs,

    }


# ============================================================
# 18. EXECUTION-READINESS TEST
# ============================================================

execution_rows = []


for _, row in (

    F4C_MANIFEST
    .iterrows()

):

    ticker = str(

        row[
            "ticker"
        ]

    )


    model_family = row[
        "valuation_model_family"
    ]


    forecast_health = (

        f4c_forecast_health(

            ticker,
            model_family,

        )

    )


    shares = pd.to_numeric(

        pd.Series(
            [
                row.get(
                    "economic_diluted_shares",
                    np.nan,
                )
            ]
        ),

        errors="coerce",

    ).iloc[0]


    discount_rate = pd.to_numeric(

        pd.Series(
            [
                row.get(
                    "discount_rate",
                    np.nan,
                )
            ]
        ),

        errors="coerce",

    ).iloc[0]


    terminal_growth = pd.to_numeric(

        pd.Series(
            [
                row.get(
                    "terminal_growth",
                    np.nan,
                )
            ]
        ),

        errors="coerce",

    ).iloc[0]


    common_ready = bool(

        pd.notna(
            shares
        )

        and

        shares > 0

        and

        pd.notna(
            discount_rate
        )

        and

        pd.notna(
            terminal_growth
        )

        and

        discount_rate
        >
        terminal_growth

        and

        forecast_health[
            "forecast_dimensions_complete"
        ]

        and

        forecast_health[
            "forecast_inputs_complete"
        ]

    )


    # ========================================================
    # OPERATING COMPANY
    # ========================================================

    if model_family in F4C_OPERATING_MODELS:

        ttm_revenue = pd.to_numeric(

            pd.Series(
                [
                    row.get(
                        "ttm_revenue",
                        np.nan,
                    )
                ]
            ),

            errors="coerce",

        ).iloc[0]


        net_debt = pd.to_numeric(

            pd.Series(
                [
                    row.get(
                        "valuation_net_debt",
                        np.nan,
                    )
                ]
            ),

            errors="coerce",

        ).iloc[0]


        model_specific_ready = bool(

            pd.notna(
                ttm_revenue
            )

            and

            ttm_revenue > 0

            and

            pd.notna(
                net_debt
            )

        )


        missing_core_reason = []


        if not (

            pd.notna(
                ttm_revenue
            )

            and

            ttm_revenue > 0

        ):

            missing_core_reason.append(
                "INVALID_TTM_REVENUE"
            )


        if pd.isna(
            net_debt
        ):

            missing_core_reason.append(
                "MISSING_NET_DEBT"
            )


    # ========================================================
    # FINANCIAL COMPANY
    # ========================================================

    elif model_family in F4C_FINANCIAL_MODELS:

        current_equity = pd.to_numeric(

            pd.Series(
                [
                    row.get(
                        "current_equity",
                        np.nan,
                    )
                ]
            ),

            errors="coerce",

        ).iloc[0]


        normalized_roe = pd.to_numeric(

            pd.Series(
                [
                    row.get(
                        "normalized_roe",
                        np.nan,
                    )
                ]
            ),

            errors="coerce",

        ).iloc[0]


        payout = pd.to_numeric(

            pd.Series(
                [
                    row.get(
                        "normalized_payout_ratio",
                        np.nan,
                    )
                ]
            ),

            errors="coerce",

        ).iloc[0]


        model_specific_ready = bool(

            pd.notna(
                current_equity
            )

            and

            current_equity > 0

            and

            pd.notna(
                normalized_roe
            )

            and

            pd.notna(
                payout
            )

        )


        missing_core_reason = []


        if not (

            pd.notna(
                current_equity
            )

            and

            current_equity > 0

        ):

            missing_core_reason.append(
                "INVALID_CURRENT_EQUITY"
            )


        if pd.isna(
            normalized_roe
        ):

            missing_core_reason.append(
                "MISSING_NORMALIZED_ROE"
            )


        if pd.isna(
            payout
        ):

            missing_core_reason.append(
                "MISSING_PAYOUT"
            )


    else:

        model_specific_ready = False


        missing_core_reason = [

            "UNSUPPORTED_MODEL"

        ]


    execution_ready = bool(

        common_ready

        and

        model_specific_ready

        and

        row[
            "execution_model"
        ]
        !=
        "UNSUPPORTED"

    )


    common_failure_reasons = []


    if not (

        pd.notna(
            shares
        )

        and

        shares > 0

    ):

        common_failure_reasons.append(
            "INVALID_SHARE_COUNT"
        )


    if not (

        pd.notna(
            discount_rate
        )

        and

        pd.notna(
            terminal_growth
        )

        and

        discount_rate
        >
        terminal_growth

    ):

        common_failure_reasons.append(
            "INVALID_DISCOUNT_RATE_OR_G"
        )


    if not forecast_health[
        "forecast_dimensions_complete"
    ]:

        common_failure_reasons.append(
            "FORECAST_DIMENSIONS_INCOMPLETE"
        )


    if not forecast_health[
        "forecast_inputs_complete"
    ]:

        common_failure_reasons.append(
            "FORECAST_INPUTS_INCOMPLETE"
        )


    all_failure_reasons = (

        common_failure_reasons

        +

        missing_core_reason

    )


    execution_rows.append({

        "ticker":
            ticker,

        "forecast_rows":
            forecast_health[
                "forecast_rows"
            ],

        "forecast_dimensions_complete":
            forecast_health[
                "forecast_dimensions_complete"
            ],

        "forecast_missing_cells":
            forecast_health[
                "forecast_missing_cells"
            ],

        "forecast_inputs_complete":
            forecast_health[
                "forecast_inputs_complete"
            ],

        "model_specific_inputs_complete":
            model_specific_ready,

        "valuation_execution_ready":
            execution_ready,

        "execution_failure_reason":
            ",".join(
                all_failure_reasons
            ),

    })


F4C_EXECUTION_AUDIT = pd.DataFrame(

    execution_rows

)


F4C_MANIFEST = (

    F4C_MANIFEST

    .merge(

        F4C_EXECUTION_AUDIT,

        on="ticker",

        how="left",

        validate="one_to_one",

    )

)


