# ============================================================
# 20. GENERIC TABLE HASH HELPER
# ============================================================

def f4c_dataframe_hash(
    dataframe,
    sort_columns,
):

    frame = (

        dataframe
        .copy()

    )


    existing_sort_columns = [

        column

        for column
        in sort_columns

        if column
        in frame.columns

    ]


    if existing_sort_columns:

        frame = frame.sort_values(

            existing_sort_columns

        )


    frame = frame.reset_index(
        drop=True
    )


    # Convert datetimes consistently.
    for column in frame.columns:

        if pd.api.types.is_datetime64_any_dtype(

            frame[
                column
            ]

        ):

            frame[
                column
            ] = (

                frame[
                    column
                ]

                .astype(
                    "datetime64[ns]"
                )

                .astype(str)

            )


    hashed = pd.util.hash_pandas_object(

        frame,
        index=False,

    )


    return (

        hashlib.sha256(

            hashed.values
            .tobytes()

        )

        .hexdigest()

    )


