# ============================================================
# 6. COLUMN NORMALIZATION HELPERS
# ============================================================

def f4e_normalized_column_name(
    value
):

    return re.sub(

        r"[^a-z0-9]",

        "",

        str(
            value
        ).lower(),

    )


def f4e_find_column(
    dataframe,
    aliases,
):

    normalized_map = {

        f4e_normalized_column_name(
            column
        ):
            column

        for column
        in dataframe.columns

    }


    for alias in aliases:

        normalized_alias = (

            f4e_normalized_column_name(
                alias
            )

        )


        if normalized_alias in normalized_map:

            return normalized_map[
                normalized_alias
            ]


    return None


def f4e_numeric_series(
    dataframe,
    column,
):

    if (

        column is None

        or

        column
        not in dataframe.columns

    ):

        return pd.Series(

            np.nan,

            index=dataframe.index,

            dtype=float,

        )


    return pd.to_numeric(

        dataframe[
            column
        ],

        errors="coerce",

    )


