# ============================================================
# 12. ECONOMIC-ENTITY KEY
# ============================================================
#
# Removes share-class suffixes so:
#
#   Alphabet Class A / Class C
#   Fox Class A / Class B
#
# are treated as the same issuer for peer exclusion.
# ============================================================

def f4e_entity_key(
    company_name
):

    value = str(
        company_name
    ).upper()


    value = re.sub(

        r"\(\s*CLASS\s+[A-Z0-9]+\s*\)",

        " ",

        value,

    )


    value = re.sub(

        r"\bCLASS\s+[A-Z0-9]+\b",

        " ",

        value,

    )


    value = re.sub(

        r"[^A-Z0-9]+",

        " ",

        value,

    )


    value = re.sub(

        r"\s+",

        " ",

        value,

    ).strip()


    return value


F4E_PEER_MASTER[
    "economic_entity_key"
] = (

    F4E_PEER_MASTER[
        "company_name"
    ]

    .map(
        f4e_entity_key
    )

)


