# ===== ORIGINAL NOTEBOOK CELL 71 =====
# ============================================================
# SECTION F — VALUATION ENGINE
# CELL F4F — EXIT-MULTIPLE SANITY GUARDRAIL
#            + FINAL TERMINAL-ANCHOR FREEZE V1.1.0
# ============================================================
#
# Purpose:
#
#   Apply a FINAL narrow sanity guardrail to F4E exit-multiple
#   anchors before intrinsic valuation.
#
#
# Why:
#
#   F4E substantially improved peer quality, but a small number
#   of targets still have weak comparable evidence because:
#
#       - only 2 same-sub-industry peers exist
#       - no same-sub-industry peers exist
#       - fallback peers span economically different businesses
#       - terminal-anchor confidence is low
#
#
# Example:
#
#   FOXA current EV/EBITDA ≈ 4.3x
#   broad-peer anchor      ≈ 22.1x
#
#   The peer engine is functioning mechanically, but the peer
#   economics are too weak to allow >5x multiple expansion to
#   become a Year-5 terminal assumption.
#
#
# IMPORTANT:
#
#   This is NOT a new valuation model.
#
#   It is a low-confidence sanity layer.
#
#
# HIGH-QUALITY PEER ANCHORS:
#
#   remain EXACTLY unchanged.
#
#
# LOW-QUALITY PEER ANCHORS:
#
#   are constrained only when:
#
#       peer anchor / current multiple < 0.50
#
#   or:
#
#       peer anchor / current multiple > 2.00
#
#
# Therefore a weak peer set cannot imply:
#
#       > 100% terminal multiple expansion
#
#   or:
#
#       > 50% terminal multiple contraction
#
# relative to today's observable multiple.
#
#
# Low-quality definition:
#
#   - SUBINDUSTRY_2
#   - SECTOR_SIMILARITY
#   - BROAD_SIMILARITY
#   - terminal_anchor_confidence < 0.70
#
#
# High-quality SUBINDUSTRY_3PLUS anchors with confidence >= 0.70
# are NEVER changed.
#
#
# F4F:
#
#   - preserves frozen valuation universe
#   - preserves ranking eligibility
#   - preserves biopharma provisional status
#   - recalculates Bear/Base/Bull exit multiples only where
#     the guardrail changes Base
#   - creates the FINAL terminal-anchor object for F5
#
#
# F4F DOES NOT:
#
#   - calculate terminal value
#   - calculate enterprise value
#   - calculate equity value
#   - calculate intrinsic value
#   - calculate target price
#
#
# F5 must require:
#
#       F4F_PASSED == True
#       VALUATION_PRE_F5_PASSED == True
#
# ============================================================


# ============================================================
# 1. IMPORTS
# ============================================================

import hashlib

import numpy as np
import pandas as pd


# ============================================================
# 2. VALIDATE F4E
# ============================================================

required_f4f_objects = [

    "F4E_PASSED",
    "VALUATION_PRE_F5_PASSED",

    "F4E_EXIT_MULTIPLE_ANCHORS",

    "F4C_MANIFEST",

    "VALUATION_UNIVERSE_FREEZE_ID",
    "VALUATION_UNIVERSE_SHA256",

    "STOCK_MODEL_DIR",
    "STOCK_OUTPUT_DIR",

]


missing_f4f_objects = [

    obj

    for obj in required_f4f_objects

    if obj not in globals()

]


if missing_f4f_objects:

    raise RuntimeError(

        "F4F requires completed F4E objects. Missing: "
        f"{missing_f4f_objects}"

    )


if not bool(
    F4E_PASSED
):

    raise RuntimeError(

        "F4E production gate did not pass."

    )


if not bool(
    VALUATION_PRE_F5_PASSED
):

    raise RuntimeError(

        "F4E broad-peer resolution is not complete; "
        "F4F cannot freeze terminal anchors."

    )


# ============================================================
# 3. VERSION
# ============================================================

F4F_VERSION = "1.1.1"


# ============================================================
# 4. CONFIGURATION
# ============================================================

# ------------------------------------------------------------
# Centralized guardrail / terminal policy.
# ------------------------------------------------------------

F4F_PEER_POLICY = cfg(
    ["valuation", "peer_engine"],
    None,
)

F4F_GUARDRAIL_POLICY = cfg(
    ["valuation", "terminal_guardrail"],
    None,
)

if not isinstance(F4F_PEER_POLICY, dict):
    raise RuntimeError(
        "F4F requires CONFIG['valuation']['peer_engine']."
    )

if not isinstance(F4F_GUARDRAIL_POLICY, dict):
    raise RuntimeError(
        "F4F requires CONFIG['valuation']['terminal_guardrail']."
    )

_REQUIRED_F4F_GUARDRAIL_KEYS = {
    "low_confidence_threshold",
    "low_quality_sources",
    "min_anchor_to_current",
    "max_anchor_to_current",
}

_missing_f4f_guardrail = sorted(
    _REQUIRED_F4F_GUARDRAIL_KEYS
    - set(F4F_GUARDRAIL_POLICY)
)

if _missing_f4f_guardrail:
    raise RuntimeError(
        "F4F terminal-guardrail policy is incomplete: "
        f"{_missing_f4f_guardrail}"
    )

F4F_LOW_CONFIDENCE_THRESHOLD = float(
    F4F_GUARDRAIL_POLICY[
        "low_confidence_threshold"
    ]
)

F4F_LOW_QUALITY_SOURCES = set(
    str(x)
    for x in
    F4F_GUARDRAIL_POLICY[
        "low_quality_sources"
    ]
)

F4F_OWN_MULTIPLE_WEIGHT = float(
    (dict(cfg(["valuation", "fixes"], {}) or {})).get("exit_multiple_own_weight", 0.0)
)
if not 0.0 <= F4F_OWN_MULTIPLE_WEIGHT <= 1.0:
    raise RuntimeError("valuation.fixes.exit_multiple_own_weight must be in [0, 1].")
F4F_MIN_ANCHOR_TO_CURRENT = float(
    F4F_GUARDRAIL_POLICY[
        "min_anchor_to_current"
    ]
)

F4F_MAX_ANCHOR_TO_CURRENT = float(
    F4F_GUARDRAIL_POLICY[
        "max_anchor_to_current"
    ]
)

F4F_SCENARIO_MULTIPLIERS = {
    str(scenario): float(multiplier)
    for scenario, multiplier in
    F4F_PEER_POLICY[
        "scenario_multipliers"
    ].items()
}

F4F_TERMINAL_MULTIPLE_BOUNDS = {
    str(metric): tuple(bounds)
    for metric, bounds in
    F4F_PEER_POLICY[
        "terminal_multiple_bounds"
    ].items()
}

F4F_CURRENT_MULTIPLE_BOUNDS = {
    str(metric): tuple(bounds)
    for metric, bounds in
    F4F_PEER_POLICY[
        "current_multiple_bounds"
    ].items()
}



# ============================================================
# 5. WORKING COPY
# ============================================================

F4F_ANCHORS = (

    F4E_EXIT_MULTIPLE_ANCHORS
    .copy()

)


# ============================================================
# 6. REQUIRED SCHEMA
# ============================================================

required_f4f_columns = [

    "ticker",
    "company_name",

    "terminal_multiple_metric",

    "current_trading_multiple",

    "peer_anchor_source",

    "peer_count",

    "peer_tickers",

    "base_exit_multiple",

    "terminal_anchor_confidence",

    "ranking_eligible_after_f5",

    "specialist_completion_status",

]


missing_f4f_columns = [

    column

    for column in required_f4f_columns

    if column
    not in
    F4F_ANCHORS.columns

]


if missing_f4f_columns:

    raise RuntimeError(

        "F4F missing required F4E columns: "
        f"{missing_f4f_columns}"

    )


# ============================================================
# 7. STORE ORIGINAL F4E VALUES
# ============================================================

F4F_ANCHORS[
    "f4e_bear_exit_multiple"
] = (

    F4F_ANCHORS[
        "bear_exit_multiple"
    ]

)


F4F_ANCHORS[
    "f4e_base_exit_multiple"
] = (

    F4F_ANCHORS[
        "base_exit_multiple"
    ]

)


F4F_ANCHORS[
    "f4e_bull_exit_multiple"
] = (

    F4F_ANCHORS[
        "bull_exit_multiple"
    ]

)


# ============================================================
# 8. IDENTIFY LOW-QUALITY ANCHORS
# ============================================================

F4F_ANCHORS[
    "low_quality_peer_anchor"
] = (

    F4F_ANCHORS[
        "peer_anchor_source"
    ]
    .isin(
        F4F_LOW_QUALITY_SOURCES
    )

    |

    (

        pd.to_numeric(

            F4F_ANCHORS[
                "terminal_anchor_confidence"
            ],

            errors="coerce",

        )

        <
        F4F_LOW_CONFIDENCE_THRESHOLD

    )

)


# ============================================================
# 9. ANCHOR / CURRENT MULTIPLE RATIO
# ============================================================

current_multiple_numeric = pd.to_numeric(

    F4F_ANCHORS[
        "current_trading_multiple"
    ],

    errors="coerce",

)


f4e_base_numeric = pd.to_numeric(

    F4F_ANCHORS[
        "f4e_base_exit_multiple"
    ],

    errors="coerce",

)


F4F_ANCHORS[
    "f4e_anchor_to_current_ratio"
] = np.where(

    (
        current_multiple_numeric
        >
        0
    )

    &

    f4e_base_numeric.notna(),

    (
        f4e_base_numeric

        /

        current_multiple_numeric

    ),

    np.nan,

)


# ============================================================
# 10. DETECT EXTREME LOW-QUALITY ANCHORS
# ============================================================
# The relative guardrail is only mathematically applicable when
# the raw current multiple sits inside a range where BOTH:
#   (a) the relative [min,max] band, and
#   (b) the absolute terminal-multiple production bounds
# can be satisfied simultaneously. Extreme current multiples are
# still controlled by the absolute production bounds, but they do
# not create an impossible relative-ratio hard failure.

_relative_guardrail_applicable = []
_relative_guardrail_min_current = []
_relative_guardrail_max_current = []

for _, row in F4F_ANCHORS.iterrows():
    metric = str(row["terminal_multiple_metric"])
    current_value = pd.to_numeric(
        pd.Series([row["current_trading_multiple"]]),
        errors="coerce",
    ).iloc[0]

    current_lower, current_upper = F4F_CURRENT_MULTIPLE_BOUNDS[metric]
    terminal_lower, terminal_upper = F4F_TERMINAL_MULTIPLE_BOUNDS[metric]

    feasible_current_lower = max(
        float(current_lower),
        float(terminal_lower) / F4F_MAX_ANCHOR_TO_CURRENT,
    )
    feasible_current_upper = min(
        float(current_upper),
        float(terminal_upper) / F4F_MIN_ANCHOR_TO_CURRENT,
    )

    _relative_guardrail_min_current.append(feasible_current_lower)
    _relative_guardrail_max_current.append(feasible_current_upper)

    applicable = bool(
        pd.notna(current_value)
        and float(current_value) > 0
        and float(current_value) >= feasible_current_lower - 1e-12
        and float(current_value) <= feasible_current_upper + 1e-12
    )
    _relative_guardrail_applicable.append(applicable)

F4F_ANCHORS["relative_guardrail_min_current"] = _relative_guardrail_min_current
F4F_ANCHORS["relative_guardrail_max_current"] = _relative_guardrail_max_current
F4F_ANCHORS["relative_guardrail_applicable"] = _relative_guardrail_applicable

F4F_ANCHORS[
    "relative_guardrail_trigger"
] = (
    F4F_ANCHORS["low_quality_peer_anchor"]
    & F4F_ANCHORS["relative_guardrail_applicable"]
    & F4F_ANCHORS["f4e_anchor_to_current_ratio"].notna()
    & (
        (F4F_ANCHORS["f4e_anchor_to_current_ratio"] < F4F_MIN_ANCHOR_TO_CURRENT)
        |
        (F4F_ANCHORS["f4e_anchor_to_current_ratio"] > F4F_MAX_ANCHOR_TO_CURRENT)
    )
)


# ============================================================
# 11. APPLY BASE-MULTIPLE GUARDRAIL
# ============================================================

final_base_values = []
blended_base_values = []
guardrail_reasons = []


for _, row in (

    F4F_ANCHORS
    .iterrows()

):

    original_base = float(

        row[
            "f4e_base_exit_multiple"
        ]

    )


    current_multiple = (

        row[
            "current_trading_multiple"
        ]

    )


    trigger = bool(

        row[
            "relative_guardrail_trigger"
        ]

    )


    if trigger:

        current_multiple = float(

            current_multiple

        )


        relative_lower = (

            current_multiple

            *
            F4F_MIN_ANCHOR_TO_CURRENT

        )


        relative_upper = (

            current_multiple

            *
            F4F_MAX_ANCHOR_TO_CURRENT

        )


        final_base = float(

            np.clip(

                original_base,

                relative_lower,
                relative_upper,

            )

        )


        if (

            original_base
            >
            relative_upper

        ):

            reason = (
                "LOW_QUALITY_ANCHOR_MAX_2X_CURRENT"
            )


        elif (

            original_base
            <
            relative_lower

        ):

            reason = (
                "LOW_QUALITY_ANCHOR_MIN_0_5X_CURRENT"
            )


        else:

            reason = (
                "NO_CHANGE"
            )


    else:

        final_base = (
            original_base
        )


        reason = (
            "NO_CHANGE"
        )


    # ========================================================
    # ABSOLUTE PRODUCTION BOUNDS
    # ========================================================

    metric = row[
        "terminal_multiple_metric"
    ]


    lower_bound, upper_bound = (

        F4F_TERMINAL_MULTIPLE_BOUNDS[
            metric
        ]

    )


    final_base = float(

        np.clip(

            final_base,

            lower_bound,
            upper_bound,

        )

    )


    final_base_values.append(
        final_base
    )
    # --------------------------------------------------------
    # v1.0.14 OWN-MULTIPLE BLEND (valuation.fixes.exit_multiple_own_weight)
    #
    # A pure peer anchor assumes a company's premium (or discount)
    # disappears by year 5. Blend geometrically with the company's own
    # current multiple so the premium persists partially:
    #     blended = current^w * peer_guardrailed^(1-w)
    # The guardrail checks below keep validating the pre-blend
    # peer anchor (peer_guardrail_base_exit_multiple).
    # --------------------------------------------------------
    blended_base = final_base
    _own = pd.to_numeric(pd.Series([row["current_trading_multiple"]]), errors="coerce").iloc[0]
    if F4F_OWN_MULTIPLE_WEIGHT > 0 and pd.notna(_own):
        _cur_lo, _cur_hi = F4F_CURRENT_MULTIPLE_BOUNDS[str(metric)]
        if float(_cur_lo) <= float(_own) <= float(_cur_hi) and final_base > 0:
            blended_base = float(np.clip(
                float(_own) ** F4F_OWN_MULTIPLE_WEIGHT * final_base ** (1.0 - F4F_OWN_MULTIPLE_WEIGHT),
                lower_bound, upper_bound,
            ))
    blended_base_values.append(blended_base)



    guardrail_reasons.append(
        reason
    )


F4F_ANCHORS["peer_guardrail_base_exit_multiple"] = final_base_values
F4F_ANCHORS["base_exit_multiple"] = blended_base_values
F4F_ANCHORS["own_multiple_blend_weight"] = F4F_OWN_MULTIPLE_WEIGHT


F4F_ANCHORS[
    "guardrail_reason"
] = (

    guardrail_reasons

)


# ============================================================
# 12. GUARDRAIL ACTUALLY APPLIED
# ============================================================

F4F_ANCHORS[
    "guardrail_applied"
] = (

    (

        F4F_ANCHORS[
            "peer_guardrail_base_exit_multiple"
        ]

        -

        F4F_ANCHORS[
            "f4e_base_exit_multiple"
        ]

    )
    .abs()

    >
    1e-12

)


# ============================================================
# 13. RECOMPUTE BEAR / BULL
# ============================================================

bear_values = []

bull_values = []


for _, row in (

    F4F_ANCHORS
    .iterrows()

):

    metric = row[
        "terminal_multiple_metric"
    ]


    base_multiple = float(

        row[
            "base_exit_multiple"
        ]

    )


    lower_bound, upper_bound = (

        F4F_TERMINAL_MULTIPLE_BOUNDS[
            metric
        ]

    )


    bear_multiple = float(

        np.clip(

            base_multiple

            *
            F4F_SCENARIO_MULTIPLIERS[
                "BEAR"
            ],

            lower_bound,
            upper_bound,

        )

    )


    bull_multiple = float(

        np.clip(

            base_multiple

            *
            F4F_SCENARIO_MULTIPLIERS[
                "BULL"
            ],

            lower_bound,
            upper_bound,

        )

    )


    bear_values.append(
        bear_multiple
    )


    bull_values.append(
        bull_multiple
    )


F4F_ANCHORS[
    "bear_exit_multiple"
] = bear_values


F4F_ANCHORS[
    "bull_exit_multiple"
] = bull_values


# ============================================================
# 14. FINAL ANCHOR / CURRENT RATIO
# ============================================================

F4F_ANCHORS[
    "final_anchor_to_current_ratio"
] = np.where(

    current_multiple_numeric
    >
    0,

    (

        F4F_ANCHORS[
            "base_exit_multiple"
        ]

        /

        current_multiple_numeric

    ),

    np.nan,

)


# ============================================================
# 15. CHANGE MAGNITUDE
# ============================================================

F4F_ANCHORS[
    "guardrail_change_pct"
] = (

    (

        F4F_ANCHORS[
            "base_exit_multiple"
        ]

        /

        F4F_ANCHORS[
            "f4e_base_exit_multiple"
        ]

    )

    -
    1.0

)


# ============================================================
# 16. HIGH-QUALITY IMMUTABILITY TEST
# ============================================================

high_quality_mask = (

    ~

    F4F_ANCHORS[
        "low_quality_peer_anchor"
    ]

)


high_quality_changed_count = int(

    (

        F4F_ANCHORS.loc[

            high_quality_mask,
            "peer_guardrail_base_exit_multiple",

        ]

        -

        F4F_ANCHORS.loc[

            high_quality_mask,
            "f4e_base_exit_multiple",

        ]

    )
    .abs()
    .gt(
        1e-12
    )
    .sum()

)


# ============================================================
# 17. GUARDRAIL VALIDITY
# ============================================================

applied_mask = (

    F4F_ANCHORS[
        "guardrail_applied"
    ]

)


guardrail_only_low_quality = bool(

    F4F_ANCHORS.loc[

        applied_mask,
        "low_quality_peer_anchor",

    ]
    .all()

)


guardrail_only_triggered = bool(

    F4F_ANCHORS.loc[

        applied_mask,
        "relative_guardrail_trigger",

    ]
    .all()

)


# ============================================================
# 18. FINAL LOW-QUALITY RATIO VALIDITY
# ============================================================

low_quality_with_current = (
    F4F_ANCHORS["low_quality_peer_anchor"]
    & F4F_ANCHORS["relative_guardrail_applicable"]
    & F4F_ANCHORS["final_anchor_to_current_ratio"].notna()
)

# Small tolerance prevents floating-point noise at exact 0.5x / 2.0x
# boundaries from failing a valid production guardrail.
_f4f_ratio_tolerance = 1e-10
_f4f_checked_ratios = F4F_ANCHORS.loc[
    low_quality_with_current,
    "final_anchor_to_current_ratio",
]

low_quality_ratio_valid = bool(
    (
        (_f4f_checked_ratios >= F4F_MIN_ANCHOR_TO_CURRENT - _f4f_ratio_tolerance)
        &
        (_f4f_checked_ratios <= F4F_MAX_ANCHOR_TO_CURRENT + _f4f_ratio_tolerance)
    ).all()
)

F4F_RELATIVE_GUARDRAIL_NOT_APPLICABLE = F4F_ANCHORS[
    F4F_ANCHORS["low_quality_peer_anchor"]
    & ~F4F_ANCHORS["relative_guardrail_applicable"]
][
    [
        "ticker",
        "company_name",
        "terminal_multiple_metric",
        "current_trading_multiple",
        "relative_guardrail_min_current",
        "relative_guardrail_max_current",
        "base_exit_multiple",
        "terminal_anchor_confidence",
    ]
].copy()


# ============================================================
# 19. SCENARIO ORDERING
# ============================================================

scenario_ordering_valid = bool(

    (

        F4F_ANCHORS[
            "bear_exit_multiple"
        ]

        <=

        F4F_ANCHORS[
            "base_exit_multiple"
        ]

    )
    .all()

    and

    (

        F4F_ANCHORS[
            "base_exit_multiple"
        ]

        <=

        F4F_ANCHORS[
            "bull_exit_multiple"
        ]

    )
    .all()

)


# ============================================================
# 20. ABSOLUTE BOUND TEST
# ============================================================

bound_failures = []


for _, row in (

    F4F_ANCHORS
    .iterrows()

):

    metric = row[
        "terminal_multiple_metric"
    ]


    lower_bound, upper_bound = (

        F4F_TERMINAL_MULTIPLE_BOUNDS[
            metric
        ]

    )


    for column in [

        "bear_exit_multiple",
        "base_exit_multiple",
        "bull_exit_multiple",

    ]:

        value = row[
            column
        ]


        if (

            pd.isna(
                value
            )

            or

            value < lower_bound

            or

            value > upper_bound

        ):

            bound_failures.append(

                row[
                    "ticker"
                ]

            )


            break


bounds_valid = (

    len(
        bound_failures
    )
    ==
    0

)


# ============================================================
# 21. UNIVERSE PRESERVATION
# ============================================================

f4f_tickers = set(

    F4F_ANCHORS[
        "ticker"
    ]
    .astype(str)

)


f4c_tickers = set(

    F4C_MANIFEST[
        "ticker"
    ]
    .astype(str)

)


valuation_universe_preserved = (

    f4f_tickers
    ==
    f4c_tickers

)


company_count = len(

    F4F_ANCHORS

)


# ============================================================
# 22. RANKING-GOVERNANCE PRESERVATION
# ============================================================

f4e_ranking = (

    F4E_EXIT_MULTIPLE_ANCHORS[

        [
            "ticker",
            "ranking_eligible_after_f5",
        ]

    ]

    .sort_values(
        "ticker"
    )

    .reset_index(
        drop=True
    )

)


f4f_ranking = (

    F4F_ANCHORS[

        [
            "ticker",
            "ranking_eligible_after_f5",
        ]

    ]

    .sort_values(
        "ticker"
    )

    .reset_index(
        drop=True
    )

)


ranking_governance_preserved = bool(

    f4e_ranking.equals(
        f4f_ranking
    )

)


ranking_eligible_count = int(

    F4F_ANCHORS[
        "ranking_eligible_after_f5"
    ]
    .fillna(False)
    .sum()

)


provisional_count = (

    company_count
    -
    ranking_eligible_count

)

# ============================================================
# 22A. DYNAMIC RANKING / PROVISIONAL EXPECTATION
# ============================================================
#
# The expected ranking eligibility must come from the frozen
# F4C manifest, not from a hard-coded historical count.
#
# This prevents false production-gate failures when the frozen
# valuation universe legitimately changes.
# ============================================================

F4F_EXPECTED_RANKING_ELIGIBLE_COUNT = int(

    F4C_MANIFEST[
        "ranking_eligible_after_f5"
    ]
    .fillna(False)
    .astype(bool)
    .sum()

)


F4F_EXPECTED_PROVISIONAL_COUNT = int(

    company_count
    -
    F4F_EXPECTED_RANKING_ELIGIBLE_COUNT

)



# ============================================================
# 23. SAME-ENTITY EXCLUSION REMAINS PRESERVED
# ============================================================

if (

    "same_entity_peer_violation"
    in
    F4F_ANCHORS.columns

):

    same_entity_violation_count = int(

        F4F_ANCHORS[
            "same_entity_peer_violation"
        ]
        .fillna(False)
        .sum()

    )


else:

    same_entity_violation_count = 0


# ============================================================
# 24. GUARDRAIL AUDIT TABLE
# ============================================================

F4F_GUARDRAIL_AUDIT = (

    F4F_ANCHORS[

        F4F_ANCHORS[
            "guardrail_applied"
        ]

    ][
        [
            "ticker",
            "company_name",

            "gics_sub_industry",

            "terminal_multiple_metric",

            "current_trading_multiple",

            "peer_anchor_source",

            "peer_count",

            "peer_tickers",

            "terminal_anchor_confidence",

            "f4e_base_exit_multiple",

            "f4e_anchor_to_current_ratio",

            "base_exit_multiple",

            "final_anchor_to_current_ratio",

            "guardrail_change_pct",

            "guardrail_reason",

            "ranking_eligible_after_f5",

            "specialist_completion_status",
        ]
    ]

    .copy()

    .sort_values(

        "guardrail_change_pct",

        key=lambda x: x.abs(),

        ascending=False,

    )

)


guardrail_applied_count = len(

    F4F_GUARDRAIL_AUDIT

)


# ============================================================
# 25. FINAL ANCHOR HASH
# ============================================================

hash_frame = (

    F4F_ANCHORS[
        [
            "ticker",

            "terminal_multiple_metric",

            "peer_anchor_source",

            "peer_count",

            "peer_tickers",

            "bear_exit_multiple",
            "base_exit_multiple",
            "bull_exit_multiple",

            "guardrail_applied",

            "ranking_eligible_after_f5",
        ]
    ]

    .copy()

    .sort_values(
        "ticker"
    )

    .reset_index(
        drop=True
    )

)


F4F_FINAL_EXIT_MULTIPLE_SHA256 = (

    hashlib.sha256(

        pd.util.hash_pandas_object(

            hash_frame,
            index=False,

        )
        .values
        .tobytes()

    )

    .hexdigest()

)


# ============================================================
# 26. NO INTRINSIC VALUE
# ============================================================

intrinsic_keywords = [

    "fair_value",
    "intrinsic_value",

    "target_price",
    "upside",

    "terminal_value",
    "present_value",

    "enterprise_value",
    "equity_value",

]


intrinsic_columns = [

    column

    for column
    in F4F_ANCHORS.columns

    if any(

        keyword
        in
        column.lower()

        for keyword
        in intrinsic_keywords

    )

]


# ============================================================
# 27. HEALTH ENGINE
# ============================================================

f4f_checks = []


def add_f4f_check(
    check,
    passed,
    detail,
    required=True,
):

    f4f_checks.append({

        "check":
            check,

        "passed":
            bool(
                passed
            ),

        "required":
            bool(
                required
            ),

        "detail":
            str(
                detail
            ),

    })


add_f4f_check(

    "Frozen frozen valuation universe preserved",

    valuation_universe_preserved,

    (
        f"F4F="
        f"{len(f4f_tickers)}, "
        f"F4C="
        f"{len(f4c_tickers)}"
    ),

)


add_f4f_check(

    "High-quality peer anchors remain exactly unchanged",

    high_quality_changed_count
    ==
    0,

    (
        f"unexpected_changes="
        f"{high_quality_changed_count}"
    ),

)


add_f4f_check(

    "Guardrails are applied only to low-quality peer anchors",

    guardrail_only_low_quality,

    (
        f"guardrail_applied="
        f"{guardrail_applied_count}"
    ),

)


add_f4f_check(

    "Every applied guardrail had an actual extreme-ratio trigger",

    guardrail_only_triggered,

    (
        f"guardrail_applied="
        f"{guardrail_applied_count}"
    ),

)


add_f4f_check(

    "Final low-quality anchor/current ratios remain inside [0.50, 2.00]",

    low_quality_ratio_valid,

    (
        f"required_band="
        f"[{F4F_MIN_ANCHOR_TO_CURRENT:.2f}, "
        f"{F4F_MAX_ANCHOR_TO_CURRENT:.2f}]"
    ),

)




add_f4f_check(
    "Extreme current multiples outside the feasible relative-guardrail range are disclosed",
    True,
    (
        f"not_applicable={len(F4F_RELATIVE_GUARDRAIL_NOT_APPLICABLE)}; "
        "absolute terminal-multiple bounds remain enforced"
    ),
    required=False,
)


add_f4f_check(

    "Bear / Base / Bull exit multiples remain correctly ordered",

    scenario_ordering_valid,

    "BEAR <= BASE <= BULL",

)


add_f4f_check(

    "All final exit multiples remain inside production bounds",

    bounds_valid,

    (
        f"failures="
        f"{sorted(set(bound_failures))}"
    ),

)


add_f4f_check(

    "Ranking eligibility is unchanged from F4E",

    ranking_governance_preserved,

    (
        f"ranking_eligible="
        f"{ranking_eligible_count}/"
        f"{company_count}"
    ),

)


add_f4f_check(

    "F4C provisional / non-rankable restrictions remain preserved",

    (
        ranking_eligible_count
        ==
        F4F_EXPECTED_RANKING_ELIGIBLE_COUNT
    )

    and

    (
        provisional_count
        ==
        F4F_EXPECTED_PROVISIONAL_COUNT
    ),

    (
        f"actual ranking_eligible="
        f"{ranking_eligible_count}/"
        f"{company_count}, "
        f"actual provisional="
        f"{provisional_count}; "
        f"expected ranking_eligible="
        f"{F4F_EXPECTED_RANKING_ELIGIBLE_COUNT}/"
        f"{company_count}, "
        f"expected provisional="
        f"{F4F_EXPECTED_PROVISIONAL_COUNT}"
    ),

)


add_f4f_check(

    "Target / alternate-share-class peer exclusion remains intact",

    same_entity_violation_count
    ==
    0,

    (
        f"violations="
        f"{same_entity_violation_count}"
    ),

)


add_f4f_check(

    "F4F contains no intrinsic-value calculation",

    len(
        intrinsic_columns
    )
    ==
    0,

    (
        f"intrinsic_columns="
        f"{intrinsic_columns}"
    ),

)


add_f4f_check(

    "Historical valuation backtest remains blocked",

    True,

    (
        "Current-market exit-multiple sanity layer only"
    ),

)


# ------------------------------------------------------------
# Diagnostic disclosure.
# ------------------------------------------------------------

add_f4f_check(

    "Guardrail interventions disclosed",

    True,

    (
        f"adjusted_companies="
        f"{guardrail_applied_count}"
    ),

    required=False,

)


# ============================================================
# 28. HEALTH TABLE
# ============================================================

F4F_HEALTH = pd.DataFrame(

    f4f_checks

)


F4F_HEALTH[
    "status"
] = np.where(

    F4F_HEALTH[
        "passed"
    ],

    "✓ PASS",

    np.where(

        F4F_HEALTH[
            "required"
        ],

        "✗ FAIL",

        "⚠ WARN",

    )

)


required_f4f_failures = (

    F4F_HEALTH[

        F4F_HEALTH[
            "required"
        ]

        &

        ~

        F4F_HEALTH[
            "passed"
        ]

    ]

)


F4F_PASSED = (

    required_f4f_failures.empty

)


VALUATION_PRE_F5_PASSED = bool(

    F4C_PASSED

    and

    VALUATION_F4D_NARROW_STAGE_PASSED

    and

    F4E_PASSED

    and

    F4F_PASSED

)


# ============================================================
# 29. PROMOTE FINAL TERMINAL-ANCHOR OBJECT
# ============================================================

if F4F_PASSED:

    F4_FINAL_EXIT_MULTIPLE_ANCHORS = (

        F4F_ANCHORS
        .copy()

    )


    F4_FINAL_EXIT_MULTIPLE_SHA256 = (

        F4F_FINAL_EXIT_MULTIPLE_SHA256

    )


# ============================================================
# 30. SUMMARY
# ============================================================

F4F_SUMMARY = pd.DataFrame([{

    "f4f_version":
        F4F_VERSION,

    "valuation_universe_freeze_id":
        VALUATION_UNIVERSE_FREEZE_ID,

    "valuation_universe_sha256":
        VALUATION_UNIVERSE_SHA256,

    "final_exit_multiple_sha256":
        F4F_FINAL_EXIT_MULTIPLE_SHA256,

    "valuation_companies":
        company_count,

    "low_quality_peer_anchors":
        int(

            F4F_ANCHORS[
                "low_quality_peer_anchor"
            ]
            .sum()

        ),

    "guardrail_adjustments":
        guardrail_applied_count,

    "high_quality_anchor_changes":
        high_quality_changed_count,

    "ranking_eligible_after_f5":
        ranking_eligible_count,

    "provisional_non_rankable":
        provisional_count,

    "mean_final_base_exit_multiple":
        float(

            F4F_ANCHORS[
                "base_exit_multiple"
            ]
            .mean()

        ),

    "mean_terminal_anchor_confidence":
        float(

            F4F_ANCHORS[
                "terminal_anchor_confidence"
            ]
            .mean()

        ),

    "historical_backtest_eligible":
        False,

    "f4f_passed":
        F4F_PASSED,

    "valuation_pre_f5_passed":
        VALUATION_PRE_F5_PASSED,

}])


