def f6_numeric(
    value,
    default=np.nan,
):

    try:

        output = float(
            value
        )


        if _f_isfinite(
            output
        ):

            return output


    except Exception:

        pass


    return default


# ============================================================
# 8. BASE ASSUMPTION HELPER
# ============================================================

def f6_base_assumptions(
    ticker
):

    output = (

        F6_FORECAST_INPUTS[

            (
                F6_FORECAST_INPUTS[
                    "ticker"
                ]
                .astype(str)
                ==
                str(
                    ticker
                )
            )

            &

            (
                F6_FORECAST_INPUTS[
                    "scenario"
                ]
                ==
                "BASE"
            )

        ]

        .sort_values(
            "forecast_year"
        )

        .copy()

        .reset_index(
            drop=True
        )

    )


    expected_years = set(int(year) for year in F4C_EXPECTED_YEARS)
    actual_years = set(
        pd.to_numeric(output["forecast_year"], errors="coerce")
        .dropna()
        .astype(int)
    )

    if (
        len(output) != len(expected_years)
        or actual_years != expected_years
    ):

        raise RuntimeError(
            f"{ticker}: BASE forecast-year lineage mismatch; "
            f"expected={sorted(expected_years)}, "
            f"actual={sorted(actual_years)}, rows={len(output)}."
        )


    return output


# ============================================================
# 9. ROBUST ROOT SOLVER
# ============================================================
#
# Uses a dense grid first instead of assuming endpoint
# monotonicity.
#
# If multiple roots exist, use the root closest to zero:
#
#   the smallest assumption change required by the market.
# ============================================================

def f6_bisection(
    function,
    lower,
    upper,
    tolerance=F6_ROOT_TOLERANCE,
    max_iterations=250,
):

    f_lower = function(
        lower
    )

    f_upper = function(
        upper
    )


    if not (

        _f_isfinite(
            f_lower
        )

        and

        _f_isfinite(
            f_upper
        )

    ):

        return np.nan


    if abs(
        f_lower
    ) <= tolerance:

        return float(
            lower
        )


    if abs(
        f_upper
    ) <= tolerance:

        return float(
            upper
        )


    if (

        f_lower
        *
        f_upper

    ) > 0:

        return np.nan


    left = float(
        lower
    )

    right = float(
        upper
    )


    for _ in range(
        max_iterations
    ):

        midpoint = (

            0.5
            *
            (
                left
                +
                right
            )

        )


        f_mid = function(
            midpoint
        )


        if not _f_isfinite(
            f_mid
        ):

            return np.nan


        if (

            abs(
                f_mid
            )
            <=
            tolerance

            or

            abs(
                right
                -
                left
            )
            <=
            tolerance

        ):

            return float(
                midpoint
            )


        if (

            f_lower
            *
            f_mid

        ) <= 0:

            right = (
                midpoint
            )


            f_upper = (
                f_mid
            )


        else:

            left = (
                midpoint
            )


            f_lower = (
                f_mid
            )


    return float(

        0.5
        *
        (
            left
            +
            right
        )

    )


def f6_find_root(
    function,
    lower,
    upper,
):

    grid = np.linspace(

        lower,
        upper,

        F6_ROOT_GRID_POINTS,

    )


    evaluated = []


    for x in grid:

        try:

            y = function(
                float(
                    x
                )
            )


        except Exception:

            y = np.nan


        if _f_isfinite(
            y
        ):

            evaluated.append(

                (
                    float(
                        x
                    ),

                    float(
                        y
                    ),
                )

            )


    if not evaluated:

        return {

            "root":
                np.nan,

            "status":
                "NO_FINITE_FUNCTION_VALUES",

            "lower_value":
                np.nan,

            "upper_value":
                np.nan,

        }


    # --------------------------------------------------------
    # Exact grid match.
    # --------------------------------------------------------

    exact_matches = [

        (
            abs(
                y
            ),
            x,
        )

        for x, y
        in evaluated

        if abs(
            y
        )
        <=
        F6_ROOT_TOLERANCE

    ]


    if exact_matches:

        root = min(

            exact_matches,

            key=lambda z:
                (
                    abs(
                        z[1]
                    ),
                    z[0],
                )

        )[1]


        return {

            "root":
                float(
                    root
                ),

            "status":
                "SOLVED",

            "lower_value":
                evaluated[0][1],

            "upper_value":
                evaluated[-1][1],

        }


    # --------------------------------------------------------
    # Identify all sign-changing intervals.
    # --------------------------------------------------------

    brackets = []


    for i in range(

        len(
            evaluated
        )
        -
        1

    ):

        x1, y1 = evaluated[i]

        x2, y2 = evaluated[
            i + 1
        ]


        if (

            y1
            *
            y2

        ) < 0:

            brackets.append(

                (
                    x1,
                    x2,
                )

            )


    roots = []


    for left, right in brackets:

        root = f6_bisection(

            function,
            left,
            right,

        )


        if _f_isfinite(
            root
        ):

            roots.append(
                root
            )


    if roots:

        root = min(

            roots,

            key=lambda x:
                abs(
                    x
                ),

        )


        return {

            "root":
                float(
                    root
                ),

            "status":
                "SOLVED",

            "lower_value":
                evaluated[0][1],

            "upper_value":
                evaluated[-1][1],

        }


    # --------------------------------------------------------
    # No root in economically permitted search interval.
    # --------------------------------------------------------

    evaluated_sorted = sorted(

        evaluated,
        key=lambda z:
            z[0],

    )


    lower_value = (

        evaluated_sorted[0][1]

    )


    upper_value = (

        evaluated_sorted[-1][1]

    )


    values = np.array(

        [
            y

            for _, y
            in evaluated_sorted
        ],

        dtype=float,

    )


    if np.all(
        values < 0
    ):

        status = (
            "MARKET_REQUIRES_DRIVER_ABOVE_SEARCH_BOUND"
        )


    elif np.all(
        values > 0
    ):

        status = (
            "MARKET_REQUIRES_DRIVER_BELOW_SEARCH_BOUND"
        )


    else:

        status = (
            "NO_STABLE_ROOT_IN_SEARCH_RANGE"
        )


    return {

        "root":
            np.nan,

        "status":
            status,

        "lower_value":
            lower_value,

        "upper_value":
            upper_value,

    }


# ============================================================
# 10. OPERATING REVERSE-DCF ENGINE
# ============================================================

def f6_operating_valuation(
    target,
    assumptions,
    growth_shift,
):

    ttm_revenue = f6_numeric(

        target[
            "ttm_revenue"
        ]

    )


    shares = f6_numeric(

        target.get(
            "valuation_share_units",
            target.get("economic_diluted_shares", np.nan),
        )

    )


    valuation_fx = f6_numeric(

        target.get(
            "financial_to_price_fx",
            1.0,
        )

    )


    net_debt = f6_numeric(

        target[
            "valuation_net_debt"
        ]

    )


    discount_rate = f6_numeric(

        target[
            "discount_rate"
        ]

    )


    exit_multiple = f6_numeric(

        target[
            "base_exit_multiple"
        ]

    )


    if not all(

        pd.notna(
            value
        )

        for value in [

            ttm_revenue,
            shares,
            valuation_fx,
            net_debt,
            discount_rate,
            exit_multiple,

        ]

    ):

        return None


    revenue = (

        ttm_revenue

    )


    explicit_pv = 0.0

    final_fcff = np.nan

    final_ebitda = np.nan

    final_terminal_growth = np.nan


    for _, row in assumptions.iterrows():

        year = int(

            row[
                "forecast_year"
            ]

        )


        revenue_growth = (

            f6_numeric(

                row[
                    "revenue_growth"
                ]

            )

            +
            growth_shift

        )


        if (

            not _f_isfinite(
                revenue_growth
            )

            or

            (
                1.0
                +
                revenue_growth
            )
            <=
            0

        ):

            return None


        ebit_margin = f6_numeric(

            row[
                "ebit_margin"
            ]

        )


        tax_rate = f6_numeric(

            row[
                "tax_rate"
            ]

        )


        da_ratio = f6_numeric(

            row[
                "da_ratio"
            ]

        )


        capex_ratio = f6_numeric(

            row[
                "capex_ratio"
            ]

        )


        nwc_ratio = f6_numeric(

            row[
                "nwc_investment_ratio"
            ]

        )


        terminal_growth = f6_numeric(

            row[
                "terminal_growth"
            ]

        )


        required = [

            ebit_margin,
            tax_rate,
            da_ratio,
            capex_ratio,
            nwc_ratio,
            terminal_growth,

        ]


        if not all(

            _f_isfinite(
                value
            )

            for value in required

        ):

            return None


        prev_revenue = revenue
        revenue = (

            revenue

            *
            (
                1.0
                +
                revenue_growth
            )

        )


        ebit = (

            revenue
            *
            ebit_margin

        )


        nopat = (

            ebit

            *
            (
                1.0
                -
                tax_rate
            )

        )


        da = (

            revenue
            *
            da_ratio

        )


        capex = (

            revenue

            *
            abs(
                capex_ratio
            )

        )


        if F5_NWC_INCREMENTAL:
            # v1.0.14: NWC investment scales with the CHANGE in revenue
            # (intensity per $ of incremental revenue, from history).
            nwc_investment = (
                f5_nwc_incremental_intensity(target["ticker"])
                * (revenue - prev_revenue)
            )
        else:
            nwc_investment = (
                revenue
                *
                nwc_ratio
            )


        fcff = (

            nopat
            +
            da
            -
            capex
            -
            nwc_investment

        )


        ebitda = (

            ebit
            +
            da

        )


        discount_factor = (

            (
                1.0
                +
                discount_rate
            )

            **
            year

        )


        explicit_pv += (

            fcff
            /
            discount_factor

        )


        final_fcff = (
            fcff
        )


        final_ebitda = (
            ebitda
        )


        final_terminal_growth = (
            terminal_growth
        )


    r_minus_g = (

        discount_rate

        -
        final_terminal_growth

    )


    if (

        r_minus_g

        <
        F5_MIN_R_MINUS_G

    ):

        return None


    gordon_terminal_value = (

        final_fcff

        *
        (
            1.0
            +
            final_terminal_growth
        )

        /
        r_minus_g

    )


    exit_terminal_value = (

        final_ebitda

        *
        exit_multiple

    )


    blended_terminal_value = (

        F5_GORDON_WEIGHT

        *
        gordon_terminal_value

        +

        F5_EXIT_MULTIPLE_WEIGHT

        *
        exit_terminal_value

    )


    discount_factor_5 = (

        (
            1.0
            +
            discount_rate
        )

        **
        5

    )


    pv_terminal_value = (

        blended_terminal_value

        /
        discount_factor_5

    )


    enterprise_value = (

        explicit_pv

        +
        pv_terminal_value

    )


    equity_value = (

        enterprise_value

        -
        net_debt

    )


    price = intrinsic_value_per_listed_unit(
        equity_value_financial_currency=equity_value,
        financial_to_price_fx=valuation_fx,
        listed_units=shares,
    )


    return {

        "price":
            price,

        "explicit_pv":
            explicit_pv,

        "final_fcff":
            final_fcff,

        "final_ebitda":
            final_ebitda,

        "terminal_growth":
            final_terminal_growth,

        "gordon_terminal_value":
            gordon_terminal_value,

        "exit_terminal_value":
            exit_terminal_value,

        "blended_terminal_value":
            blended_terminal_value,

        "discount_factor_5":
            discount_factor_5,

        "enterprise_value":
            enterprise_value,

        "equity_value":
            equity_value,

    }


# ============================================================
# 11. FINANCIAL REVERSE-RESIDUAL-INCOME ENGINE
# ============================================================

def f6_financial_valuation(
    target,
    assumptions,
    roe_shift,
):

    current_equity = f6_numeric(

        target[
            "current_equity"
        ]

    )


    shares = f6_numeric(

        target.get(
            "valuation_share_units",
            target.get("economic_diluted_shares", np.nan),
        )

    )


    valuation_fx = f6_numeric(

        target.get(
            "financial_to_price_fx",
            1.0,
        )

    )


    discount_rate = f6_numeric(

        target[
            "discount_rate"
        ]

    )


    exit_multiple = f6_numeric(

        target[
            "base_exit_multiple"
        ]

    )


    terminal_metric = str(

        target[
            "terminal_multiple_metric"
        ]

    )


    if not all(

        pd.notna(
            value
        )

        for value in [

            current_equity,
            shares,
            valuation_fx,
            discount_rate,
            exit_multiple,

        ]

    ):

        return None


    base_roes = pd.to_numeric(

        assumptions[
            "roe"
        ],

        errors="coerce",

    ).to_numpy(
        dtype=float
    )


    earnings_growth = pd.to_numeric(

        assumptions[
            "earnings_growth"
        ],

        errors="coerce",

    ).to_numpy(
        dtype=float
    )


    terminal_growth_array = pd.to_numeric(

        assumptions[
            "terminal_growth"
        ],

        errors="coerce",

    ).to_numpy(
        dtype=float
    )


    adjusted_roes = (

        base_roes

        +
        roe_shift

    )


    if (

        not _f_isfinite(
            adjusted_roes
        ).all()

        or

        (
            adjusted_roes

            <=
            F6_FINANCIAL_ROE_MINIMUM

        ).any()

    ):

        return None


    if (

        not _f_isfinite(
            earnings_growth
        ).all()

        or

        not _f_isfinite(
            terminal_growth_array
        ).all()

    ):

        return None


    beginning_book = (

        current_equity

    )


    explicit_pv_residual_income = (
        0.0
    )


    final_net_income = np.nan

    final_ending_book = np.nan

    final_roe = np.nan

    final_terminal_growth = np.nan


    for i, (_, row) in enumerate(

        assumptions.iterrows()

    ):

        year = int(

            row[
                "forecast_year"
            ]

        )


        roe = float(

            adjusted_roes[i]

        )


        terminal_growth = float(

            terminal_growth_array[i]

        )


        net_income = (

            roe

            *
            beginning_book

        )


        residual_income = (

            net_income

            -
            discount_rate

            *
            beginning_book

        )


        discount_factor = (

            (
                1.0
                +
                discount_rate
            )

            **
            year

        )


        explicit_pv_residual_income += (

            residual_income

            /
            discount_factor

        )


        if i < 4:

            next_roe = float(

                adjusted_roes[
                    i + 1
                ]

            )


            next_growth = float(

                earnings_growth[
                    i + 1
                ]

            )


        else:

            next_roe = (
                roe
            )


            next_growth = (
                terminal_growth
            )


        if (

            next_roe

            <=
            F6_FINANCIAL_ROE_MINIMUM

            or

            (
                1.0
                +
                next_growth
            )
            <=
            0

        ):

            return None


        next_income_target = (

            net_income

            *
            (
                1.0
                +
                next_growth
            )

        )


        ending_book = (

            next_income_target

            /
            next_roe

        )


        if not (

            _f_isfinite(
                ending_book
            )

            and

            ending_book > 0

        ):

            return None


        beginning_book = (
            ending_book
        )


        final_net_income = (
            net_income
        )


        final_ending_book = (
            ending_book
        )


        final_roe = (
            roe
        )


        final_terminal_growth = (
            terminal_growth
        )


    r_minus_g = (

        discount_rate

        -
        final_terminal_growth

    )


    if (

        r_minus_g

        <
        F5_MIN_R_MINUS_G

    ):

        return None


    year6_net_income = (

        final_roe

        *
        final_ending_book

    )


    year6_residual_income = (

        year6_net_income

        -
        discount_rate

        *
        final_ending_book

    )


    gordon_continuation_value = (

        year6_residual_income

        /
        r_minus_g

    )


    if terminal_metric == "PRICE_BOOK":

        exit_equity_value = (

            exit_multiple

            *
            final_ending_book

        )


    elif terminal_metric == "PRICE_EARNINGS":

        exit_equity_value = (

            exit_multiple

            *
            final_net_income

        )


    else:

        return None


    exit_continuation_value = (

        exit_equity_value

        -
        final_ending_book

    )


    blended_continuation_value = (

        F5_GORDON_WEIGHT

        *
        gordon_continuation_value

        +

        F5_EXIT_MULTIPLE_WEIGHT

        *
        exit_continuation_value

    )


    discount_factor_5 = (

        (
            1.0
            +
            discount_rate
        )

        **
        5

    )


    pv_continuation_value = (

        blended_continuation_value

        /
        discount_factor_5

    )


    equity_value = (

        current_equity

        +
        explicit_pv_residual_income

        +
        pv_continuation_value

    )


    price = intrinsic_value_per_listed_unit(
        equity_value_financial_currency=equity_value,
        financial_to_price_fx=valuation_fx,
        listed_units=shares,
    )


    return {

        "price":
            price,

        "current_equity":
            current_equity,

        "explicit_pv_residual_income":
            explicit_pv_residual_income,

        "final_net_income":
            final_net_income,

        "final_ending_book":
            final_ending_book,

        "final_roe":
            final_roe,

        "terminal_growth":
            final_terminal_growth,

        "gordon_continuation_value":
            gordon_continuation_value,

        "exit_equity_value":
            exit_equity_value,

        "exit_continuation_value":
            exit_continuation_value,

        "blended_continuation_value":
            blended_continuation_value,

        "discount_factor_5":
            discount_factor_5,

        "equity_value":
            equity_value,

    }


# ============================================================
# 12. ANALYTICAL MARKET-IMPLIED EXIT MULTIPLE
# ============================================================

def f6_operating_implied_exit_multiple(
    target,
    base_details,
):

    current_price = f6_numeric(

        target[
            "current_price"
        ]

    )


    shares = f6_numeric(

        target.get(
            "valuation_share_units",
            target.get("economic_diluted_shares", np.nan),
        )

    )


    valuation_fx = f6_numeric(

        target.get(
            "financial_to_price_fx",
            1.0,
        )

    )


    net_debt = f6_numeric(

        target[
            "valuation_net_debt"
        ]

    )


    market_equity_value_price_currency = (

        current_price

        *
        shares

    )


    if (
        not _f_isfinite(valuation_fx)
        or valuation_fx <= 0.0
    ):
        return np.nan


    market_equity_value = (
        market_equity_value_price_currency
        / valuation_fx
    )


    target_enterprise_value = (

        market_equity_value

        +
        net_debt

    )


    required_blended_terminal = (

        (
            target_enterprise_value

            -
            base_details[
                "explicit_pv"
            ]
        )

        *
        base_details[
            "discount_factor_5"
        ]

    )


    numerator = (

        required_blended_terminal

        -

        F5_GORDON_WEIGHT

        *
        base_details[
            "gordon_terminal_value"
        ]

    )


    denominator = (

        F5_EXIT_MULTIPLE_WEIGHT

        *
        base_details[
            "final_ebitda"
        ]

    )


    if (

        not _f_isfinite(
            denominator
        )

        or

        abs(
            denominator
        )
        <=
        1e-12

    ):

        return np.nan


    return float(

        numerator
        /
        denominator

    )


def f6_financial_implied_exit_multiple(
    target,
    base_details,
):

    current_price = f6_numeric(

        target[
            "current_price"
        ]

    )


    shares = f6_numeric(

        target.get(
            "valuation_share_units",
            target.get("economic_diluted_shares", np.nan),
        )

    )


    valuation_fx = f6_numeric(

        target.get(
            "financial_to_price_fx",
            1.0,
        )

    )


    terminal_metric = str(

        target[
            "terminal_multiple_metric"
        ]

    )


    if (
        not _f_isfinite(valuation_fx)
        or valuation_fx <= 0.0
    ):
        return np.nan


    target_equity_value = (

        current_price

        *
        shares

        /
        valuation_fx

    )


    required_pv_continuation = (

        target_equity_value

        -
        base_details[
            "current_equity"
        ]

        -
        base_details[
            "explicit_pv_residual_income"
        ]

    )


    required_blended_continuation = (

        required_pv_continuation

        *
        base_details[
            "discount_factor_5"
        ]

    )


    required_exit_continuation = (

        (
            required_blended_continuation

            -

            F5_GORDON_WEIGHT

            *
            base_details[
                "gordon_continuation_value"
            ]
        )

        /
        F5_EXIT_MULTIPLE_WEIGHT

    )


    required_exit_equity_value = (

        required_exit_continuation

        +
        base_details[
            "final_ending_book"
        ]

    )


    if terminal_metric == "PRICE_BOOK":

        denominator = (

            base_details[
                "final_ending_book"
            ]

        )


    elif terminal_metric == "PRICE_EARNINGS":

        denominator = (

            base_details[
                "final_net_income"
            ]

        )


    else:

        return np.nan


    if (

        not _f_isfinite(
            denominator
        )

        or

        abs(
            denominator
        )
        <=
        1e-12

    ):

        return np.nan


    return float(

        required_exit_equity_value

        /
        denominator

    )


# ============================================================
# 13. EXPECTATIONS-GAP DIRECTION
# ============================================================

def f6_expectations_direction(
    current_price,
    base_intrinsic_value,
):

    gap = (

        current_price

        /
        base_intrinsic_value

        -
        1.0

    )


    if gap > F6_NEAR_BASE_PRICE_GAP:

        return (
            "MARKET_PRICES_STRONGER_EXPECTATIONS_THAN_BASE"
        )


    if gap < -F6_NEAR_BASE_PRICE_GAP:

        return (
            "MARKET_PRICES_WEAKER_EXPECTATIONS_THAN_BASE"
        )


    return (
        "MARKET_PRICE_NEAR_BASE_CASE"
    )


# ============================================================
# 14. RUN REVERSE EXPECTATIONS ENGINE
# ============================================================

reverse_rows = []


for _, target in (

    F6_TARGETS
    .sort_values(
        "ticker"
    )
    .iterrows()

):

    ticker = str(

        target[
            "ticker"
        ]

    )


    company_name = (

        target[
            "company_name"
        ]

    )


    execution_model = (

        target[
            "execution_model"
        ]

    )


    current_price = f6_numeric(

        target[
            "current_price"
        ]

    )


    assumptions = (

        f6_base_assumptions(
            ticker
        )

    )


    base_value_row = (

        F6_BASE_VALUES[

            F6_BASE_VALUES[
                "ticker"
            ]
            .astype(str)
            ==
            ticker

        ]

    )


    if len(
        base_value_row
    ) != 1:

        raise RuntimeError(

            f"{ticker}: expected one final BASE valuation row."

        )


    base_intrinsic_value = f6_numeric(

        base_value_row.iloc[0][
            "intrinsic_value_per_share"
        ]

    )


    summary_row = (

        F6_FINAL_SUMMARY[

            F6_FINAL_SUMMARY[
                "ticker"
            ]
            .astype(str)
            ==
            ticker

        ]

    )


    if len(
        summary_row
    ) != 1:

        raise RuntimeError(

            f"{ticker}: expected one final company summary row."

        )


    summary_row = (

        summary_row
        .iloc[0]

    )


    valuation_confidence = f6_numeric(

        summary_row[
            "valuation_confidence"
        ]

    )


    ranking_eligible = bool(

        summary_row[
            "ranking_eligible_after_f5"
        ]

    )


    specialist_status = (

        summary_row[
            "specialist_completion_status"
        ]

    )


    base_exit_multiple = f6_numeric(

        target[
            "base_exit_multiple"
        ]

    )


    terminal_metric = str(

        target[
            "terminal_multiple_metric"
        ]

    )


    # ========================================================
    # OPERATING COMPANIES
    # ========================================================

    if execution_model in F5_OPERATING_MODELS:

        model_type = (
            "OPERATING_REVERSE_DCF"
        )


        driver_name = (
            "REVENUE_GROWTH"
        )


        base_growth_array = pd.to_numeric(

            assumptions[
                "revenue_growth"
            ],

            errors="coerce",

        ).to_numpy(
            dtype=float
        )


        base_driver_level = float(

            np.mean(
                base_growth_array
            )

        )


        base_details = (

            f6_operating_valuation(

                target,
                assumptions,
                0.0,

            )

        )


        if base_details is None:

            raise RuntimeError(

                f"{ticker}: unable to reproduce base "
                "operating valuation."

            )


        reproduced_base_price = float(

            base_details[
                "price"
            ]

        )


        function = lambda delta: (

            (
                f6_operating_valuation(

                    target,
                    assumptions,
                    delta,

                )
                or
                {
                    "price":
                        np.nan
                }

            )[
                "price"
            ]

            -
            current_price

        )


        root_result = (

            f6_find_root(

                function,

                F6_OPERATING_GROWTH_SHIFT_LOWER,
                F6_OPERATING_GROWTH_SHIFT_UPPER,

            )

        )


        driver_shift = (

            root_result[
                "root"
            ]

        )


        if _f_isfinite(
            driver_shift
        ):

            implied_driver_level = (

                base_driver_level

                +
                driver_shift

            )


            solved_details = (

                f6_operating_valuation(

                    target,
                    assumptions,
                    driver_shift,

                )

            )


            solved_price = (

                solved_details[
                    "price"
                ]

            )


            repricing_error = (

                solved_price

                -
                current_price

            )


        else:

            implied_driver_level = np.nan

            solved_price = np.nan

            repricing_error = np.nan


        implied_exit_multiple = (

            f6_operating_implied_exit_multiple(

                target,
                base_details,

            )

        )


        lower_bound = (

            F6_OPERATING_GROWTH_SHIFT_LOWER

        )


        upper_bound = (

            F6_OPERATING_GROWTH_SHIFT_UPPER

        )


    # ========================================================
    # FINANCIAL COMPANIES
    # ========================================================

    elif execution_model in F5_FINANCIAL_MODELS:

        model_type = (
            "FINANCIAL_REVERSE_RESIDUAL_INCOME"
        )


        driver_name = (
            "ROE"
        )


        base_roe_array = pd.to_numeric(

            assumptions[
                "roe"
            ],

            errors="coerce",

        ).to_numpy(
            dtype=float
        )


        base_driver_level = float(

            np.mean(
                base_roe_array
            )

        )


        minimum_base_roe = float(

            np.min(
                base_roe_array
            )

        )


        lower_bound = max(

            -0.50,

            (
                F6_FINANCIAL_ROE_MINIMUM

                -
                minimum_base_roe
            ),

        )


        upper_bound = (

            F6_FINANCIAL_ROE_SHIFT_UPPER

        )


        base_details = (

            f6_financial_valuation(

                target,
                assumptions,
                0.0,

            )

        )


        if base_details is None:

            raise RuntimeError(

                f"{ticker}: unable to reproduce base "
                "financial valuation."

            )


        reproduced_base_price = float(

            base_details[
                "price"
            ]

        )


        function = lambda delta: (

            (
                f6_financial_valuation(

                    target,
                    assumptions,
                    delta,

                )
                or
                {
                    "price":
                        np.nan
                }

            )[
                "price"
            ]

            -
            current_price

        )


        root_result = (

            f6_find_root(

                function,

                lower_bound,
                upper_bound,

            )

        )


        driver_shift = (

            root_result[
                "root"
            ]

        )


        if _f_isfinite(
            driver_shift
        ):

            implied_driver_level = (

                base_driver_level

                +
                driver_shift

            )


            solved_details = (

                f6_financial_valuation(

                    target,
                    assumptions,
                    driver_shift,

                )

            )


            solved_price = (

                solved_details[
                    "price"
                ]

            )


            repricing_error = (

                solved_price

                -
                current_price

            )


        else:

            implied_driver_level = np.nan

            solved_price = np.nan

            repricing_error = np.nan


        implied_exit_multiple = (

            f6_financial_implied_exit_multiple(

                target,
                base_details,

            )

        )


    else:

        raise RuntimeError(

            f"{ticker}: unsupported execution model "
            f"{execution_model}."

        )


    # ========================================================
    # BASE REPRODUCTION ERROR
    # ========================================================

    base_reproduction_error = (

        reproduced_base_price

        -
        base_intrinsic_value

    )


    base_reproduction_error_pct = (

        base_reproduction_error

        /
        base_intrinsic_value

        if abs(
            base_intrinsic_value
        ) > 1e-12

        else np.nan

    )


    # ========================================================
    # MARKET / BASE GAP
    # ========================================================

    market_to_base_ratio = (

        current_price

        /
        base_intrinsic_value

    )


    market_price_gap_vs_base = (

        market_to_base_ratio

        -
        1.0

    )


    expectations_direction = (

        f6_expectations_direction(

            current_price,
            base_intrinsic_value,

        )

    )


    # ========================================================
    # EXIT MULTIPLE GAP
    # ========================================================

    exit_multiple_gap = (

        implied_exit_multiple

        -
        base_exit_multiple

        if (

            _f_isfinite(
                implied_exit_multiple
            )

            and

            _f_isfinite(
                base_exit_multiple
            )

        )

        else np.nan

    )


    exit_multiple_gap_pct = (

        implied_exit_multiple

        /
        base_exit_multiple

        -
        1.0

        if (

            _f_isfinite(
                implied_exit_multiple
            )

            and

            _f_isfinite(
                base_exit_multiple
            )

            and

            abs(
                base_exit_multiple
            ) > 1e-12

        )

        else np.nan

    )


    # ========================================================
    # ROOT CONFIDENCE / INTERPRETATION
    # ========================================================

    root_solved = bool(

        _f_isfinite(
            driver_shift
        )

    )


    if root_solved:

        driver_gap_pp = (

            driver_shift
            *
            100.0

        )


    else:

        driver_gap_pp = np.nan


    reverse_rows.append({

        "ticker":
            ticker,

        "company_name":
            company_name,

        "execution_model":
            execution_model,

        "reverse_model_type":
            model_type,

        "market_implied_driver":
            driver_name,

        "current_price":
            current_price,

        "base_intrinsic_value":
            base_intrinsic_value,

        "reproduced_base_price":
            reproduced_base_price,

        "base_reproduction_error":
            base_reproduction_error,

        "base_reproduction_error_pct":
            base_reproduction_error_pct,

        "market_to_base_ratio":
            market_to_base_ratio,

        "market_price_gap_vs_base":
            market_price_gap_vs_base,

        "expectations_direction":
            expectations_direction,

        "base_driver_level":
            base_driver_level,

        "market_implied_driver_shift":
            driver_shift,

        "market_implied_driver_shift_pp":
            driver_gap_pp,

        "market_implied_driver_level":
            implied_driver_level,

        "driver_search_lower":
            lower_bound,

        "driver_search_upper":
            upper_bound,

        "reverse_driver_status":
            root_result[
                "status"
            ],

        "root_solved":
            root_solved,

        "solved_market_price":
            solved_price,

        "market_repricing_error":
            repricing_error,

        "terminal_multiple_metric":
            terminal_metric,

        "base_exit_multiple":
            base_exit_multiple,

        "market_implied_exit_multiple":
            implied_exit_multiple,

        "exit_multiple_gap":
            exit_multiple_gap,

        "exit_multiple_gap_pct":
            exit_multiple_gap_pct,

        "valuation_confidence":
            valuation_confidence,

        "ranking_eligible_after_f5":
            ranking_eligible,

        "specialist_completion_status":
            specialist_status,

        "valuation_universe_freeze_id":
            VALUATION_UNIVERSE_FREEZE_ID,

    })


F6_REVERSE_EXPECTATIONS = pd.DataFrame(

    reverse_rows

)


