# ==================================================================================================
# HELPER
# ==================================================================================================

def final_f_numeric(
    value,
    default=np.nan,
):

    try:

        output = float(
            value
        )


        if _f_isfinite(
            output
        ):

            return output


    except Exception:

        pass


    return default


# ==================================================================================================
# ==================================================================================================
# F7 — MARKET-IMPLIED EXPECTATIONS NORMALIZATION
# ==================================================================================================
# ==================================================================================================
#
# Purpose:
#
#   Convert F6 reverse-DCF outputs into a standardized expectations-gap signal.
#
#
# Key interpretation:
#
#   Positive signal:
#
#       market price can be justified using assumptions WEAKER
#       than our Base case.
#
#       => favorable expectations gap
#
#
#   Negative signal:
#
#       market price requires assumptions STRONGER
#       than our Base case.
#
#       => demanding expectations
#
#
# Operating:
#
#       signal based on market-implied revenue-growth shift
#
# Financial:
#
#       signal based on market-implied ROE shift
#
#
# Scale:
#
#       Operating:
#           10 percentage-point annual growth shift = 1 signal unit
#
#       Financial:
#           5 percentage-point ROE shift = 1 signal unit
#
#
# Unsolved upper-bound cases:
#
#       signal = -3
#
# because expectations exceed the already-wide search range.
#
#
# Market-implied exit multiples are treated only as diagnostics.
#
# Negative / absurd multiples are explicitly marked
# ECONOMICALLY INFEASIBLE and are never used as valuation inputs.
# ==================================================================================================


F7_VERSION = "1.0.0"


F7_OPERATING_DRIVER_SCALE = 0.10

F7_FINANCIAL_DRIVER_SCALE = 0.05


F7_SIGNAL_MIN = -3.0

F7_SIGNAL_MAX = 3.0


F7_EXPECTATIONS = (

    F6_REVERSE_EXPECTATIONS
    .copy()

)


F7_EXPECTED_COMPANY_COUNT = int(

    F5_FINAL_COMPANY_VALUATION_SUMMARY[
        "ticker"
    ]
    .astype(str)
    .nunique()

)


# ==================================================================================================
# F7.1 — DRIVER SCALE
# ==================================================================================================

F7_EXPECTATIONS[
    "driver_normalization_scale"
] = np.where(

    F7_EXPECTATIONS[
        "market_implied_driver"
    ]
    ==
    "REVENUE_GROWTH",

    F7_OPERATING_DRIVER_SCALE,

    F7_FINANCIAL_DRIVER_SCALE,

)


# ==================================================================================================
# F7.2 — STANDARDIZED EXPECTATIONS SIGNAL
# ==================================================================================================

driver_shift = pd.to_numeric(

    F7_EXPECTATIONS[
        "market_implied_driver_shift"
    ],

    errors="coerce",

)


driver_scale = pd.to_numeric(

    F7_EXPECTATIONS[
        "driver_normalization_scale"
    ],

    errors="coerce",

)


raw_expectations_signal = (

    -
    driver_shift

    /
    driver_scale

)


F7_EXPECTATIONS[
    "expectations_gap_signal"
] = raw_expectations_signal


# ------------------------------------------------------------
# Explicitly encode bounded unsolved cases.
# ------------------------------------------------------------

upper_bound_mask = (

    F7_EXPECTATIONS[
        "reverse_driver_status"
    ]
    ==
    "MARKET_REQUIRES_DRIVER_ABOVE_SEARCH_BOUND"

)


lower_bound_mask = (

    F7_EXPECTATIONS[
        "reverse_driver_status"
    ]
    ==
    "MARKET_REQUIRES_DRIVER_BELOW_SEARCH_BOUND"

)


F7_EXPECTATIONS.loc[

    upper_bound_mask,
    "expectations_gap_signal",

] = F7_SIGNAL_MIN


F7_EXPECTATIONS.loc[

    lower_bound_mask,
    "expectations_gap_signal",

] = F7_SIGNAL_MAX


F7_EXPECTATIONS[
    "expectations_gap_signal"
] = (

    pd.to_numeric(

        F7_EXPECTATIONS[
            "expectations_gap_signal"
        ],

        errors="coerce",

    )

    .clip(

        lower=
            F7_SIGNAL_MIN,

        upper=
            F7_SIGNAL_MAX,

    )

)


# ==================================================================================================
# F7.3 — ROOT RELIABILITY
# ==================================================================================================

F7_EXPECTATIONS[
    "expectations_signal_reliability"
] = np.where(

    F7_EXPECTATIONS[
        "root_solved"
    ],

    1.00,

    0.65,

)


# ==================================================================================================
# F7.4 — MARKET-IMPLIED EXIT-MULTIPLE ECONOMIC PLAUSIBILITY
# ==================================================================================================

F7_TERMINAL_MULTIPLE_BOUNDS = {

    "EV_EBITDA":
        (
            2.0,
            60.0,
        ),

    "PRICE_BOOK":
        (
            0.25,
            12.0,
        ),

    "PRICE_EARNINGS":
        (
            4.0,
            100.0,
        ),

}


economic_flags = []

economic_reasons = []


for _, row in (

    F7_EXPECTATIONS
    .iterrows()

):

    metric = str(

        row[
            "terminal_multiple_metric"
        ]

    )


    implied_multiple = final_f_numeric(

        row[
            "market_implied_exit_multiple"
        ]

    )


    if not _f_isfinite(
        implied_multiple
    ):

        economic_flags.append(
            False
        )


        economic_reasons.append(
            "MISSING"
        )


        continue


    if implied_multiple <= 0:

        economic_flags.append(
            False
        )


        economic_reasons.append(
            "NON_POSITIVE_NOT_ECONOMIC"
        )


        continue


    if metric not in F7_TERMINAL_MULTIPLE_BOUNDS:

        economic_flags.append(
            False
        )


        economic_reasons.append(
            "UNSUPPORTED_METRIC"
        )


        continue


    lower, upper = (

        F7_TERMINAL_MULTIPLE_BOUNDS[
            metric
        ]

    )


    if implied_multiple < lower:

        economic_flags.append(
            False
        )


        economic_reasons.append(
            "BELOW_PLAUSIBILITY_BOUND"
        )


    elif implied_multiple > upper:

        economic_flags.append(
            False
        )


        economic_reasons.append(
            "ABOVE_PLAUSIBILITY_BOUND"
        )


    else:

        economic_flags.append(
            True
        )


        economic_reasons.append(
            "ECONOMICALLY_PLAUSIBLE"
        )


F7_EXPECTATIONS[
    "market_implied_exit_multiple_economic"
] = economic_flags


F7_EXPECTATIONS[
    "market_implied_exit_multiple_reason"
] = economic_reasons


# ==================================================================================================
# F7.5 — EXPECTATIONS CLASSIFICATION
# ==================================================================================================

def f7_expectations_classification(
    signal
):

    if pd.isna(
        signal
    ):

        return "UNAVAILABLE"


    if signal >= 2.0:

        return "MARKET_EXPECTATIONS_MUCH_WEAKER_THAN_BASE"


    if signal >= 0.75:

        return "MARKET_EXPECTATIONS_WEAKER_THAN_BASE"


    if signal > -0.75:

        return "MARKET_EXPECTATIONS_NEAR_BASE"


    if signal > -2.0:

        return "MARKET_EXPECTATIONS_STRONGER_THAN_BASE"


    return "MARKET_EXPECTATIONS_MUCH_STRONGER_THAN_BASE"


F7_EXPECTATIONS[
    "expectations_gap_classification"
] = (

    F7_EXPECTATIONS[
        "expectations_gap_signal"
    ]

    .map(
        f7_expectations_classification
    )

)


# ==================================================================================================
# F7.6 — EXTREME EXPECTATIONS FLAG
# ==================================================================================================

F7_EXPECTATIONS[
    "extreme_market_expectations"
] = (

    F7_EXPECTATIONS[
        "expectations_gap_signal"
    ]
    .abs()

    >=
    2.0

)


# ==================================================================================================
# F7.7 — HEALTH
# ==================================================================================================

F7_COMPANY_COUNT = len(

    F7_EXPECTATIONS

)


F7_FINITE_SIGNAL_COUNT = int(

    _f_isfinite(

        F7_EXPECTATIONS[
            "expectations_gap_signal"
        ]

    )
    .sum()

)


F7_NON_ECONOMIC_EXIT_COUNT = int(

    (

        ~
        F7_EXPECTATIONS[
            "market_implied_exit_multiple_economic"
        ]

    )
    .sum()

)


F7_HEALTH = pd.DataFrame([

    {

        "check":
            "Frozen valuation universe preserved",

        "passed":
            F7_COMPANY_COUNT
            ==
            F7_EXPECTED_COMPANY_COUNT,

        "required":
            True,

        "detail":
            (
                f"companies={F7_COMPANY_COUNT}/"
                f"{F7_EXPECTED_COMPANY_COUNT}"
            ),

    },

    {

        "check":
            "Every company receives expectations-gap signal",

        "passed":
            F7_FINITE_SIGNAL_COUNT
            ==
            F7_COMPANY_COUNT,

        "required":
            True,

        "detail":
            (
                f"coverage="
                f"{F7_FINITE_SIGNAL_COUNT}/"
                f"{F7_COMPANY_COUNT}"
            ),

    },

    {

        "check":
            "Expectations signal remains bounded",

        "passed":
            bool(

                F7_EXPECTATIONS[
                    "expectations_gap_signal"
                ]

                .between(

                    F7_SIGNAL_MIN,
                    F7_SIGNAL_MAX,

                    inclusive="both",

                )

                .all()

            ),

        "required":
            True,

        "detail":
            (
                f"range="
                f"[{F7_EXPECTATIONS['expectations_gap_signal'].min():.3f}, "
                f"{F7_EXPECTATIONS['expectations_gap_signal'].max():.3f}]"
            ),

    },

    {

        "check":
            "Non-economic market-implied multiples explicitly identified",

        "passed":
            True,

        "required":
            False,

        "detail":
            (
                f"non_economic="
                f"{F7_NON_ECONOMIC_EXIT_COUNT}"
            ),

    },

])


F7_HEALTH[
    "status"
] = np.where(

    F7_HEALTH[
        "passed"
    ],

    "✓ PASS",

    np.where(

        F7_HEALTH[
            "required"
        ],

        "✗ FAIL",

        "⚠ WARN",

    )

)


F7_REQUIRED_FAILURES = (

    F7_HEALTH[

        F7_HEALTH[
            "required"
        ]

        &

        ~
        F7_HEALTH[
            "passed"
        ]

    ]

)


F7_PASSED = (

    F7_REQUIRED_FAILURES.empty

)


if not F7_PASSED:

    display(
        F7_REQUIRED_FAILURES
    )


    raise RuntimeError(

        "F7 PRODUCTION GATE FAILED."

    )


